    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
    throwDeferredBodyError(request);
    const account = await accounts.register(request.body, request.ip ?? null);
    return reply.status(201).send(account);
  });

  // ---------------------------------------------------------------------------
  // HU-01-02 — Login (público, 200)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/login', async (request, reply) => {
    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
    const rawEmail =
      typeof request.body === 'object' &&
      request.body !== null &&
      typeof (request.body as Record<string, unknown>).email === 'string'
        ? normalizeEmail((request.body as Record<string, string>).email)
        : '';
    const limiterKey = `${request.ip}|${rawEmail}`;
    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
    // (HU-01-02 RN-8).
    const decision =
      rawEmail === ''
        ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
        : loginFailureLimiter.peek(limiterKey);
    if (decision.limited) {
      audit.record({
        event: 'LOGIN',
        email: rawEmail || null,
        result: 'FAILURE',
        reason: 'RATE_LIMITED',
        origin: request.ip ?? null,
      });
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de intentos de autenticación.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-8).
    throwDeferredBodyError(request);
    try {
      const result = await accounts.login(request.body, request.ip ?? null);
      return reply.status(200).send(result);
    } catch (err) {
      if (err instanceof AppError && err.code === 'INVALID_CREDENTIALS') {
        loginFailureLimiter.record(limiterKey);
      }
      throw err;
    }
  });

  // ---------------------------------------------------------------------------
  // HU-06-04 — Consulta de dirección de depósito (protegido, 200)
  // ---------------------------------------------------------------------------
  app.get('/api/v1/deposit-address', async (request, reply) => {
    // Precedencia (HU-06-04 RN-9): UNAUTHENTICATED → UNAUTHORIZED → esquema/activo →
    // red → asignación/lectura.
    const identity = authenticate(request);
    enforceApiRateLimit(identity.accountId, 'GET /api/v1/deposit-address');
    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
    // VALIDATION_ERROR.
    throwDeferredBodyError(request);

    const query = (request.query ?? {}) as Record<string, unknown>;
    const asset = singleQueryValue(query.asset);
    if (asset === undefined || !SUPPORTED_ASSETS.includes(asset as SupportedAsset)) {
      throw validationError([
        {
          field: 'asset',
          message: `El activo debe ser uno de: ${SUPPORTED_ASSETS.join(', ')}.`,
        },
      ]);
    }

    // La red es implícitamente Sepolia; si la consulta declara otra, se rechaza (RN-4).
    const chainIdParam = singleQueryValue(query.chainId);
    if (chainIdParam !== undefined && chainIdParam.trim() !== CHAIN_ID) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: chainIdParam,
      });
    }
    const networkParam = singleQueryValue(query.network);
    if (networkParam !== undefined && networkParam.trim().toLowerCase() !== NETWORK_NAME) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: networkParam,
      });
    }

    // La identidad sale exclusivamente del token: cualquier selector de cuenta inyectado
    // por query o body se ignora (RN-2).
    const record = wallet.getOrAssign(identity.accountId);

    const body: Record<string, string> = {
      asset,
      address: record.address,
      network: record.network,
      chainId: record.chainId,
      derivationPath: record.derivationPath,
    };
    if (asset === 'USDC') body.tokenAddress = config.usdcContractAddress;
    return reply.status(200).send(body);
  });

  // ---------------------------------------------------------------------------
  // Consulta interna del conjunto de direcciones asignadas (HU-06-03 RN-11).
  // No es pública: requiere `X-Internal-Token` o provenir de loopback.
  // ---------------------------------------------------------------------------
  app.get('/internal/deposit-addresses', async (request, reply) => {
    const token = request.headers['x-internal-token'];
    const isLoopback = ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(request.ip);
    const authorized = config.internalApiToken
      ? token === config.internalApiToken
      : isLoopback;
    if (!authorized) throw new AppError('UNAUTHENTICATED', 'Credencial interna ausente o inválida.');
    throwDeferredBodyError(request);
    return reply.status(200).send({
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      items: wallet.listAll().map((record) => ({
        accountId: record.accountId,
        addressIndex: record.addressIndex,
        address: record.address,
        derivationPath: record.derivationPath,
        network: record.network,
        chainId: record.chainId,
        createdAt: record.createdAt,
      })),
    });
  });

  return app;
}

