/**
 * Superficie HTTP de la API (épica 09, alcance de esta etapa).
 *
 * Contrato: ruta base `/api/v1`, envelope uniforme de error
 * `{ error: { code, message, details? } }`, un solo error por respuesta según la
 * precedencia determinista, y autenticación por token Bearer en los recursos protegidos.
 */
import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from 'fastify';
import { AppError, validationError } from '../core/errors';
import { CHAIN_ID, NETWORK_NAME, type Config } from '../core/config';
import { nowIso } from '../core/time';
import { normalizeEmail } from '../core/validation';
import type { Db } from '../db/index';
import type { AuditLog } from '../core/audit';
import type { AccountService } from '../modules/accounts/service';
import type { SessionService } from '../modules/accounts/sessions';
import type { WalletService } from '../modules/wallet/service';
import { SlidingWindowLimiter } from './rateLimit';

export interface AppDependencies {
  config: Config;
  db: Db;
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

/** Verbos soportados por cada ruta existente (para responder 405 y no 404). */
const ROUTE_METHODS: Record<string, string[]> = {
  '/health': ['GET', 'HEAD'],
  '/api/v1/auth/register': ['POST'],
  '/api/v1/auth/login': ['POST'],
  '/api/v1/deposit-address': ['GET', 'HEAD'],
  '/internal/deposit-addresses': ['GET', 'HEAD'],
};

const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
type SupportedAsset = (typeof SUPPORTED_ASSETS)[number];

function normalizePath(url: string): string {
  const pathname = url.split('?')[0];
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

/**
 * Error de parseo del cuerpo diferido hasta después del paso 0 de la precedencia
 * (rate limiting) y de la autenticación. Se guarda en la request bajo un símbolo propio.
 */
const DEFERRED_BODY_ERROR = Symbol('deferredBodyError');

type RequestWithDeferredError = { [DEFERRED_BODY_ERROR]?: AppError };

function deferBodyError(request: unknown, error: AppError): void {
  (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR] = error;
}

/** Levanta el error de parseo diferido, si lo hubo. */
function throwDeferredBodyError(request: unknown): void {
  const error = (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR];
  if (error) throw error;
}

function singleQueryValue(value: unknown): string | undefined {
  if (value === undefined) return undefined;
  if (Array.isArray(value)) return value.length > 0 ? String(value[value.length - 1]) : undefined;
  return String(value);
}

export function buildApp(deps: AppDependencies): FastifyInstance {
  const { config, accounts, sessions, wallet, audit } = deps;

  const app = Fastify({
    logger: { level: config.logLevel },
    ajv: { customOptions: { allErrors: true } },
  });

  const apiLimiter = new SlidingWindowLimiter(config.apiRateLimit);
  const registerLimiter = new SlidingWindowLimiter(config.registerRateLimit);
  const loginFailureLimiter = new SlidingWindowLimiter(config.loginRateLimit);

  // ---------------------------------------------------------------------------
  // Parseo del cuerpo: cualquier cuerpo se interpreta como JSON. Un cuerpo que no sea
  // JSON válido produce VALIDATION_ERROR (422) — HU-09-01 RN-3.
  //
  // El fallo de parseo NO se emite acá: el parser corre antes que los handlers, y el rate
  // limiting es el **paso 0** de la precedencia, anterior a cualquier validación "incluso
  // la de esquema" (HU-01-01 RN-9/RN-10, HU-01-02 RN-8/RN-9). Por eso el error queda
  // diferido en la request y lo levanta el handler *después* de evaluar el límite y, en los
  // recursos protegidos, después de autenticar (HU-09-02 RN-9 / AT-09-05-04). Para las
  // rutas sin cuerpo ni precedencia propia, el hook `preHandler` de más abajo lo levanta
  // antes del handler, de modo que nunca se ignora en silencio.
  // ---------------------------------------------------------------------------
  app.removeContentTypeParser(['application/json', 'text/plain']);
  app.addContentTypeParser('*', { parseAs: 'string' }, (request, body: string, done) => {
    const contentType = request.headers['content-type'];
    if (contentType && !/json/i.test(contentType)) {
      deferBodyError(
        request,
        validationError([{ field: 'Content-Type', message: 'Se espera application/json.' }]),
      );
      done(null, undefined);
      return;
    }
    if (body === undefined || body === null || body.length === 0) {
      done(null, undefined);
      return;
    }
    try {
      done(null, JSON.parse(body));
    } catch {
      deferBodyError(
        request,
        validationError([{ field: 'body', message: 'El cuerpo no es JSON válido.' }]),
      );
      done(null, undefined);
    }
  });

  // Rutas cuyo handler levanta el error diferido en el punto exacto que le fija su
  // precedencia (después del rate limiting y de la autenticación). Para cualquier otra
  // ruta, la red de seguridad de abajo lo levanta antes del handler, de modo que un cuerpo
  // que no parsea nunca se ignora en silencio.
  const ROUTES_WITH_ORDERED_BODY_CHECK = new Set([
    '/api/v1/auth/register',
    '/api/v1/auth/login',
    '/api/v1/deposit-address',
    '/internal/deposit-addresses',
  ]);
  app.addHook('preHandler', async (request) => {
    if (ROUTES_WITH_ORDERED_BODY_CHECK.has(normalizePath(request.url))) return;
    throwDeferredBodyError(request);
  });

  // ---------------------------------------------------------------------------
  // Manejo uniforme de errores (HU-09-05).
  // ---------------------------------------------------------------------------
  function sendError(reply: FastifyReply, error: AppError): FastifyReply {
    if (error.headers) {
      for (const [name, value] of Object.entries(error.headers)) reply.header(name, value);
    }
    return reply.status(error.httpStatus).send(error.toEnvelope());
  }

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof AppError) {
      return sendError(reply, error);
    }
    const fastifyCode = (error as { code?: string }).code ?? '';
    if (
      fastifyCode.startsWith('FST_ERR_CTP_') ||
      fastifyCode === 'FST_ERR_VALIDATION' ||
      (typeof (error as { statusCode?: number }).statusCode === 'number' &&
        (error as { statusCode: number }).statusCode === 400)
    ) {
      return sendError(
        reply,
        validationError([{ field: 'body', message: 'Cuerpo o parámetros inválidos.' }]),
      );
    }
    // INTERNAL_ERROR no filtra detalles sensibles (HU-09-05 RN-9); el detalle queda en el
    // log del servidor.
    request.log.error({ err: error }, 'error interno no clasificado');
    return sendError(reply, new AppError('INTERNAL_ERROR', 'Error interno del servidor.'));
  });

  app.setNotFoundHandler((request, reply) => {
    const pathname = normalizePath(request.url);
    const allowed = ROUTE_METHODS[pathname];
    if (allowed && !allowed.includes(request.method)) {
      return sendError(
        reply,
        new AppError('METHOD_NOT_ALLOWED', 'Método no permitido sobre la ruta.', {
          method: request.method,
          allowed,
        }),
      );
    }
    return sendError(
      reply,
      new AppError('NOT_FOUND', 'Recurso inexistente.', { resource: 'route', id: pathname }),
    );
  });

  // ---------------------------------------------------------------------------
  // Autenticación (HU-09-02 RN-1..RN-4): se evalúa antes que cualquier validación de
  // esquema o regla de negocio (RN-9).
  // ---------------------------------------------------------------------------
  function authenticate(request: FastifyRequest): { accountId: string } {
    const header = request.headers.authorization;
    if (!header || typeof header !== 'string') throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    // El nombre del esquema es case-insensitive (RFC 7235); el valor del token no.
    const match = /^Bearer[ \t]+(.+)$/i.exec(header.trim());
    if (!match) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    const identity = sessions.resolve(match[1].trim());
    if (!identity) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
    return { accountId: identity.accountId };
  }

  function enforceApiRateLimit(accountId: string, routeKey: string): void {
    const decision = apiLimiter.consume(`${accountId}|${routeKey}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de solicitudes permitido.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
  }

  // ---------------------------------------------------------------------------
  // Health check
  // ---------------------------------------------------------------------------
  app.get('/health', async () => ({
    status: 'ok',
    service: 'cex-backend',
    time: nowIso(),
    network: NETWORK_NAME,
    chainId: CHAIN_ID,
    rpcConfigured: config.ethRpcUrl !== '',
  }));

  // ---------------------------------------------------------------------------
  // HU-01-01 — Registro (público, 201)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/register', async (request, reply) => {
    // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): rate limiting antes de todo.
    const decision = registerLimiter.consume(`${request.ip}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de registros permitido desde este origen.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
    throwDeferredBodyError(request);
    const account = await accounts.register(request.body, request.ip ?? null);
    return reply.status(201).send(account);
  });

  // ---------------------------------------------------------------------------
  // HU-01-02 — Login (público, 200)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/login', async (request, reply) => {
    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
    const rawEmail =
      typeof request.body === 'object' &&
      request.body !== null &&
      typeof (request.body as Record<string, unknown>).email === 'string'
        ? normalizeEmail((request.body as Record<string, string>).email)
        : '';
    const limiterKey = `${request.ip}|${rawEmail}`;
    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
    // (HU-01-02 RN-8).
    const decision =
      rawEmail === ''
        ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
        : loginFailureLimiter.peek(limiterKey);
    if (decision.limited) {
      audit.record({
        event: 'LOGIN',
        email: rawEmail || null,
        result: 'FAILURE',
        reason: 'RATE_LIMITED',
        origin: request.ip ?? null,
      });
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de intentos de autenticación.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-8).
    throwDeferredBodyError(request);
    try {
      const result = await accounts.login(request.body, request.ip ?? null);
      return reply.status(200).send(result);
    } catch (err) {
      if (err instanceof AppError && err.code === 'INVALID_CREDENTIALS') {
        loginFailureLimiter.record(limiterKey);
      }
      throw err;
    }
  });

  // ---------------------------------------------------------------------------
  // HU-06-04 — Consulta de dirección de depósito (protegido, 200)
  // ---------------------------------------------------------------------------
  app.get('/api/v1/deposit-address', async (request, reply) => {
    // Precedencia (HU-06-04 RN-9): UNAUTHENTICATED → UNAUTHORIZED → esquema/activo →
    // red → asignación/lectura.
    const identity = authenticate(request);
    enforceApiRateLimit(identity.accountId, 'GET /api/v1/deposit-address');
    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
    // VALIDATION_ERROR.
    throwDeferredBodyError(request);

    const query = (request.query ?? {}) as Record<string, unknown>;
    const asset = singleQueryValue(query.asset);
    if (asset === undefined || !SUPPORTED_ASSETS.includes(asset as SupportedAsset)) {
      throw validationError([
        {
          field: 'asset',
          message: `El activo debe ser uno de: ${SUPPORTED_ASSETS.join(', ')}.`,
        },
      ]);
    }

    // La red es implícitamente Sepolia; si la consulta declara otra, se rechaza (RN-4).
    const chainIdParam = singleQueryValue(query.chainId);
    if (chainIdParam !== undefined && chainIdParam.trim() !== CHAIN_ID) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: chainIdParam,
      });
    }
    const networkParam = singleQueryValue(query.network);
    if (networkParam !== undefined && networkParam.trim().toLowerCase() !== NETWORK_NAME) {
      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
        expected: CHAIN_ID,
        got: networkParam,
      });
    }

    // La identidad sale exclusivamente del token: cualquier selector de cuenta inyectado
    // por query o body se ignora (RN-2).
    const record = wallet.getOrAssign(identity.accountId);

    const body: Record<string, string> = {
      asset,
      address: record.address,
      network: record.network,
      chainId: record.chainId,
      derivationPath: record.derivationPath,
    };
    if (asset === 'USDC') body.tokenAddress = config.usdcContractAddress;
    return reply.status(200).send(body);
  });

  // ---------------------------------------------------------------------------
  // Consulta interna del conjunto de direcciones asignadas (HU-06-03 RN-11).
  // No es pública: requiere `X-Internal-Token` o provenir de loopback.
  // ---------------------------------------------------------------------------
  app.get('/internal/deposit-addresses', async (request, reply) => {
    const token = request.headers['x-internal-token'];
    const isLoopback = ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(request.ip);
    const authorized = config.internalApiToken
      ? token === config.internalApiToken
      : isLoopback;
    if (!authorized) throw new AppError('UNAUTHENTICATED', 'Credencial interna ausente o inválida.');
    throwDeferredBodyError(request);
    return reply.status(200).send({
      network: NETWORK_NAME,
      chainId: CHAIN_ID,
      items: wallet.listAll().map((record) => ({
        accountId: record.accountId,
        addressIndex: record.addressIndex,
        address: record.address,
        derivationPath: record.derivationPath,
        network: record.network,
        chainId: record.chainId,
        createdAt: record.createdAt,
      })),
    });
  });

  return app;
}

## Criterios de aceptación (DoD)

### Escenario 1: Registro de cuenta [AT-09-01-01]
- Dado un email no registrado y una contraseña válida
- Cuando el cliente hace `POST /api/v1/auth/register` con `{ email, password }` y
  `Content-Type: application/json`
- Entonces la respuesta es **201** con cuerpo `{ accountId, email, status, createdAt }`,
  con `status: "ACTIVE"` (estado inicial de la cuenta, HU-01-01 RN-6)
- Y no se expone la contraseña ni hash alguno en la respuesta

### Escenario 2: Login devuelve token [AT-09-01-02]
- Dado una cuenta registrada
- Cuando el cliente hace `POST /api/v1/auth/login` con credenciales correctas
- Entonces la respuesta es **200** con un token de sesión (string) utilizable como
  `Authorization: Bearer <token>` en endpoints protegidos
- Y con credenciales incorrectas responde `INVALID_CREDENTIALS` (401) sin revelar si el
  email existe

### Escenario 3: Perfil propio [AT-09-01-03]
- Dado un token válido
- Cuando el cliente hace `GET /api/v1/me`
- Entonces la respuesta es **200** con `{ accountId, email, status, createdAt }` de la
  cuenta dueña del token, con `status: "ACTIVE"` (HU-01-04 RN-4)

### Escenario 4: Alta de orden limit (feliz) [AT-09-01-04]
- Dado un token válido y balance suficiente
- Cuando el cliente hace `POST /api/v1/orders` con
  `{ "clientOrderId": "c-1", "symbol": "ETH-USDC", "side": "BUY", "type": "LIMIT",
  "priceMin": "2000500000", "quantityWei": "1000000000000000000" }`
- Entonces la respuesta es **201** con el objeto orden incluyendo `orderId`,
  `status ∈ {OPEN, PARTIALLY_FILLED, FILLED}` (nunca `REJECTED`), `priceMin": "2000500000"`,
  `quantityWei": "1000000000000000000"`, `filledWei`, `feeWei` y `feeUsdcMin` como strings
- Y si la orden quedó `OPEN` sin fills, `filledWei == "0"`, `feeWei == "0"` y
  `feeUsdcMin == "0"`; si tuvo fills, `feeWei` (BUY recibe ETH) acumula la fee y
  `feeUsdcMin == "0"`
- Y todos los montos de la respuesta son strings que matchean `^(0|[1-9][0-9]*)$`

### Escenario 5: Alta de orden market (borde: sin precio) [AT-09-01-05]
- Dado un token válido y liquidez en el lado opuesto
- Cuando el cliente envía `{ clientOrderId, symbol: "ETH-USDC", side: "SELL",
  type: "MARKET", quantityWei: "100000000000000" }` **sin** `priceMin`
====
/**
 * Configuración del backend, leída del entorno y validada al arranque.
 *
 * Una configuración inválida **impide el arranque** (no se inicia el servicio en estado
 * inválido): HU-01-02 RN-3 (rango del TTL) y HU-06-01 RN-6/RN-11 (credencial de cifrado).
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import { isValidChecksumAddress, toChecksumAddress } from '../wallet/hd';

/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
export const CHAIN_ID = '11155111';
export const NETWORK_NAME = 'sepolia';
/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
export const CONFIRMACIONES_REQUERIDAS = 12;

export class ConfigError extends Error {}

export interface RateLimitPolicy {
  enabled: boolean;
  max: number;
  windowSeconds: number;
}

export interface Config {
  host: string;
  port: number;
  databasePath: string;
  /** TTL del token de sesión en segundos; entero en [60, 86400] (HU-01-02 RN-3). */
  sessionTtlSeconds: number;
  /**
   * Credencial de cifrado del seed **tal como viene del entorno**, sin decodificar
   * (HU-06-01 RN-6). Ni su ausencia ni su formato inválido se resuelven acá: ambos casos
   * los decide el provisioning, que es el único punto donde se distingue "no hay seed
   * todavía" (`VALIDATION_ERROR`) de "hay un seed persistido que no se puede descifrar"
   * (`INTERNAL_ERROR`, AT-06-01-11) — la credencial ausente **o incorrecta** sobre un seed
   * ya persistido aborta siempre con `INTERNAL_ERROR`.
   */
  walletEncryptionKeyRaw?: string;
  /** Mnemonic importado por configuración (opcional); si falta, se genera uno nuevo. */
  walletMnemonic?: string;
  walletMnemonicPassphrase: string;
  /** Dirección del contrato USDC-mock del entorno (checksum EIP-55). */
  usdcContractAddress: string;
  /** Endpoint JSON-RPC de Sepolia (opcional en esta etapa; sin default de terceros). */
  ethRpcUrl: string;
  /** Rate limit por cuenta y endpoint para endpoints autenticados (HU-09-02 RN-12). */
  apiRateLimit: RateLimitPolicy;
  /** Anti-flood del registro (HU-01-01 RN-10); desactivado salvo configuración explícita. */
  registerRateLimit: RateLimitPolicy;
  /** Anti-fuerza-bruta del login sobre intentos fallidos (HU-01-02 RN-9). */
  loginRateLimit: RateLimitPolicy;
  /** Token para las rutas internas (`/internal/*`); si falta, sólo se admite loopback. */
  internalApiToken?: string;
  logLevel: string;
}

function readEnvFile(file: string): void {
  if (!fs.existsSync(file)) return;
  const content = fs.readFileSync(file, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"') && value.length >= 2) ||
      (value.startsWith("'") && value.endsWith("'") && value.length >= 2)
    ) {
      value = value.slice(1, -1);
    }
    if (process.env[key] === undefined) process.env[key] = value;
  }
}

function parseIntStrict(value: string, name: string): number {
  if (!/^-?\d+$/.test(value.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${value}".`);
  }
  return Number.parseInt(value.trim(), 10);
}

function parseBool(value: string | undefined, fallback: boolean): boolean {
  if (value === undefined || value.trim() === '') return fallback;
  const v = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(v)) return true;
  if (['0', 'false', 'no', 'off'].includes(v)) return false;
  throw new ConfigError(`Valor booleano inválido: "${value}".`);
}

/** Credencial de cifrado con formato/longitud inválidos (la clasifica el provisioning). */
export class EncryptionKeyFormatError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EncryptionKeyFormatError';
  }
}

/**
 * Decodifica la credencial AES-256-GCM del entorno (64 hex, con o sin `0x`, o base64 de 32
 * bytes). El mensaje de error nunca incluye el valor recibido (HU-06-01 RN-5).
 */
export function decodeEncryptionKey(raw: string): Buffer {
  const value = raw.trim();
  let buf: Buffer;
  if (/^(0x)?[0-9a-fA-F]{64}$/.test(value)) {
    buf = Buffer.from(value.replace(/^0x/, ''), 'hex');
  } else {
    buf = Buffer.from(value, 'base64');
  }
  if (buf.length !== 32) {
    throw new EncryptionKeyFormatError(
      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (64 hex o 44 caracteres base64). ' +
        'Podés generar una con: npm run genkey',
    );
  }
  return buf;
}

function rateLimitFrom(
  env: NodeJS.ProcessEnv,
  enabledVar: string,
  maxVar: string,
  windowVar: string,
  defaults: RateLimitPolicy,
  /**
   * `true` para las políticas **opcionales** de la épica 01: cuando se activan, umbral y
   * ventana son obligatorios y deben estar declarados en el entorno (HU-01-01 RN-10,
   * HU-01-02 RN-9); activarlas sin declararlos impide el arranque en vez de caer en
   * defaults silenciosos. `false` para el límite de HU-09-02 RN-12, cuyos parámetros
   * (60 req / 60 s por cuenta y endpoint) los fija la propia spec.
   */
  parametersRequiredWhenEnabled: boolean,
): RateLimitPolicy {
  const enabled = parseBool(env[enabledVar], defaults.enabled);
  if (!enabled) return { enabled: false, max: defaults.max, windowSeconds: defaults.windowSeconds };
  const rawMax = env[maxVar];
  const rawWindow = env[windowVar];
  const declaredMax = rawMax !== undefined && rawMax.trim() !== '';
  const declaredWindow = rawWindow !== undefined && rawWindow.trim() !== '';
  if (parametersRequiredWhenEnabled && (!declaredMax || !declaredWindow)) {
    const faltantes = [!declaredMax ? maxVar : null, !declaredWindow ? windowVar : null]
      .filter((name): name is string => name !== null)
      .join(' y ');
    throw new ConfigError(
      `Con ${enabledVar}=true, el umbral y la ventana del rate limiting son obligatorios y ` +
        `deben estar declarados en el entorno; falta declarar ${faltantes}.`,
    );
  }
  const max = declaredMax ? parseIntStrict(rawMax as string, maxVar) : defaults.max;
  const windowSeconds = declaredWindow
    ? parseIntStrict(rawWindow as string, windowVar)
    : defaults.windowSeconds;
  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
  return { enabled: true, max, windowSeconds };
}

/**
 * Normaliza la dirección del contrato USDC del entorno a `0x` + 40 hex con checksum EIP-55
 * (HU-09-01 RN-10 / HU-06-04 RN-6): es el valor que se emite como `tokenAddress`.
 *
 * - Formato inválido (no son 40 hex con prefijo `0x`) ⇒ no se arranca.
 * - Caja mixta ⇒ debe traer un checksum EIP-55 correcto; si no coincide, se trata como
 *   error de tipeo y no se arranca.
 * - Toda en minúsculas o toda en mayúsculas (formas "sin checksum" según EIP-55) ⇒ se
 *   normaliza a la forma con checksum.
 */
export function normalizeContractAddress(raw: string, name: string): string {
  const value = raw.trim();
  if (!/^0x[0-9a-fA-F]{40}$/.test(value)) {
    throw new ConfigError(
      `${name} debe ser una dirección Ethereum: "0x" seguido de 40 dígitos hexadecimales; ` +
        `se recibió "${value}".`,
    );
  }
  const body = value.slice(2);
  const hasMixedCase = body !== body.toLowerCase() && body !== body.toUpperCase();
  if (hasMixedCase && !isValidChecksumAddress(value)) {
    throw new ConfigError(
      `${name} tiene caja mixta pero su checksum EIP-55 no verifica; ` +
        `la forma correcta de esa dirección es ${toChecksumAddress(value)}.`,
    );
  }
  return toChecksumAddress(value);
}

/**
 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
 * `USDC_CONTRACT_ADDRESS`.
 */
export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  if (parseBool(env.LOAD_DOTENV, true)) {
    readEnvFile(path.resolve(process.cwd(), '.env'));
  }

  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');

  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
    : 3600;
  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
    throw new ConfigError(
      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
    );
  }

  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
  if (chainIdEnv !== CHAIN_ID) {
    throw new ConfigError(
      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
    );
  }

  return {
    host: env.HOST?.trim() || '0.0.0.0',
    port,
    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
    sessionTtlSeconds,
    walletEncryptionKeyRaw: env.WALLET_ENCRYPTION_KEY,
    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
    usdcContractAddress: normalizeContractAddress(
      env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
      'USDC_CONTRACT_ADDRESS',
    ),
    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
    apiRateLimit: rateLimitFrom(
      env,
      'API_RATE_LIMIT_ENABLED',
      'API_RATE_LIMIT_MAX',
      'API_RATE_LIMIT_WINDOW_SECONDS',
      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
      { enabled: true, max: 60, windowSeconds: 60 },
      false,
    ),
    registerRateLimit: rateLimitFrom(
      env,
      'REGISTER_RATE_LIMIT_ENABLED',
      'REGISTER_RATE_LIMIT_MAX',
      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
      { enabled: false, max: 20, windowSeconds: 60 },
      true,
    ),
    loginRateLimit: rateLimitFrom(
      env,
      'LOGIN_RATE_LIMIT_ENABLED',
      'LOGIN_RATE_LIMIT_MAX_FAILURES',
      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
      { enabled: false, max: 5, windowSeconds: 60 },
      true,
    ),
    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
    logLevel: env.LOG_LEVEL?.trim() || 'info',
  };
}

/**
 * Servicio de cuentas: registro (HU-01-01) e inicio de sesión (HU-01-02).
 *
 * Las precedencias de validación son deterministas y se reporta **un solo error** por
 * respuesta (RNE-7 / modelo-de-errores.md §4).
 */
import { randomUUID } from 'node:crypto';
import { AppError, validationError, type ValidationIssue } from '../../core/errors';
