function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Paso 1 de la precedencia: esquema/tipos/campos requeridos/campos desconocidos
 * (HU-01-01 RN-4/RN-9).
 */
export function parseRegisterPayload(body: unknown): { email: string; password: string } {
  if (!isPlainObject(body)) {
    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
  }
  const issues: ValidationIssue[] = [];
  const allowed = new Set(['email', 'password']);
  for (const key of Object.keys(body)) {
    if (!allowed.has(key)) {
      issues.push({ field: key, message: 'Campo desconocido.' });
    }
  }
  if (!('email' in body)) {
    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
  } else if (typeof body.email !== 'string') {
    issues.push({ field: 'email', message: 'Debe ser un string.' });
  }
  if (!('password' in body)) {
    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
  } else if (typeof body.password !== 'string') {
    issues.push({ field: 'password', message: 'Debe ser un string.' });
  }
  if (issues.length > 0) throw validationError(issues);
  return { email: body.email as string, password: body.password as string };
}

/** Paso 1 del login: sólo tipos (HU-01-02 RN-7/RN-11: no se valida el formato del email). */
export function parseLoginPayload(body: unknown): { email: string; password: string } {
  if (!isPlainObject(body)) {
    throw validationError([{ field: 'body', message: 'El cuerpo debe ser un objeto JSON.' }]);
  }
  const issues: ValidationIssue[] = [];
  if (!('email' in body)) {
    issues.push({ field: 'email', message: 'Campo requerido faltante.' });
  } else if (typeof body.email !== 'string') {
    issues.push({ field: 'email', message: 'Debe ser un string.' });
  }
  if (!('password' in body)) {
    issues.push({ field: 'password', message: 'Campo requerido faltante.' });
  } else if (typeof body.password !== 'string') {
    issues.push({ field: 'password', message: 'Debe ser un string.' });
  }
  if (issues.length > 0) throw validationError(issues);
  return { email: body.email as string, password: body.password as string };
}

export class AccountService {
  private readonly accounts: AccountRepository;

  constructor(
    private readonly db: Db,
    private readonly sessions: SessionService,
    private readonly audit: AuditLog,
    private readonly addressAssigner: DepositAddressAssigner,
  ) {
    this.accounts = new AccountRepository(db);
  }

  get repository(): AccountRepository {
    return this.accounts;
  }

  /** HU-01-01: alta de cuenta. Devuelve la proyección pública (sin secretos). */
  async register(body: unknown, origin: string | null): Promise<AccountView> {
    // Paso 1: esquema.
    const payload = parseRegisterPayload(body);
    // Paso 2: formato de email (sobre el email normalizado, RN-1/RN-2).
    const email = normalizeEmail(payload.email);
    if (!isValidEmailFormat(email)) {
      this.audit.record({
        event: 'REGISTER',
        email,
        result: 'FAILURE',
        reason: 'VALIDATION_ERROR',
        origin,
      });
      throw validationError([
        {
          field: 'email',
          message: `Formato de email inválido o de más de ${EMAIL_MAX_LENGTH} caracteres.`,
        },
      ]);
    }
    // Paso 3: política de contraseña. El rango es de **caracteres** (RN-3), por lo que se
    // cuentan code points y no unidades UTF-16.
    const passwordLength = characterLength(payload.password);
    if (passwordLength < PASSWORD_MIN_LENGTH || passwordLength > PASSWORD_MAX_LENGTH) {
      this.audit.record({
        event: 'REGISTER',
        email,
        result: 'FAILURE',
        reason: 'VALIDATION_ERROR',
        origin,
      });
      throw validationError([
        {
          field: 'password',
          message: `La contraseña debe tener entre ${PASSWORD_MIN_LENGTH} y ${PASSWORD_MAX_LENGTH} caracteres.`,
        },
      ]);
    }

    const passwordHash = await hashPassword(payload.password);
    const account: AccountView & { passwordHash: string } = {
      accountId: randomUUID(), // opaco, no secuencial, 122 bits de entropía (RN-6 / RNE-6)
      email,
      status: 'ACTIVE',
      createdAt: nowIso(),
      passwordHash,
    };

    // Paso 4: unicidad. La restricción UNIQUE de la base resuelve también el caso
    // concurrente (RN-8): a lo sumo una inserción prospera.
    try {
      transaction(this.db, () => {
        this.accounts.insert({
          accountId: account.accountId,
          email: account.email,
          passwordHash,
          status: account.status,
          createdAt: account.createdAt,
        });
        this.accounts.insertInitialBalances(account.accountId);
        // Asignación eager de la dirección de depósito (HU-06-03 RN-12), en la misma
        // transacción: no existe una cuenta sin dirección observable.
        this.addressAssigner.assignForAccountInTransaction(account.accountId);
      });
    } catch (err) {
      if (isUniqueConstraintError(err)) {
        this.audit.record({
          event: 'REGISTER',
          email,
          result: 'FAILURE',
          reason: 'EMAIL_ALREADY_EXISTS',
          origin,
        });
        throw new AppError('EMAIL_ALREADY_EXISTS', 'Ya existe una cuenta con ese email.', {
          email,
        });
      }
      throw err;
    }

    this.addressAssigner.publishPendingEvents();
    this.audit.record({ event: 'REGISTER', email, result: 'SUCCESS', origin });

    return {
      accountId: account.accountId,
      email: account.email,
      status: account.status,
      createdAt: account.createdAt,
    };
  }

  /** HU-01-02: verificación de credenciales y emisión del token de sesión. */
  async login(body: unknown, origin: string | null): Promise<LoginResult> {
    // Paso 1: esquema (sin validar el formato del email — RN-11).
    const payload = parseLoginPayload(body);
    const email = normalizeEmail(payload.email);
    const account = this.accounts.findByEmail(email);

    let ok = false;
    if (account) {
      ok = await verifyPassword(payload.password, account.passwordHash);
    } else {
      // Email inexistente: se ejecuta un KDF dummy de coste equivalente para que la
      // latencia no permita enumerar cuentas (RN-12 / RNE-3).
      await dummyVerify(payload.password);
    }

    if (!account || !ok) {
      this.audit.record({
        event: 'LOGIN',
        email,
        result: 'FAILURE',
        reason: 'INVALID_CREDENTIALS',
        origin,
      });
      // Respuesta idéntica tanto si el email no existe como si la contraseña es
      // incorrecta, y sin `details` discriminante (RN-2).
      throw new AppError('INVALID_CREDENTIALS', 'Credenciales inválidas.');
    }

    const session = this.sessions.issue(account.accountId);
    this.audit.record({ event: 'LOGIN', email, result: 'SUCCESS', origin });
    return { token: session.token, tokenType: 'Bearer', expiresAt: session.expiresAt };
  }
}
=====SESSIONS
/**
 * Sesiones: emisión y validación del token Bearer (HU-01-02 RN-3/RN-5/RN-6, HU-09-02).
 *
 * El token es **opaco**: 32 bytes (256 bits) del CSPRNG del sistema
 * (`crypto.randomBytes`), codificados en base64url. No deriva del email ni del
 * `accountId` y no los contiene (AT-01-02-10). En la base sólo se guarda su
 * **hash SHA-256**, de modo que el secreto no queda en reposo en claro.
 */
import { createHash, randomBytes } from 'node:crypto';
import type { Db } from '../../db/index';
import { isoFromEpochMs, nowIso } from '../../core/time';

const TOKEN_BYTES = 32; // 256 bits >= 128 bits exigidos por HU-01-02 RN-3

export interface IssuedSession {
  token: string;
  expiresAt: string;
}

export interface SessionIdentity {
  accountId: string;
  expiresAt: string;
}

export function hashToken(token: string): string {
  return createHash('sha256').update(token, 'utf8').digest('hex');
}

export class SessionService {
  constructor(private readonly db: Db, private readonly ttlSeconds: number) {}

  issue(accountId: string, now = Date.now()): IssuedSession {
    const token = randomBytes(TOKEN_BYTES).toString('base64url');
    const expiresAt = isoFromEpochMs(now + this.ttlSeconds * 1000);
    this.db
      .prepare(
        'INSERT INTO sessions (token_hash, account_id, created_at, expires_at, revoked_at) VALUES (?, ?, ?, ?, NULL)',
      )
      .run(hashToken(token), accountId, isoFromEpochMs(now), expiresAt);
    return { token, expiresAt };
  }

  /** Devuelve la identidad si el token es válido y no expiró/revocó; `null` en otro caso. */
  resolve(token: string, now = Date.now()): SessionIdentity | null {
    const row = this.db
      .prepare(
        'SELECT account_id AS accountId, expires_at AS expiresAt, revoked_at AS revokedAt FROM sessions WHERE token_hash = ?',
      )
      .get(hashToken(token)) as
      | { accountId: string; expiresAt: string; revokedAt: string | null }
      | undefined;
    if (!row) return null;
    if (row.revokedAt !== null) return null;
    if (Date.parse(row.expiresAt) <= now) return null;
    return { accountId: row.accountId, expiresAt: row.expiresAt };
  }

  /** Cantidad de sesiones vivas de una cuenta (uso interno / tests). */
  activeCount(accountId: string, now = Date.now()): number {
    const rows = this.db
      .prepare('SELECT expires_at AS expiresAt, revoked_at AS revokedAt FROM sessions WHERE account_id = ?')
      .all(accountId) as unknown as { expiresAt: string; revokedAt: string | null }[];
    return rows.filter((r) => r.revokedAt === null && Date.parse(r.expiresAt) > now).length;
  }

  purgeExpired(now = Date.now()): void {
    this.db.prepare('DELETE FROM sessions WHERE expires_at <= ?').run(isoFromEpochMs(now));
  }

  get ttl(): number {
    return this.ttlSeconds;
  }

  get issuedAtIso(): string {
    return nowIso();
  }
}

/** Acceso a datos de cuentas (HU-01-01). */
import type { Db } from '../../db/index';

export interface AccountRow {
  accountId: string;
  email: string;
  passwordHash: string;
  status: string;
  createdAt: string;
}

export const ASSETS = ['ETH', 'USDC'] as const;
export type Asset = (typeof ASSETS)[number];

export class AccountRepository {
  constructor(private readonly db: Db) {}

  findByEmail(normalizedEmail: string): AccountRow | undefined {
    return this.db
      .prepare(
        'SELECT account_id AS accountId, email, password_hash AS passwordHash, status, created_at AS createdAt FROM accounts WHERE email = ?',
      )
      .get(normalizedEmail) as AccountRow | undefined;
  }

  findById(accountId: string): AccountRow | undefined {
    return this.db
      .prepare(
        'SELECT account_id AS accountId, email, password_hash AS passwordHash, status, created_at AS createdAt FROM accounts WHERE account_id = ?',
      )
      .get(accountId) as AccountRow | undefined;
  }

  exists(accountId: string): boolean {
    return this.findById(accountId) !== undefined;
  }

  /** Inserta la cuenta. Lanza si el email ya existe (UNIQUE), lo que resuelve RN-8. */
  insert(row: AccountRow): void {
    this.db
      .prepare(
        'INSERT INTO accounts (account_id, email, password_hash, status, created_at) VALUES (?, ?, ?, ?, ?)',
      )
      .run(row.accountId, row.email, row.passwordHash, row.status, row.createdAt);
  }

  /** Estado inicial de balances: disponible "0" y bloqueado "0" por activo (HU-01-01 RN-6). */
  insertInitialBalances(accountId: string): void {
    const stmt = this.db.prepare(
      "INSERT INTO account_balances (account_id, asset, available, locked) VALUES (?, ?, '0', '0')",
    );
    for (const asset of ASSETS) stmt.run(accountId, asset);
  }

  /** Lectura interna del estado de balances (no hay superficie HTTP en esta etapa). */
  balancesOf(accountId: string): { asset: string; available: string; locked: string }[] {
    return this.db
      .prepare('SELECT asset, available, locked FROM account_balances WHERE account_id = ? ORDER BY asset')
      .all(accountId) as unknown as { asset: string; available: string; locked: string }[];
  }
}
====HELPERS
/**
 * Helper compartido por los tests de aceptación: levanta una instancia real del backend
 * (base SQLite en un directorio temporal + wallet HD provisionada) y expone utilidades
 * para inyectar requests HTTP con `app.inject()` (sin abrir un puerto).
 */
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { randomBytes } from 'node:crypto';
import type { FastifyInstance, InjectOptions } from 'fastify';
import { loadConfig, type Config } from '../../src/core/config';
import { bootstrap, type BootstrappedApp } from '../../src/bootstrap';

export interface TestApp extends BootstrappedApp {
  config: Config;
  dbPath: string;
  encryptionKey: string;
  /** Cierra la app y borra el directorio temporal. */
  cleanup(): Promise<void>;
}

export function makeEnv(overrides: Record<string, string> = {}): NodeJS.ProcessEnv {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cex-test-'));
  return {
    LOAD_DOTENV: 'false',
    WALLET_ENCRYPTION_KEY: randomBytes(32).toString('hex'),
    DATABASE_PATH: path.join(dir, 'exchange.db'),
    LOG_LEVEL: 'silent',
    ...overrides,
  };
}

/** Levanta una app de test. `env` permite sobreescribir cualquier variable de entorno. */
export function createTestApp(overrides: Record<string, string> = {}): TestApp {
  const env = makeEnv(overrides);
  const config = loadConfig(env);
  const booted = bootstrap(config);
  return {
    ...booted,
    config,
    dbPath: config.databasePath,
    encryptionKey: env.WALLET_ENCRYPTION_KEY as string,
    async cleanup() {
      await booted.close();
      fs.rmSync(path.dirname(config.databasePath), { recursive: true, force: true });
    },
  };
}

/** Reabre una app sobre la MISMA base y clave (simula un reinicio del proceso). */
export function restartTestApp(previous: TestApp, overrides: Record<string, string> = {}): TestApp {
  const env = {
    LOAD_DOTENV: 'false',
    WALLET_ENCRYPTION_KEY: previous.encryptionKey,
    DATABASE_PATH: previous.dbPath,
    LOG_LEVEL: 'silent',
    ...overrides,
  } as NodeJS.ProcessEnv;
  const config = loadConfig(env);
  const booted = bootstrap(config);
  return {
    ...booted,
    config,
    dbPath: previous.dbPath,
    encryptionKey: previous.encryptionKey,
    async cleanup() {
      await booted.close();
      fs.rmSync(path.dirname(previous.dbPath), { recursive: true, force: true });
    },
  };
}

export const VALID_PASSWORD = 'Sup3rSecreta';

export async function post(
  app: FastifyInstance,
  url: string,
  payload: unknown,
  options: InjectOptions = {},
) {
  return app.inject({
    method: 'POST',
    url,
    payload: payload === undefined ? undefined : JSON.stringify(payload),
    headers: { 'content-type': 'application/json', ...(options.headers ?? {}) },
    ...options,
  });
}

export async function get(app: FastifyInstance, url: string, token?: string, options: InjectOptions = {}) {
  return app.inject({
    method: 'GET',
    url,
    headers: {
      ...(token ? { authorization: `Bearer ${token}` } : {}),
      ...(options.headers ?? {}),
    },
    ...options,
  });
}

export async function registerAccount(
  app: FastifyInstance,
  email: string,
  password: string = VALID_PASSWORD,
) {
  const response = await post(app, '/api/v1/auth/register', { email, password });
  if (response.statusCode !== 201) {
    throw new Error(`registro inesperado (${response.statusCode}): ${response.body}`);
  }
  return response.json() as { accountId: string; email: string; status: string; createdAt: string };
}

export async function loginToken(
  app: FastifyInstance,
  email: string,
  password: string = VALID_PASSWORD,
): Promise<string> {
  const response = await post(app, '/api/v1/auth/login', { email, password });
  if (response.statusCode !== 200) {
    throw new Error(`login inesperado (${response.statusCode}): ${response.body}`);
  }
  return (response.json() as { token: string }).token;
}

let emailCounter = 0;
export function uniqueEmail(prefix = 'trader'): string {
  emailCounter += 1;
  return `${prefix}-${process.pid}-${emailCounter}-${randomBytes(4).toString('hex')}@example.com`;
}
