cat > src/api/errors.ts <<'EOF'
/**
 * Catálogo de errores de la API y derivación de los mensajes que ve el usuario.
 *
 * Fuente de verdad: `spec/00-fundaciones/modelo-de-errores.md` y
 * `spec/09-api-http-websocket/HU-09-05-modelo-de-errores-api.md`.
 *
 * Regla central (épica 10 RNE-3 / HU-10-01 RN-10): **todo error se discrimina por su
 * `code`**, nunca por el `message` del servidor. El `message` que llega en el envelope
 * está orientado a diagnóstico y su literal no es estable: no se muestra en la UI, para no
 * acoplarse a él y para no filtrar detalle del error (HU-10-01 RN-8).
 */

/** Códigos del catálogo (espacio de nombres plano y cerrado, §3 del modelo de errores). */
export const ERROR_CODES = [
  // 3.1 Autenticación y autorización
  'UNAUTHENTICATED',
  'UNAUTHORIZED',
  'RATE_LIMITED',
  // 3.2 Validación general
  'VALIDATION_ERROR',
  'NOT_FOUND',
  'METHOD_NOT_ALLOWED',
  // 3.3 Trading: validación de órdenes
  'INVALID_PRICE_TICK',
  'INVALID_LOT_SIZE',
  'BELOW_MIN_NOTIONAL',
  'INVALID_SIDE',
  'INVALID_ORDER_TYPE',
  'PRICE_REQUIRED',
  'PRICE_NOT_ALLOWED',
  // 3.4 Trading: estado y ejecución
  'INSUFFICIENT_FUNDS',
  'ORDER_NOT_FOUND',
  'ORDER_NOT_CANCELLABLE',
  'SELF_TRADE_BLOCKED',
  'MARKET_NO_LIQUIDITY',
  'MARKET_BUDGET_INSUFFICIENT',
  'DUPLICATE_CLIENT_ORDER_ID',
  // 3.5 On-chain
  'INVALID_ADDRESS',
  'WITHDRAWAL_BELOW_MIN',
  'WITHDRAWAL_AMOUNT_INVALID',
  'DEPOSIT_ALREADY_CREDITED',
  'DEPOSIT_NOT_CONFIRMED',
  'CHAIN_ID_MISMATCH',
  'NONCE_CONFLICT',
  'BROADCAST_FAILED',
  // 3.6 Cuentas
  'EMAIL_ALREADY_EXISTS',
  'INVALID_CREDENTIALS',
  'ACCOUNT_NOT_FOUND',
  // 3.7 Genéricos / sistema
  'CONFLICT',
  'INTERNAL_ERROR',
] as const;

export type ErrorCode = (typeof ERROR_CODES)[number];

export function isErrorCode(value: unknown): value is ErrorCode {
  return typeof value === 'string' && (ERROR_CODES as readonly string[]).includes(value);
}

/** Una causa de fallo de esquema, tal como viaja en `details.issues` (HU-10-01 RN-5). */
export interface ValidationIssue {
  field: string;
  message: string;
}

/**
 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
 *
 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
 * `code` (RN-10) y así ningún detalle del error del backend puede terminar en pantalla
 * (RN-8).
 */
export class ApiError extends Error {
  readonly code: ErrorCode | string;
  readonly httpStatus: number;
  readonly details: Record<string, unknown> | undefined;

  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
    super(`ApiError(${code})`);
    this.name = 'ApiError';
    this.code = code;
    this.httpStatus = httpStatus;
    this.details = details;
  }

  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
  get issues(): ValidationIssue[] {
    const raw = this.details?.issues;
    if (!Array.isArray(raw)) return [];
    const issues: ValidationIssue[] = [];
    for (const item of raw) {
      if (typeof item === 'string') {
        issues.push({ field: '', message: item });
        continue;
      }
      if (typeof item !== 'object' || item === null) continue;
      const record = item as Record<string, unknown>;
      const field = record.field ?? record.path ?? record.name ?? '';
      const message = record.message ?? record.msg ?? '';
      issues.push({
        field: typeof field === 'string' ? field : String(field),
        message: typeof message === 'string' ? message : '',
      });
    }
    return issues;
  }

  /**
   * `details.retryAfterSeconds` de `RATE_LIMITED`. Es un **conteo** y viaja como entero
   * JSON, no como string (HU-10-01, escenario 6). Devuelve `null` si no vino un entero
   * no negativo.
   */
  get retryAfterSeconds(): number | null {
    const raw = this.details?.retryAfterSeconds;
    if (typeof raw !== 'number' || !Number.isInteger(raw) || raw < 0) return null;
    return raw;
  }
}

/**
 * Fallo que impide obtener una respuesta de dominio: el servidor no fue alcanzable, la
 * conexión se cortó, o la respuesta no trae un envelope de error del catálogo. Se muestra
 * con el mismo mensaje no técnico que `INTERNAL_ERROR` (HU-10-01 RN-8).
 */
export class NetworkError extends Error {
  constructor() {
    super('NetworkError');
    this.name = 'NetworkError';
  }
}

/** Mensaje no técnico y sin detalle sensible para el fallo de red / 500 (RN-8). */
export const CONNECTION_ERROR_MESSAGE = 'No se pudo conectar, reintentá';

/** Mensaje genérico de credenciales, que no revela si el email existe (RN-4). */
export const INVALID_CREDENTIALS_MESSAGE = 'Email o contraseña incorrectos';

