test('AT-01-04-04 (error): token expirado por TTL o inexistente ⇒ UNAUTHENTICATED (401)', async () => {
  // TTL mínimo admitido por HU-01-02 RN-3; se vence la sesión en la base para no esperar.
  const { ctx, account, token } = await authedApp({ SESSION_TTL_SECONDS: '60' });
  try {
    const vigente = await get(ctx.app, ME_URL, token);
    assert.equal(vigente.statusCode, 200, 'el token debía ser válido antes de expirar');

    ctx.db
      .prepare('UPDATE sessions SET expires_at = ? WHERE account_id = ?')
      .run(new Date(Date.now() - 1000).toISOString(), account.accountId);
    const expirado = await get(ctx.app, ME_URL, token);
    assert.equal(expirado.statusCode, 401, expirado.body);
    assert.equal((expirado.json() as { error: { code: string } }).error.code, 'UNAUTHENTICATED');

    // Token inexistente (nunca emitido): indistinguible del expirado.
    const inexistente = await get(ctx.app, ME_URL, 'token-que-nunca-se-emitio');
    assert.equal(inexistente.statusCode, 401, inexistente.body);
    assert.equal(
      (inexistente.json() as { error: { code: string } }).error.code,
      'UNAUTHENTICATED',
    );
    assert.equal(
      (expirado.json() as { error: { message: string } }).error.message,
      (inexistente.json() as { error: { message: string } }).error.message,
      'el mensaje no debe revelar si el token existió (HU-09-02 RN-3)',
    );

    // Mecanismo de revocación (HU-01-03, fuera de alcance como endpoint): una sesión
    // marcada como revocada tampoco autentica.
    const otroEmail = uniqueEmail();
    const otra = await registerAccount(ctx.app, otroEmail);
    const tokenRevocado = await loginToken(ctx.app, otroEmail);
    ctx.db
      .prepare('UPDATE sessions SET revoked_at = ? WHERE account_id = ?')
      .run(new Date().toISOString(), otra.accountId);
    const revocado = await get(ctx.app, ME_URL, tokenRevocado);
    assert.equal(revocado.statusCode, 401, revocado.body);
    assert.equal((revocado.json() as { error: { code: string } }).error.code, 'UNAUTHENTICATED');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-01-04-07 (borde): la lectura del perfil no altera la sesión (no renueva el TTL) ni el estado de la cuenta', async () => {
  const { ctx, email, account } = await authedApp();
  try {
    const login = await post(ctx.app, '/api/v1/auth/login', { email, password: VALID_PASSWORD });
    const { token, expiresAt } = login.json() as { token: string; expiresAt: string };

    const filaAntes = ctx.db
      .prepare('SELECT expires_at AS expiresAt FROM sessions WHERE account_id = ? ORDER BY created_at')
      .all(account.accountId) as unknown as { expiresAt: string }[];

    const cuerpos: string[] = [];
    for (let i = 0; i < 3; i += 1) {
      const response = await get(ctx.app, ME_URL, token);
      assert.equal(response.statusCode, 200, response.body);
      cuerpos.push(response.body);
    }
    // Cada respuesta es 200 con los mismos datos.
    assert.equal(new Set(cuerpos).size, 1, `el perfil cambió entre lecturas: ${cuerpos.join(' | ')}`);
    const profile = assertProfileBody(JSON.parse(cuerpos[0]), cuerpos[0]);
    assert.equal(profile.status, 'ACTIVE');

    const filaDespues = ctx.db
      .prepare('SELECT expires_at AS expiresAt FROM sessions WHERE account_id = ? ORDER BY created_at')
      .all(account.accountId) as unknown as { expiresAt: string }[];
    assert.deepEqual(filaDespues, filaAntes, 'la lectura del perfil modificó expires_at (RN-7)');
    assert.equal(filaDespues[filaDespues.length - 1].expiresAt, expiresAt);

    // El estado de la cuenta sigue siendo ACTIVE en la base.
    const fila = ctx.db
      .prepare('SELECT status FROM accounts WHERE account_id = ?')
      .get(account.accountId) as { status: string };
    assert.equal(fila.status, 'ACTIVE');
  } finally {
    await ctx.cleanup();
  }
});

