test('HU-01-04 RN-2/RN-3 (decisión de contrato): la identidad sale sólo del token; un selector de cuenta ajeno se ignora', async () => {
  // La épica 09 no expone `/accounts/{accountId}`, así que los AT-01-04-05/06 no tienen
  // superficie propia (ver el encabezado). Lo verificable es la decisión equivalente: el
  // perfil devuelto es siempre el del dueño del token (RN-2 / HU-06-04 RN-2) y sin token
  // válido la respuesta es UNAUTHENTICATED antes que cualquier otra cosa (RN-8).
  const ctx = createTestApp();
  try {
    const emailA = uniqueEmail('a');
    const emailB = uniqueEmail('b');
    const cuentaA = await registerAccount(ctx.app, emailA);
    const cuentaB = await registerAccount(ctx.app, emailB);
    const tokenA = await loginToken(ctx.app, emailA);

    // A pide su perfil inyectando el accountId de B por query, header y cuerpo.
    const respuestas = [
      await get(ctx.app, `${ME_URL}?accountId=${cuentaB.accountId}`, tokenA),
      await ctx.app.inject({
        method: 'GET',
        url: ME_URL,
        headers: { authorization: `Bearer ${tokenA}`, 'x-account-id': cuentaB.accountId },
      }),
      await ctx.app.inject({
        method: 'GET',
        url: ME_URL,
        headers: { authorization: `Bearer ${tokenA}`, 'content-type': 'application/json' },
        payload: JSON.stringify({ accountId: cuentaB.accountId }),
      }),
    ];
    for (const response of respuestas) {
      assert.equal(response.statusCode, 200, response.body);
      const profile = assertProfileBody(response.json(), response.body);
      assert.equal(profile.accountId, cuentaA.accountId);
      assert.equal(profile.email, emailA.toLowerCase());
      // Ningún dato de B, y tampoco un 403 que revele que B existe.
      assert.ok(!response.body.includes(cuentaB.accountId));
      assert.ok(!response.body.includes(emailB.toLowerCase()));
    }

    // Precedencia RN-8: sin credencial válida, un solo error y es UNAUTHENTICATED (401).
    const sinToken = await get(ctx.app, `${ME_URL}?accountId=${cuentaB.accountId}`);
    assert.equal(sinToken.statusCode, 401, sinToken.body);
    const error = (sinToken.json() as { error: { code: string } }).error;
    assert.equal(error.code, 'UNAUTHENTICATED');
    assert.notEqual(error.code, 'UNAUTHORIZED');
  } finally {
    await ctx.cleanup();
  }
});

