const EIP55_RE = /^0x[0-9a-fA-F]{40}$/;

async function authedApp(): Promise<{ ctx: TestApp; token: string; accountId: string }> {
  const ctx = createTestApp();
  const email = uniqueEmail();
  const account = await registerAccount(ctx.app, email);
  const token = await loginToken(ctx.app, email);
  return { ctx, token, accountId: account.accountId };
}

