test('AT-09-01-01: POST /api/v1/auth/register ⇒ 201 con { accountId, email, status, createdAt }', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    const response = await post(ctx.app, '/api/v1/auth/register', {
      email,
      password: VALID_PASSWORD,
    });

    assert.equal(response.statusCode, 201);
    assert.match(String(response.headers['content-type']), /application\/json/);
    const body = response.json() as Record<string, unknown>;
    assert.deepEqual(Object.keys(body).sort(), ['accountId', 'createdAt', 'email', 'status']);
    assert.equal(body.email, email.toLowerCase());
    assert.equal(body.status, 'ACTIVE');
    assert.equal(typeof body.accountId, 'string');
    assert.equal(typeof body.createdAt, 'string');
    assert.ok(!Number.isNaN(Date.parse(body.createdAt as string)), 'createdAt ISO-8601 UTC');

    // No se expone la contraseña ni hash alguno.
    assert.ok(!response.body.includes(VALID_PASSWORD));
    assert.ok(!/password|hash|scrypt|salt/i.test(response.body), response.body);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-02: POST /api/v1/auth/login ⇒ 200 con token usable como Bearer; credenciales incorrectas ⇒ INVALID_CREDENTIALS (401)', async () => {
  const ctx = createTestApp();
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);

    const ok = await post(ctx.app, '/api/v1/auth/login', { email, password: VALID_PASSWORD });
    assert.equal(ok.statusCode, 200);
    const body = ok.json() as Record<string, unknown>;
    assert.equal(typeof body.token, 'string');
    assert.ok((body.token as string).length > 0);

    // El token es utilizable como `Authorization: Bearer <token>` en un recurso protegido.
    const protegido = await get(ctx.app, '/api/v1/deposit-address?asset=ETH', body.token as string);
    assert.equal(protegido.statusCode, 200);

    // Contraseña incorrecta y email inexistente son indistinguibles (no revela existencia).
    const passMal = await post(ctx.app, '/api/v1/auth/login', { email, password: 'OtraClave123' });
    const emailInexistente = await post(ctx.app, '/api/v1/auth/login', {
      email: uniqueEmail(),
      password: VALID_PASSWORD,
    });
    for (const response of [passMal, emailInexistente]) {
      assert.equal(response.statusCode, 401);
      assert.equal(assertErrorEnvelope(response).code, 'INVALID_CREDENTIALS');
    }
    assert.equal(passMal.body, emailInexistente.body, 'la respuesta revela si el email existe');
  } finally {
    await ctx.cleanup();
  }
});

test('AT-09-01-10: GET /api/v1/deposit-address?asset=ETH ⇒ 200 con { asset, address } EIP-55; ?asset=BTC ⇒ VALIDATION_ERROR (422)', async () => {
