test('AT-09-01-15: ruta inexistente ⇒ NOT_FOUND (404); método no permitido sobre ruta existente ⇒ METHOD_NOT_ALLOWED (405) con details { method, allowed }', async () => {
  const ctx = createTestApp();
  try {
    const inexistente = await get(ctx.app, '/api/v1/foo');
    assert.equal(inexistente.statusCode, 404);
    assert.equal(assertErrorEnvelope(inexistente).code, 'NOT_FOUND');

    // `/api/v1/balances` no existe en esta corrida: se usa una ruta existente del alcance.
    const put = await ctx.app.inject({
      method: 'PUT',
      url: '/api/v1/auth/login',
      headers: { 'content-type': 'application/json' },
      payload: JSON.stringify({ email: uniqueEmail(), password: VALID_PASSWORD }),
    });
    assert.equal(put.statusCode, 405);
    const error = assertErrorEnvelope(put);
    assert.equal(error.code, 'METHOD_NOT_ALLOWED');
    assert.equal(error.details?.method, 'PUT');
    assert.ok(Array.isArray(error.details?.allowed), 'details.allowed debe ser la lista de verbos');
    assert.deepEqual(error.details?.allowed, ['POST']);
  } finally {
    await ctx.cleanup();
  }
});

