/**
 * CORS — soporte de despliegue para el cliente web (épica 10), **no especificado**.
 *
 * La spec no menciona CORS en ninguna parte, así que estos tests no llevan AT-id: no
 * verifican un criterio de aceptación sino el contrato de la variable de entorno
 * `CORS_ALLOWED_ORIGINS` que habilita al cliente web (`http://localhost:5173` en
 * desarrollo) a pegarle directo al backend en lugar de vía proxy.
 *
 * Invariante que se protege: **apagado por defecto**. Con la variable ausente o vacía el
 * backend no emite ningún header de CORS y su comportamiento observable es idéntico al de
 * antes de esta feature. No se habilita `Access-Control-Allow-Credentials`: el contrato no
 * usa cookies (HU-10-01 RN-3), la autenticación es por `Authorization: Bearer`.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { loadConfig, ConfigError, parseCorsAllowedOrigins } from '../src/core/config';
import { createTestApp, get, makeEnv, registerAccount, loginToken, uniqueEmail } from './helpers/testApp';

const ALLOWED = 'http://localhost:5173';
const ALLOWED_ALT = 'http://127.0.0.1:5173';
const CORS_ENV = { CORS_ALLOWED_ORIGINS: `${ALLOWED},${ALLOWED_ALT}` };

const CORS_HEADERS = [
  'access-control-allow-origin',
  'access-control-allow-methods',
  'access-control-allow-headers',
  'access-control-max-age',
  'access-control-allow-credentials',
];

function assertSinHeadersDeCors(headers: Record<string, unknown>, where: string): void {
  for (const name of CORS_HEADERS) {
    assert.equal(headers[name], undefined, `${where}: no debería emitir ${name}`);
  }
}

test('CORS: preflight OPTIONS con origen permitido ⇒ 204 con Allow-Origin/Methods/Headers/Max-Age y sin caer en 404/405', async () => {
  const ctx = createTestApp(CORS_ENV);
  try {
    for (const url of ['/api/v1/me', '/api/v1/auth/login', '/api/v1/no-existe']) {
      const response = await ctx.app.inject({
        method: 'OPTIONS',
        url,
        headers: {
          origin: ALLOWED,
          'access-control-request-method': 'GET',
          'access-control-request-headers': 'authorization,content-type',
        },
      });
      assert.equal(response.statusCode, 204, `${url}: ${response.body}`);
      // El preflight no pasa por el handler de 404/405 ni por el de errores.
      assert.equal(response.body, '', `${url}: el preflight no debe tener cuerpo`);
      assert.equal(response.headers['access-control-allow-origin'], ALLOWED);
      assert.equal(response.headers['vary'], 'Origin');
      const methods = String(response.headers['access-control-allow-methods']);
      assert.ok(methods.includes('GET'), methods);
      assert.ok(methods.includes('POST'), methods);
      assert.ok(methods.includes('OPTIONS'), methods);
      const allowHeaders = String(response.headers['access-control-allow-headers']).toLowerCase();
      assert.ok(allowHeaders.includes('authorization'), allowHeaders);
      assert.ok(allowHeaders.includes('content-type'), allowHeaders);
      const maxAge = String(response.headers['access-control-max-age']);
      assert.ok(/^\d+$/.test(maxAge) && Number(maxAge) > 0, `Max-Age inválido: ${maxAge}`);
      // Sin credenciales: la autenticación es por header, no por cookies.
      assert.equal(response.headers['access-control-allow-credentials'], undefined);
    }
  } finally {
    await ctx.cleanup();
  }
});

test('CORS: request normal con origen permitido ⇒ Access-Control-Allow-Origin (eco exacto) + Vary: Origin, sin alterar la respuesta', async () => {
  const ctx = createTestApp(CORS_ENV);
  try {
    const email = uniqueEmail();
    const cuenta = await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    for (const origin of [ALLOWED, ALLOWED_ALT]) {
      const ok = await get(ctx.app, '/api/v1/me', token, { headers: { origin } });
      assert.equal(ok.statusCode, 200, ok.body);
      assert.equal(ok.headers['access-control-allow-origin'], origin);
      assert.equal(ok.headers['vary'], 'Origin');
      assert.equal(ok.headers['access-control-allow-credentials'], undefined);
      assert.equal((ok.json() as { accountId: string }).accountId, cuenta.accountId);
    }

    // También en una respuesta de error, para que el navegador pueda leer el envelope.
    const error = await get(ctx.app, '/api/v1/me', undefined, { headers: { origin: ALLOWED } });
    assert.equal(error.statusCode, 401);
    assert.equal(error.headers['access-control-allow-origin'], ALLOWED);
    assert.equal(error.headers['vary'], 'Origin');
    assert.equal((error.json() as { error: { code: string } }).error.code, 'UNAUTHENTICATED');
  } finally {
    await ctx.cleanup();
  }
});

test('CORS: un Origin que no está en la lista no recibe headers de CORS y el status no cambia', async () => {
  const ctx = createTestApp(CORS_ENV);
  try {
    const email = uniqueEmail();
    await registerAccount(ctx.app, email);
    const token = await loginToken(ctx.app, email);

    // Variantes que NO son el origen exacto: otro host, otro puerto, otro esquema, sufijo.
    const ajenos = [
      'http://evil.example',
      'http://localhost:5174',
      'https://localhost:5173',
      'http://localhost:5173.evil.example',
      'http://localhost:5173/',
    ];
    for (const origin of ajenos) {
      const response = await get(ctx.app, '/api/v1/me', token, { headers: { origin } });
      // El backend no falla ni cambia el status: sigue siendo la respuesta normal.
      assert.equal(response.statusCode, 200, `${origin}: ${response.body}`);
      assertSinHeadersDeCors(response.headers as Record<string, unknown>, origin);
      assert.equal(response.headers['vary'], undefined, origin);
    }

    // Sin header Origin (cliente no-navegador) tampoco se emite nada.
    const sinOrigin = await get(ctx.app, '/api/v1/me', token);
    assert.equal(sinOrigin.statusCode, 200);
    assertSinHeadersDeCors(sinOrigin.headers as Record<string, unknown>, 'sin Origin');
  } finally {
    await ctx.cleanup();
  }
});

test('CORS: lista vacía o ausente ⇒ ningún header de CORS y comportamiento idéntico al previo', async () => {
  for (const overrides of [{}, { CORS_ALLOWED_ORIGINS: '' }, { CORS_ALLOWED_ORIGINS: '   ' }]) {
    const ctx = createTestApp(overrides);
    try {
      assert.deepEqual(ctx.config.corsAllowedOrigins, []);
      const email = uniqueEmail();
      await registerAccount(ctx.app, email);
      const token = await loginToken(ctx.app, email);

      const ok = await get(ctx.app, '/api/v1/me', token, { headers: { origin: ALLOWED } });
      assert.equal(ok.statusCode, 200, ok.body);
      assertSinHeadersDeCors(ok.headers as Record<string, unknown>, 'CORS deshabilitado');
      assert.equal(ok.headers['vary'], undefined);

      // El preflight no se atiende: OPTIONS sigue resolviendo como antes (405 sobre una
      // ruta existente que no soporta el verbo).
      const preflight = await ctx.app.inject({
        method: 'OPTIONS',
        url: '/api/v1/me',
        headers: { origin: ALLOWED, 'access-control-request-method': 'GET' },
      });
      assert.equal(preflight.statusCode, 405);
      assert.equal(
        (preflight.json() as { error: { code: string } }).error.code,
        'METHOD_NOT_ALLOWED',
      );
      assertSinHeadersDeCors(preflight.headers as Record<string, unknown>, 'preflight sin CORS');
    } finally {
      await ctx.cleanup();
    }
  }
});

test('CORS (config): la lista se parsea a orígenes exactos y un origen mal formado impide el arranque', async () => {
  // Parseo: se recortan espacios, se tolera la barra final y se deduplica.
  assert.deepEqual(parseCorsAllowedOrigins(undefined), []);
  assert.deepEqual(parseCorsAllowedOrigins(''), []);
  assert.deepEqual(parseCorsAllowedOrigins('  '), []);
  assert.deepEqual(parseCorsAllowedOrigins(`${ALLOWED},${ALLOWED_ALT}`), [ALLOWED, ALLOWED_ALT]);
  assert.deepEqual(parseCorsAllowedOrigins(` ${ALLOWED}/ , ${ALLOWED} `), [ALLOWED]);
  assert.deepEqual(parseCorsAllowedOrigins('https://app.exchange.test'), [
    'https://app.exchange.test',
  ]);

  // Mal formados: mismo mecanismo que el resto de la configuración (ConfigError ⇒ el
  // arranque falla).
  const invalidos = [
    '*',
    'localhost:5173',
    'http://localhost:5173/app',
    'http://localhost:5173?x=1',
    'http://localhost:5173#frag',
    'http://user:pass@localhost:5173',
    'ftp://localhost:5173',
    'no es una url',
  ];
  for (const value of invalidos) {
    assert.throws(
      () => parseCorsAllowedOrigins(value),
      ConfigError,
      `debería rechazarse: ${value}`,
    );
    // Y el arranque completo también falla (la validación corre en loadConfig).
    assert.throws(
      () => loadConfig(makeEnv({ CORS_ALLOWED_ORIGINS: value })),
      ConfigError,
      `loadConfig debería fallar con CORS_ALLOWED_ORIGINS=${value}`,
    );
  }

  // Un valor válido sí arranca y queda normalizado en la config.
  const config = loadConfig(makeEnv({ CORS_ALLOWED_ORIGINS: `${ALLOWED}/, ${ALLOWED_ALT}` }));
  assert.deepEqual(config.corsAllowedOrigins, [ALLOWED, ALLOWED_ALT]);
});

