    63	/** Una causa de fallo de esquema, tal como viaja en `details.issues` (HU-10-01 RN-5). */
    64	export interface ValidationIssue {
    65	  field: string;
    66	  message: string;
    67	}
    68	
    69	/**
    70	 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
    71	 *
    72	 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
    73	 * `code` (RN-10) y así ningún detalle del error del backend puede terminar en pantalla
    74	 * (RN-8).
    75	 */
    76	export class ApiError extends Error {
    77	  readonly code: ErrorCode | string;
    78	  readonly httpStatus: number;
    79	  readonly details: Record<string, unknown> | undefined;
    80	
    81	  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
    82	    super(`ApiError(${code})`);
    83	    this.name = 'ApiError';
    84	    this.code = code;
    85	    this.httpStatus = httpStatus;
    86	    this.details = details;
    87	  }
    88	
    89	  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
    90	  get issues(): ValidationIssue[] {
    91	    const raw = this.details?.issues;
    92	    if (!Array.isArray(raw)) return [];
    93	    const issues: ValidationIssue[] = [];
    94	    for (const item of raw) {
    95	      if (typeof item === 'string') {
    96	        issues.push({ field: '', message: item });
    97	        continue;
    98	      }
    99	      if (typeof item !== 'object' || item === null) continue;
   100	      const record = item as Record<string, unknown>;
   101	      const field = record.field ?? record.path ?? record.name ?? '';
   102	      const message = record.message ?? record.msg ?? '';
   103	      issues.push({
   104	        field: typeof field === 'string' ? field : String(field),
   105	        message: typeof message === 'string' ? message : '',
   106	      });
   107	    }
   108	    return issues;
   109	  }
   110	
   111	  /**
   112	   * `details.retryAfterSeconds` de `RATE_LIMITED`. Es un **conteo** y viaja como entero
   113	   * JSON, no como string (HU-10-01, escenario 6). Devuelve `null` si no vino un entero
   114	   * no negativo.
   115	   */
   116	  get retryAfterSeconds(): number | null {
   117	    const raw = this.details?.retryAfterSeconds;
   118	    if (typeof raw !== 'number' || !Number.isInteger(raw) || raw < 0) return null;
   119	    return raw;
   120	  }
   121	}
   122	
   123	/**
   124	 * Fallo que impide obtener una respuesta de dominio: el servidor no fue alcanzable, la
   125	 * conexión se cortó, o la respuesta no trae un envelope de error del catálogo. Se muestra
   126	 * con el mismo mensaje no técnico que `INTERNAL_ERROR` (HU-10-01 RN-8).
   127	 */
   128	export class NetworkError extends Error {
   129	  constructor() {
   130	    super('NetworkError');
   131	    this.name = 'NetworkError';
   132	  }
   133	}
   134	
   135	/** Mensaje no técnico y sin detalle sensible para el fallo de red / 500 (RN-8). */
   136	export const CONNECTION_ERROR_MESSAGE = 'No se pudo conectar, reintentá';
   137	
   138	/** Mensaje genérico de credenciales, que no revela si el email existe (RN-4). */
   139	export const INVALID_CREDENTIALS_MESSAGE = 'Email o contraseña incorrectos';
   140	
   141	/** Aviso de sesión expirada al volver a login (RN-7). */
   142	export const SESSION_EXPIRED_MESSAGE = 'Tu sesión expiró, ingresá nuevamente';
   143	
   144	/** Texto por `code` del catálogo, en español y sin datos del error del servidor (RN-10). */
   145	const MESSAGE_BY_CODE: Partial<Record<ErrorCode, string>> = {
   146	  UNAUTHENTICATED: SESSION_EXPIRED_MESSAGE,
   147	  UNAUTHORIZED: 'No tenés permiso para esta operación',
   148	  RATE_LIMITED: 'Demasiados intentos. Esperá unos segundos antes de reintentar',
   149	  VALIDATION_ERROR: 'Revisá los datos ingresados',
   150	  NOT_FOUND: 'El recurso solicitado no existe',
   151	  METHOD_NOT_ALLOWED: CONNECTION_ERROR_MESSAGE,
   152	  INVALID_CREDENTIALS: INVALID_CREDENTIALS_MESSAGE,
   153	  ACCOUNT_NOT_FOUND: 'El recurso solicitado no existe',
   154	  EMAIL_ALREADY_EXISTS: 'Ya existe una cuenta con ese email',
   155	  CONFLICT: 'La operación no se pudo completar por un conflicto de estado',
   156	  INTERNAL_ERROR: CONNECTION_ERROR_MESSAGE,
   157	};
   158	
   159	/**
   160	 * Mensaje a mostrar para un error cualquiera. Un `code` desconocido (o un fallo de red)
   161	 * cae en el mensaje no técnico de RN-8: nunca se muestra texto proveniente del servidor.
   162	 */
   163	export function messageForError(error: unknown): string {
   164	  if (error instanceof ApiError) {
   165	    if (isErrorCode(error.code)) {
   166	      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
   167	    }
   168	    return CONNECTION_ERROR_MESSAGE;
   169	  }
   170	  return CONNECTION_ERROR_MESSAGE;
   171	}
