 38	/** Mensaje por campo derivado de `details.issues` (RN-5). */
 39	interface FieldErrors {
 40	  email?: string;
 41	  password?: string;
 42	}
 43	
 44	/** Los campos del formulario a los que se puede anclar un issue. */
 45	const FORM_FIELDS = ['email', 'password'] as const;
 46	
 47	/** Límite defensivo: el detalle del servidor se muestra acotado y sin reformatear. */
 48	const MAX_ISSUE_LENGTH = 200;
 49	
 50	function truncate(text: string): string {
 51	  const clean = text.trim();
 52	  return clean.length > MAX_ISSUE_LENGTH ? `${clean.slice(0, MAX_ISSUE_LENGTH)}…` : clean;
 53	}
 54	
 55	function defaultIssueMessage(field: string): string {
 56	  if (field === 'email') return 'Revisá el email ingresado.';
 57	  if (field === 'password') return 'Revisá la contraseña ingresada.';
 58	  return 'Revisá los datos ingresados.';
 59	}
 60	
 61	/**
 62	 * Reparte los `issues` entre los campos del formulario y una lista general. Sólo se
 63	 * muestra el texto del issue (nunca el valor enviado), de modo que no se expone ningún
 64	 * dato sensible (RN-5).
 65	 */
 66	function splitIssues(error: ApiError): { fields: FieldErrors; general: string[] } {
 67	  const fields: FieldErrors = {};
 68	  const general: string[] = [];
 69	  for (const issue of error.issues) {
 70	    const field = issue.field.split('.').pop() ?? '';
 71	    const message = issue.message.trim() === '' ? defaultIssueMessage(field) : truncate(issue.message);
 72	    if ((FORM_FIELDS as readonly string[]).includes(field)) {
 73	      const key = field as (typeof FORM_FIELDS)[number];
 74	      if (fields[key] === undefined) fields[key] = message;
 75	    } else {
 76	      general.push(message);
 77	    }
 78	  }
 79	  if (Object.keys(fields).length === 0 && general.length === 0) {
 80	    general.push('Revisá los datos ingresados.');
 81	  }
 82	  return { fields, general };
 83	}
 84	
 85	function waitMessage(seconds: number): string {
 86	  const unit = seconds === 1 ? 'segundo' : 'segundos';
 87	  return `Demasiados intentos. Esperá ${seconds} ${unit} antes de reintentar.`;
 88	}
 89	
 90	export function LoginPage() {
 91	  const session = useSession();
 92	  const navigate = useNavigate();
 93	  const emailId = useId();
 94	  const passwordId = useId();
 95	
 96	  const [email, setEmail] = useState('');
 97	  const [password, setPassword] = useState('');
 98	  const [submitting, setSubmitting] = useState(false);
 99	  const [formError, setFormError] = useState<string | null>(null);
100	  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
101	  const [generalIssues, setGeneralIssues] = useState<string[]>([]);
102	  const [retryable, setRetryable] = useState(false);
103	  const [cooldown, setCooldown] = useState(0);
104	
105	  // Guarda de envío único (RN-2): sobrevive a los re-renders y se evalúa antes de disparar
106	  // la llamada, así un segundo submit no puede colarse entre el `setState` y el `fetch`.
107	  const inFlightRef = useRef(false);
108	
109	  // Cuenta regresiva del rate limit (RN-6). Al llegar a cero el botón se rehabilita solo.
110	  useEffect(() => {
111	    if (cooldown <= 0) return;
112	    const timer = setTimeout(() => setCooldown((current) => (current <= 1 ? 0 : current - 1)), 1000);
113	    return () => clearTimeout(timer);
114	  }, [cooldown]);
115	
116	  // RN-9: con la sesión ya validada no se piden credenciales de nuevo.
117	  if (session.status === 'authenticated') {
118	    return <Navigate to={TRADING_ROUTE} replace />;
119	  }
120	
121	  // RN-11: mientras el `GET /me` de validación está en vuelo no se muestra el formulario
122	  // (evita pedir credenciales que quizá no hagan falta).
123	  if (session.status === 'validating') {
124	    return (
125	      <main className="card" aria-busy="true">
126	        <h1>Exchange ETH/USDC</h1>
127	        <p className="muted" data-testid="session-validating">
128	          Validando tu sesión…
129	        </p>
130	      </main>
131	    );
132	  }
133	
134	  const hasCredentials = email.trim() !== '' && password !== '';
135	  const blockedByRateLimit = cooldown > 0;
136	  const canSubmit = hasCredentials && !submitting && !blockedByRateLimit;
137	
138	  function resetFeedback() {
139	    setFormError(null);
140	    setFieldErrors({});
141	    setGeneralIssues([]);
142	    setRetryable(false);
143	  }
144	
145	  function handleFailure(error: unknown) {
146	    if (error instanceof ApiError) {
147	      switch (error.code) {
148	        case 'INVALID_CREDENTIALS':
149	          // RN-4: mismo mensaje genérico exista o no el email; la contraseña se limpia y el
150	          // usuario permanece en login para reintentar.
151	          setPassword('');
152	          setFormError(INVALID_CREDENTIALS_MESSAGE);
153	          return;
154	        case 'VALIDATION_ERROR': {
155	          // RN-5: detalle por campo desde `details.issues`.
156	          const { fields, general } = splitIssues(error);
157	          setFieldErrors(fields);
158	          setGeneralIssues(general);
159	          return;
160	        }
161	        case 'RATE_LIMITED': {
162	          // RN-6: la espera sale de `details.retryAfterSeconds` (entero JSON). Si el error
163	          // no la trae, no hay lapso que contar: se informa el límite sin bloquear el botón.
164	          const seconds = error.retryAfterSeconds;
165	          if (seconds !== null && seconds > 0) {
166	            setCooldown(seconds);
167	            return;
168	          }
169	          setFormError(messageForError(error));
170	          return;
171	        }
172	        case 'INTERNAL_ERROR':
173	          // RN-8: mensaje no técnico, con reintento y sin filtrar detalle del error.
174	          setFormError(CONNECTION_ERROR_MESSAGE);
175	          setRetryable(true);
176	          return;
177	        default:
178	          // RN-10: cualquier otro `code` del catálogo se resuelve por su código, no por el
179	          // texto del servidor.
180	          setFormError(messageForError(error));
181	          return;
182	      }
183	    }
184	    // `NetworkError` o cualquier falla no clasificada: RN-8.
185	    setFormError(CONNECTION_ERROR_MESSAGE);
186	    setRetryable(true);
187	  }
188	
189	  async function attemptLogin() {
190	    // RN-2: durante una solicitud en curso el intento se ignora.
191	    if (inFlightRef.current) return;
192	    // RN-1: sin ambos campos no se llama a la API.
193	    if (!hasCredentials) return;
194	    // RN-6: durante la espera del rate limit tampoco se reintenta.
195	    if (blockedByRateLimit) return;
196	
197	    inFlightRef.current = true;
198	    setSubmitting(true);
199	    resetFeedback();
200	    session.dismissNotice();
201	
202	    try {
203	      // El email se envía tal como se tipeó: el login **no** valida su formato y la
204	      // normalización (trim + lowercase) es del servidor (HU-01-02 RN-1/RN-11).
205	      const response = await login(session.api, { email, password });
206	      // RNE-2: no se asume éxito sin una respuesta utilizable del servidor.
207	      if (
208	        typeof response?.token !== 'string' ||
209	        response.token === '' ||
210	        typeof response.expiresAt !== 'string'
211	      ) {
212	        throw new NetworkError();
213	      }
214	      // RN-3: sesión establecida y navegación a la vista de trading (HU-10-02).
215	      session.establish({ token: response.token, expiresAt: response.expiresAt });
216	      navigate(TRADING_ROUTE, { replace: true });
217	    } catch (error) {
218	      handleFailure(error);
219	    } finally {
220	      inFlightRef.current = false;
221	      setSubmitting(false);
222	    }
223	  }
224	
225	  function handleSubmit(event: FormEvent<HTMLFormElement>) {
226	    event.preventDefault();
227	    void attemptLogin();
228	  }
229	
230	  const errorMessage = blockedByRateLimit ? waitMessage(cooldown) : formError;
231	
232	  return (
233	    <main className="card">
234	      <h1>Exchange ETH/USDC</h1>
235	      <p className="muted">Ingresá con tu cuenta para operar el par ETH/USDC.</p>
236	
237	      {session.notice !== null && (
238	        <p className="alert alert-warning" role="status" data-testid="session-notice">
239	          {session.notice}
240	        </p>
241	      )}
242	
243	      {session.validationUnavailable && (
244	        <p className="alert alert-warning" role="status" data-testid="validation-unavailable">
245	          {CONNECTION_ERROR_MESSAGE}{' '}
246	          <button type="button" className="link" onClick={() => session.revalidate()}>
247	            Reintentar validación
248	          </button>
249	        </p>
250	      )}
251	
252	      <form onSubmit={handleSubmit} noValidate>
253	        <div className="field">
254	          <label htmlFor={emailId}>Email</label>
255	          <input
256	            id={emailId}
257	            name="email"
258	            type="email"
259	            autoComplete="username"
260	            value={email}
261	            onChange={(event) => setEmail(event.target.value)}
262	            aria-invalid={fieldErrors.email !== undefined}
263	            aria-describedby={fieldErrors.email !== undefined ? `${emailId}-error` : undefined}
264	            disabled={submitting}
265	          />
266	          {fieldErrors.email !== undefined && (
267	            <p className="field-error" id={`${emailId}-error`} data-testid="email-error">
268	              {fieldErrors.email}
269	            </p>
270	          )}
271	        </div>
272	
273	        <div className="field">
274	          <label htmlFor={passwordId}>Contraseña</label>
275	          <input
276	            id={passwordId}
277	            name="password"
278	            type="password"
279	            autoComplete="current-password"
280	            value={password}
281	            onChange={(event) => setPassword(event.target.value)}
282	            aria-invalid={fieldErrors.password !== undefined}
283	            aria-describedby={fieldErrors.password !== undefined ? `${passwordId}-error` : undefined}
284	            disabled={submitting}
285	          />
286	          {fieldErrors.password !== undefined && (
287	            <p className="field-error" id={`${passwordId}-error`} data-testid="password-error">
288	              {fieldErrors.password}
289	            </p>
290	          )}
291	        </div>
292	
293	        {generalIssues.length > 0 && (
294	          <ul className="alert alert-error" role="alert" data-testid="general-issues">
295	            {generalIssues.map((issue) => (
296	              <li key={issue}>{issue}</li>
297	            ))}
298	          </ul>
299	        )}
300	
301	        {errorMessage !== null && (
302	          <p className="alert alert-error" role="alert" data-testid="login-error">
303	            {errorMessage}
304	            {retryable && (
305	              <>
306	                {' '}
307	                <button
308	                  type="button"
309	                  className="link"
310	                  onClick={() => void attemptLogin()}
311	                  data-testid="retry-login"
312	                >
313	                  Reintentar
314	                </button>
315	              </>
316	            )}
317	          </p>
318	        )}
319	
320	        <button type="submit" disabled={!canSubmit} data-testid="submit-login">
321	          {submitting ? 'Ingresando…' : 'Ingresar'}
322	        </button>
323	      </form>
324	    </main>
325	  );
