/**
 * Utilidades compartidas por la suite de aceptación de HU-10-01 (pantalla de login).
 *
 * Contiene: el montaje de la app con routing y sesión inyectables (`renderApp`), un mock de
 * `fetch` que discrimina por método + URL como lo haría la API real (`createFetchMock`),
 * constructores de respuestas con el envelope de `00-fundaciones/modelo-de-errores.md`
 * (`jsonResponse` / `errorResponse`) y acceso crudo al registro de sesión persistido.
 */
import { render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { vi, type Mock } from 'vitest';
import { App } from '../src/App';
import { SessionProvider } from '../src/session/SessionProvider';
import { LOGIN_ROUTE } from '../src/routes/paths';
import type { FetchLike } from '../src/api/client';
import type { StoredSession } from '../src/session/storage';

/**
 * Clave de `localStorage` del registro de sesión (contrato de `src/session/storage.ts`).
 * Se replica acá a propósito: los AT-10-01-07/09/10 y RN-3 afirman sobre el estado
 * persistido *desde afuera* del cliente, sin usar sus propios helpers de lectura.
 */
export const STORAGE_KEY = 'cex.web.session.v1';

/** Prefijo de la API que se le pasa explícitamente al provider en los tests. */
export const BASE_URL = '/api/v1';

/** Perfil que devuelve `GET /api/v1/me` (HU-09-01: `{accountId, email, status, createdAt}`). */
export const PROFILE = {
  accountId: 'acc_01HZY0000000000000000001',
  email: 'trader@example.com',
  status: 'ACTIVE',
  createdAt: '2026-01-05T10:00:00.000Z',
} as const;

/** Credenciales que tipea el usuario en la mayoría de los escenarios. */
export const CREDENTIALS = {
  email: 'trader@example.com',
  password: 'Contrasena-Muy-Larga-1234',
} as const;

/** Instante ISO 8601 UTC desplazado `seconds` respecto de ahora. */
export function isoIn(seconds: number): string {
  return new Date(Date.now() + seconds * 1000).toISOString();
}

// --------------------------------------------------------------------------------------
// Mock de `fetch`
// --------------------------------------------------------------------------------------

/** Una llamada al mock, ya normalizada para poder afirmar sobre ella. */
export interface FetchCall {
  url: string;
  method: string;
  headers: Record<string, string>;
  body: unknown;
}

export type RouteHandler = (call: FetchCall) => Response | Promise<Response>;

export interface RouteMap {
  /** `POST /auth/login` (HU-09-01). */
  login?: RouteHandler;
  /** `GET /me` (llamada liviana de validación de RN-11 y llamada protegida de trading). */
  me?: RouteHandler;
}

export type FetchMock = Mock<(input: string, init?: RequestInit) => Promise<Response>>;

function normalizeHeaders(headers: HeadersInit | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  if (!headers) return out;
  if (headers instanceof Headers) {
    headers.forEach((value, key) => {
      out[key.toLowerCase()] = value;
    });
    return out;
  }
  if (Array.isArray(headers)) {
    for (const [key, value] of headers) out[String(key).toLowerCase()] = String(value);
    return out;
  }
  for (const [key, value] of Object.entries(headers)) out[key.toLowerCase()] = String(value);
  return out;
}

function describeCall(input: string, init: RequestInit | undefined): FetchCall {
  let body: unknown = undefined;
  if (typeof init?.body === 'string' && init.body !== '') {
    try {
      body = JSON.parse(init.body);
    } catch {
      body = init.body;
    }
  }
  return {
    url: input,
    method: (init?.method ?? 'GET').toUpperCase(),
    headers: normalizeHeaders(init?.headers),
    body,
  };
}

/**
 * `fetch` de mentira que enruta por método + URL. Una ruta sin handler declarado hace
 * fallar el test (el cliente la verá como fallo de red, pero la aserción del escenario no
 * se cumplirá y el mensaje queda en el listado de llamadas).
 */
export function createFetchMock(routes: RouteMap): FetchMock {
  return vi.fn(async (input: string, init?: RequestInit): Promise<Response> => {
    const call = describeCall(input, init);
    if (call.method === 'POST' && call.url.endsWith('/auth/login')) {
      if (!routes.login) throw new Error(`El test no esperaba una llamada a ${call.url}`);
      return routes.login(call);
    }
    if (call.method === 'GET' && call.url.endsWith('/me')) {
      if (!routes.me) throw new Error(`El test no esperaba una llamada a ${call.url}`);
      return routes.me(call);
    }
    throw new Error(`Ruta no mockeada: ${call.method} ${call.url}`);
  });
}

/** Llamadas registradas por el mock, en orden. */
export function fetchCalls(mock: FetchMock): FetchCall[] {
  return mock.mock.calls.map(([input, init]) => describeCall(input, init));
}

/** Llamadas cuyo path termina en `suffix`. */
export function callsTo(mock: FetchMock, suffix: string): FetchCall[] {
  return fetchCalls(mock).filter((call) => call.url.endsWith(suffix));
}

/** Respuesta JSON realista (con `content-type`), como la de un servidor HTTP. */
export function jsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

/** Respuesta de error con el envelope uniforme `{ error: { code, message, details } }`. */
export function errorResponse(
  status: number,
  code: string,
  message: string,
  details?: Record<string, unknown>,
): Response {
  return jsonResponse(status, {
    error: { code, message, ...(details !== undefined ? { details } : {}) },
  });
}

/** Promesa controlada por el test, para mantener una solicitud "en vuelo". */
export interface Deferred<T> {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (reason: unknown) => void;
}

export function deferred<T>(): Deferred<T> {
  let resolve!: (value: T) => void;
  let reject!: (reason: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

// --------------------------------------------------------------------------------------
// Sesión persistida
// --------------------------------------------------------------------------------------

/** Deja un registro de sesión en `localStorage`, como una recarga de la SPA. */
export function seedStoredSession(session: StoredSession): void {
  globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
}

/** Registro de sesión persistido crudo, o `null` si no hay ninguno. */
export function readPersistedSession(): { token?: unknown; expiresAt?: unknown } | null {
  const raw = globalThis.localStorage.getItem(STORAGE_KEY);
  if (raw === null) return null;
  return JSON.parse(raw) as { token?: unknown; expiresAt?: unknown };
}

/** Contenido completo de `localStorage`, para afirmar que no quedó rastro del token. */
export function dumpLocalStorage(): string {
  const store = globalThis.localStorage;
  let out = '';
  for (let i = 0; i < store.length; i += 1) {
    const key = store.key(i);
    if (key === null) continue;
    out += `${key}=${store.getItem(key) ?? ''}\n`;
  }
  return out;
}

// --------------------------------------------------------------------------------------
// Montaje de la app
// --------------------------------------------------------------------------------------

export interface RenderAppOptions {
  fetchImpl: FetchLike;
  /** Ruta inicial del router en memoria. Por defecto, la pantalla de login. */
  initialEntries?: string[];
  baseUrl?: string;
}

/**
 * Monta la app completa (rutas `/login` y `/trading`) con el mismo anidamiento que
 * `src/main.tsx` — `SessionProvider` por fuera del router —, cambiando `BrowserRouter` por
 * `MemoryRouter` e inyectando el `fetch` del test.
 */
export function renderApp(options: RenderAppOptions) {
  return render(
    <SessionProvider baseUrl={options.baseUrl ?? BASE_URL} fetchImpl={options.fetchImpl}>
      <MemoryRouter initialEntries={options.initialEntries ?? [LOGIN_ROUTE]}>
        <App />
      </MemoryRouter>
    </SessionProvider>,
  );
}
