/**
 * Suite de aceptación de HU-10-01 — Pantalla de login.
 *
 * Un test por criterio de aceptación (AT-10-01-01 .. AT-10-01-10), más los tests de las
 * reglas que los AT no cubren de forma directa pero la HU exige (RN-10 / RNE-3 y RN-3).
 *
 * Todo se ejercita de caja negra sobre la app real (`<App />` con routing y
 * `<SessionProvider>`), mockeando únicamente `fetch`: la API es el límite del sistema bajo
 * prueba, y las respuestas usan el envelope de `00-fundaciones/modelo-de-errores.md`.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  CREDENTIALS,
  PROFILE,
  STORAGE_KEY,
  callsTo,
  createFetchMock,
  deferred,
  dumpLocalStorage,
  errorResponse,
  fetchCalls,
  isoIn,
  jsonResponse,
  readPersistedSession,
  renderApp,
  seedStoredSession,
  type FetchMock,
} from './support';

/** Token de sesión con una forma reconocible: se busca su literal en el DOM y en la URL. */
const TOKEN = 'tok_sesion_secreta_9f3c1a7b5e2d';

const emailInput = () => screen.getByLabelText('Email') as HTMLInputElement;
const passwordInput = () => screen.getByLabelText('Contraseña') as HTMLInputElement;
const submitButton = () => screen.getByTestId('submit-login') as HTMLButtonElement;
const loginForm = () => {
  const form = submitButton().closest('form');
  if (form === null) throw new Error('El botón de envío no está dentro de un <form>');
  return form;
};

/** Completa el formulario con `userEvent` (eventos de teclado reales sobre los inputs). */
async function fillCredentials(
  user: ReturnType<typeof userEvent.setup>,
  credentials: { email: string; password: string } = CREDENTIALS,
) {
  await user.type(emailInput(), credentials.email);
  await user.type(passwordInput(), credentials.password);
}

/** Respuesta 200 de `POST /auth/login` (HU-09-01 / HU-01-02). */
function loginOk(token = TOKEN, expiresAt = isoIn(3600)) {
  return () => jsonResponse(200, { token, tokenType: 'Bearer', expiresAt });
}

describe('HU-10-01 — Pantalla de login', () => {
  // -----------------------------------------------------------------------------------
  // AT-10-01-01 — Login exitoso
  // -----------------------------------------------------------------------------------
  it('AT-10-01-01: login exitoso llama al endpoint, establece la sesión, navega a trading y no expone el token en el DOM ni en la URL', async () => {
    const expiresAt = isoIn(3600);
    const fetchMock = createFetchMock({
      login: loginOk(TOKEN, expiresAt),
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    // Navegó a la vista de trading (HU-10-02) y ya no se piden credenciales.
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(screen.queryByTestId('submit-login')).toBeNull();

    // Se envió la solicitud al endpoint de autenticación de la épica 09.
    const login = callsTo(fetchMock, '/auth/login');
    expect(login).toHaveLength(1);
    expect(login[0]?.url).toBe('/api/v1/auth/login');
    expect(login[0]?.method).toBe('POST');
    expect(login[0]?.body).toEqual({ email: CREDENTIALS.email, password: CREDENTIALS.password });

    // El token quedó establecido como sesión (se usa en la llamada protegida siguiente)…
    expect(callsTo(fetchMock, '/me')[0]?.headers.authorization).toBe(`Bearer ${TOKEN}`);
    // …pero su literal no aparece renderizado ni en la URL del navegador (RN-3 / RNE-4).
    expect(document.body.innerHTML).not.toContain(TOKEN);
    expect(document.body.textContent ?? '').not.toContain(TOKEN);
    expect(window.location.href).not.toContain(TOKEN);
    expect(window.location.search).toBe('');
    expect(window.location.hash).toBe('');
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-02a / 02b — Credenciales inválidas con mensaje genérico
  // -----------------------------------------------------------------------------------

  /**
   * Ejecuta un intento de login que la API rechaza con `INVALID_CREDENTIALS` (401) y
   * devuelve lo observable desde afuera. Es la "salida" que 02a y 02b deben compartir.
   */
  async function attemptRejectedLogin(email: string, serverMessage: string) {
    const fetchMock = createFetchMock({
      login: () => errorResponse(401, 'INVALID_CREDENTIALS', serverMessage),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user, { email, password: 'una-contrasena-cualquiera' });
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    return {
      errorText: (error.textContent ?? '').trim(),
      passwordValue: passwordInput().value,
      emailValue: emailInput().value,
      // Sigue en la pantalla de login: el formulario está montado y no hay vista de trading.
      onLogin: screen.queryByTestId('submit-login') !== null,
      onTrading: screen.queryByTestId('trading-account') !== null,
      loginCalls: callsTo(fetchMock, '/auth/login').length,
    };
  }

  it('AT-10-01-02a: email inexistente ⇒ mensaje genérico, password limpio y permanece en login', async () => {
    const outcome = await attemptRejectedLogin(
      'no-existe@example.com',
      'Credenciales inválidas.',
    );

    expect(outcome.errorText).toBe('Email o contraseña incorrectos');
    expect(outcome.passwordValue).toBe('');
    expect(outcome.emailValue).toBe('no-existe@example.com');
    expect(outcome.onLogin).toBe(true);
    expect(outcome.onTrading).toBe(false);
    expect(outcome.loginCalls).toBe(1);
  });

  it('AT-10-01-02b: email existente con contraseña incorrecta ⇒ salida indistinguible del caso 02a (mismo code)', async () => {
    // Mismo `code` para las dos situaciones: el cliente no puede (ni debe) diferenciarlas.
    const inexistente = await attemptRejectedLogin(
      'no-existe@example.com',
      'Credenciales inválidas.',
    );
    cleanup();
    globalThis.localStorage.clear();
    const passwordIncorrecta = await attemptRejectedLogin(
      'no-existe@example.com',
      'Password incorrecta para la cuenta acc_0001.',
    );

    expect(passwordIncorrecta.errorText).toBe('Email o contraseña incorrectos');
    expect(passwordIncorrecta.passwordValue).toBe('');
    expect(passwordIncorrecta.onLogin).toBe(true);
    expect(passwordIncorrecta.onTrading).toBe(false);
    // La evidencia de que no se revela si el email existe: la salida completa es idéntica,
    // aun con `message` distinto del servidor (RN-4 + RN-10).
    expect(passwordIncorrecta).toEqual(inexistente);
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-03 — Campos vacíos deshabilitan el envío
  // -----------------------------------------------------------------------------------
  it('AT-10-01-03: con email y/o password vacíos el botón queda deshabilitado y no se llama a la API', async () => {
    // Sin handlers: cualquier llamada a la API haría fallar el escenario de forma visible.
    const fetchMock = createFetchMock({});
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    // Caso 1: ambos vacíos.
    expect(submitButton().disabled).toBe(true);

    // Caso 2: sólo email.
    await user.type(emailInput(), CREDENTIALS.email);
    expect(passwordInput().value).toBe('');
    expect(submitButton().disabled).toBe(true);

    // Caso 3: sólo password.
    await user.clear(emailInput());
    await user.type(passwordInput(), CREDENTIALS.password);
    expect(emailInput().value).toBe('');
    expect(submitButton().disabled).toBe(true);

    // Aun forzando el submit del formulario (sin pasar por el botón deshabilitado) no se
    // dispara ninguna llamada: RN-1 se aplica también en el handler de envío.
    fireEvent.submit(loginForm());
    await Promise.resolve();
    expect(fetchMock).not.toHaveBeenCalled();
    expect(fetchCalls(fetchMock)).toHaveLength(0);

    // Con los dos campos completos sí se habilita (el bloqueo era por campos vacíos).
    await user.type(emailInput(), CREDENTIALS.email);
    expect(submitButton().disabled).toBe(false);
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-04 — Anti doble submit
  // -----------------------------------------------------------------------------------
  it('AT-10-01-04: con una solicitud en curso el segundo envío se ignora y el botón muestra estado de carga', async () => {
    const gate = deferred<Response>();
    const fetchMock = createFetchMock({
      login: () => gate.promise,
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    // Estado de carga mientras la primera solicitud está en vuelo.
    expect(submitButton().textContent).toBe('Ingresando…');
    expect(submitButton().disabled).toBe(true);
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(1);

    // Segundo intento antes de recibir respuesta: por el botón (deshabilitado) y forzando
    // el submit del formulario. Ninguno dispara una segunda llamada (RN-2).
    await user.click(submitButton());
    fireEvent.submit(loginForm());
    fireEvent.submit(loginForm());
    await Promise.resolve();
    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(submitButton().textContent).toBe('Ingresando…');

    // Al resolver la primera, el flujo continúa normalmente.
    await act(async () => {
      gate.resolve(jsonResponse(200, { token: TOKEN, tokenType: 'Bearer', expiresAt: isoIn(3600) }));
    });
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(1);
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-05 — VALIDATION_ERROR (422) con details.issues
  // -----------------------------------------------------------------------------------
  it('AT-10-01-05: VALIDATION_ERROR (422) muestra los mensajes por campo derivados de details.issues y no navega fuera de login', async () => {
    const fetchMock = createFetchMock({
      login: () =>
        errorResponse(422, 'VALIDATION_ERROR', 'El payload no cumple el esquema.', {
          issues: [
            { field: 'email', message: 'Formato de email inválido.' },
            { field: 'password', message: 'Debe tener al menos 8 caracteres.' },
            { field: 'captcha', message: 'Campo desconocido.' },
          ],
        }),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user, { email: 'no-es-un-email', password: 'corta' });
    await user.click(submitButton());

    // Un mensaje por campo, con el texto que vino en `issues`.
    expect((await screen.findByTestId('email-error')).textContent).toBe('Formato de email inválido.');
    expect(screen.getByTestId('password-error').textContent).toBe('Debe tener al menos 8 caracteres.');
    // Los issues que no corresponden a un campo del formulario se listan aparte.
    expect(screen.getByTestId('general-issues').textContent).toContain('Campo desconocido.');
    // Los campos quedan marcados como inválidos para lectores de pantalla.
    expect(emailInput().getAttribute('aria-invalid')).toBe('true');
    expect(passwordInput().getAttribute('aria-invalid')).toBe('true');

    // No se navega fuera de login.
    expect(screen.queryByTestId('trading-account')).toBeNull();
    expect(submitButton()).toBeTruthy();
    expect(readPersistedSession()).toBeNull();
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-06 — RATE_LIMITED (429) con details.retryAfterSeconds
  // -----------------------------------------------------------------------------------
  describe('AT-10-01-06 — rate limit', () => {
    afterEach(() => {
      vi.useRealTimers();
    });

    it('AT-10-01-06: RATE_LIMITED (429) deshabilita el botón, informa los 30 segundos de espera y lo rehabilita al transcurrir', async () => {
      vi.useFakeTimers();
      // `retryAfterSeconds` viaja como **entero JSON** (no string), según el escenario 6.
      const fetchMock = createFetchMock({
        login: () =>
          errorResponse(429, 'RATE_LIMITED', 'Se superó el límite de solicitudes.', {
            retryAfterSeconds: 30,
          }),
      });
      renderApp({ fetchImpl: fetchMock });

      // Con temporizadores falsos se usa `fireEvent` en lugar de `user-event`.
      fireEvent.change(emailInput(), { target: { value: CREDENTIALS.email } });
      fireEvent.change(passwordInput(), { target: { value: CREDENTIALS.password } });
      expect(submitButton().disabled).toBe(false);

      await act(async () => {
        fireEvent.submit(loginForm());
      });

      // Botón bloqueado y aviso con el lapso exacto informado por el servidor.
      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(1);
      expect(submitButton().disabled).toBe(true);
      expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');

      // A mitad de la espera todavía está bloqueado (la cuenta regresiva avanza).
      await act(async () => {
        await vi.advanceTimersByTimeAsync(15_000);
      });
      expect(submitButton().disabled).toBe(true);
      expect(screen.getByTestId('login-error').textContent).toContain('15 segundos');

      // Transcurrido el tiempo indicado, el botón se rehabilita (RN-6).
      await act(async () => {
        await vi.advanceTimersByTimeAsync(15_000);
      });
      expect(submitButton().disabled).toBe(false);
      expect(screen.queryByTestId('login-error')).toBeNull();

      // Y un reenvío ya sí llega a la API.
      await act(async () => {
        fireEvent.submit(loginForm());
      });
      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(2);
    });
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-07 — Expiración de sesión
  // -----------------------------------------------------------------------------------
  it('AT-10-01-07: UNAUTHENTICATED (401) en una llamada protegida limpia la sesión local y redirige a login con el aviso de expiración', async () => {
    const gate = deferred<Response>();
    const fetchMock = createFetchMock({
      login: loginOk(),
      // La llamada protegida de la pantalla de trading queda en vuelo hasta que el test la
      // resuelve: así se verifica primero que el usuario tenía sesión activa en otra vista.
      me: () => gate.promise,
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    // Sesión activa navegando otra pantalla, con el token persistido.
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(readPersistedSession()?.token).toBe(TOKEN);

    // La llamada protegida responde 401 UNAUTHENTICATED.
    await act(async () => {
      gate.resolve(errorResponse(401, 'UNAUTHENTICATED', 'Token expirado.'));
    });

    // Vuelta a login con el aviso de sesión expirada…
    const notice = await screen.findByTestId('session-notice');
    expect(notice.textContent).toBe('Tu sesión expiró, ingresá nuevamente');
    expect(submitButton()).toBeTruthy();
    expect(screen.queryByTestId('trading-account')).toBeNull();
    // …y sin rastro del token en el almacenamiento local (RNE-4).
    expect(globalThis.localStorage.getItem(STORAGE_KEY)).toBeNull();
    expect(readPersistedSession()).toBeNull();
    expect(dumpLocalStorage()).not.toContain(TOKEN);
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-08 — Fallo de red / servidor
  // -----------------------------------------------------------------------------------

  /** `message` del servidor con detalle sensible: no puede terminar en pantalla (RN-8). */
  const SERVER_LEAK = 'stack trace secreto en /var/db';

  it('AT-10-01-08 (fallo de red): muestra el mensaje no técnico, conserva el email, ofrece reintentar y no filtra el detalle del error', async () => {
    let attempts = 0;
    const fetchMock = createFetchMock({
      login: () => {
        attempts += 1;
        if (attempts === 1) return Promise.reject(new TypeError(`Failed to fetch: ${SERVER_LEAK}`));
        return jsonResponse(200, { token: TOKEN, tokenType: 'Bearer', expiresAt: isoIn(3600) });
      },
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    expect(error.textContent).toContain('No se pudo conectar, reintentá');
    // El email ingresado se conserva para reintentar sin volver a tipearlo.
    expect(emailInput().value).toBe(CREDENTIALS.email);
    expect(screen.queryByTestId('trading-account')).toBeNull();
    // Ningún detalle del error subyacente llegó a la pantalla.
    expect(document.body.textContent ?? '').not.toContain(SERVER_LEAK);
    expect(document.body.textContent ?? '').not.toContain('Failed to fetch');

    // El reintento ofrecido dispara efectivamente una segunda llamada, que esta vez entra.
    await user.click(screen.getByTestId('retry-login'));
    await waitFor(() => {
      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(2);
    });
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
  });

  it('AT-10-01-08 (INTERNAL_ERROR 500): muestra el mismo mensaje no técnico, ofrece reintentar y no filtra el message del servidor', async () => {
    let attempts = 0;
    const fetchMock = createFetchMock({
      login: () => {
        attempts += 1;
        if (attempts === 1) {
          return errorResponse(500, 'INTERNAL_ERROR', SERVER_LEAK, {
            trace: 'db://usuario=admin password=hunter2',
          });
        }
        return jsonResponse(200, { token: TOKEN, tokenType: 'Bearer', expiresAt: isoIn(3600) });
      },
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    expect(error.textContent).toContain('No se pudo conectar, reintentá');
    expect(emailInput().value).toBe(CREDENTIALS.email);
    expect(screen.queryByTestId('trading-account')).toBeNull();
    // Ni el `message` ni el `details` del servidor se filtran (RN-8) …
    expect(document.body.textContent ?? '').not.toContain(SERVER_LEAK);
    expect(document.body.textContent ?? '').not.toContain('hunter2');
    // … ni siquiera en el marcado (atributos, títulos, etc.).
    expect(document.body.innerHTML).not.toContain('hunter2');

    await user.click(screen.getByTestId('retry-login'));
    await waitFor(() => {
      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(2);
    });
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-09 — Sesión persistida vigente
  // -----------------------------------------------------------------------------------
  it('AT-10-01-09: con un token persistido vigente y GET /me → 200 se redirige a trading sin volver a autenticarse', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
    const fetchMock = createFetchMock({ me: () => jsonResponse(200, PROFILE) });
    renderApp({ fetchImpl: fetchMock });

    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(screen.queryByTestId('submit-login')).toBeNull();

    // La validación de RN-11 fue una sola llamada liviana, autenticada por header…
    const me = callsTo(fetchMock, '/me');
    expect(me).toHaveLength(1);
    expect(me[0]?.method).toBe('GET');
    expect(me[0]?.url).toBe('/api/v1/me');
    expect(me[0]?.headers.authorization).toBe(`Bearer ${TOKEN}`);
    // …y no se volvió a pedir credenciales al servidor.
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(0);
    // La sesión persistida sigue en pie.
    expect(readPersistedSession()?.token).toBe(TOKEN);
  });

  // -----------------------------------------------------------------------------------
  // AT-10-01-10 — Sesión persistida inválida / expirada / revocada
  // -----------------------------------------------------------------------------------
  it('AT-10-01-10 (a: token persistido expirado): el chequeo local de RN-11 lo descarta sin llamar a la API y queda el formulario de login', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(-60) });
    // Sin handlers: si el cliente llamara a la API, la llamada fallaría de forma visible.
    const fetchMock = createFetchMock({});
    renderApp({ fetchImpl: fetchMock });

    // El formulario está disponible de entrada: no hay validación remota que esperar.
    expect(submitButton()).toBeTruthy();
    expect(screen.queryByTestId('session-validating')).toBeNull();
    expect(screen.queryByTestId('trading-account')).toBeNull();

    // Chequeo local de expiración (RN-11): ni una sola llamada a la API.
    expect(fetchMock).not.toHaveBeenCalled();
    // Y el token persistido quedó limpio.
    expect(globalThis.localStorage.getItem(STORAGE_KEY)).toBeNull();
    expect(dumpLocalStorage()).not.toContain(TOKEN);
  });

  it('AT-10-01-10 (b: token persistido revocado): GET /me → UNAUTHENTICATED (401) limpia el token persistido y muestra el formulario de login', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
    const fetchMock = createFetchMock({
      me: () => errorResponse(401, 'UNAUTHENTICATED', 'Token revocado.'),
    });
    renderApp({ fetchImpl: fetchMock });

    // Mientras el veredicto del servidor está en vuelo no se pide nada al usuario.
    expect(screen.getByTestId('session-validating')).toBeTruthy();

    // Con el 401 se muestra el formulario de login y no se navega a trading.
    expect(await screen.findByTestId('submit-login')).toBeTruthy();
    expect(screen.queryByTestId('trading-account')).toBeNull();
    expect(callsTo(fetchMock, '/me')).toHaveLength(1);
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(0);

    // Se limpió todo estado de sesión local, incluido el token persistido.
    expect(globalThis.localStorage.getItem(STORAGE_KEY)).toBeNull();
    expect(dumpLocalStorage()).not.toContain(TOKEN);
    // El arranque no muestra el aviso de RN-7 (ese corresponde a una sesión que estaba
    // activa y se cayó, no a una sesión persistida que el servidor ya no reconoce).
    expect(screen.queryByTestId('session-notice')).toBeNull();
  });

  // -----------------------------------------------------------------------------------
  // Reglas no cubiertas de forma directa por un AT
  // -----------------------------------------------------------------------------------

  it('RN-10 / RNE-3: el error se maneja por `code` y no por `message` (INVALID_CREDENTIALS con un message inesperado)', async () => {
    const rareza = 'cualquier cosa ' + 'jklñ-4711';
    const fetchMock = createFetchMock({
      login: () => errorResponse(401, 'INVALID_CREDENTIALS', rareza, { hint: rareza }),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    // El texto mostrado se deriva del `code` del catálogo, no del `message` del servidor.
    expect((await screen.findByTestId('login-error')).textContent).toBe(
      'Email o contraseña incorrectos',
    );
    expect(document.body.textContent ?? '').not.toContain(rareza);
    // Y el resto del comportamiento de RN-4 se aplica igual.
    expect(passwordInput().value).toBe('');
    expect(submitButton()).toBeTruthy();
  });

  it('RN-3: tras el login exitoso el token y su expiración quedan persistidos y la llamada protegida siguiente usa `Authorization: Bearer <token>`', async () => {
    const expiresAt = isoIn(7200);
    const fetchMock: FetchMock = createFetchMock({
      login: loginOk(TOKEN, expiresAt),
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());
    expect(await screen.findByTestId('trading-account')).toBeTruthy();

    // Token + expiración persistidos del lado del cliente para sobrevivir recargas.
    expect(readPersistedSession()).toEqual({ token: TOKEN, expiresAt });

    // La llamada de login no lleva el token (todavía no existe) ni lo pone en la URL…
    const login = callsTo(fetchMock, '/auth/login')[0];
    expect(login?.url).toBe('/api/v1/auth/login');
    expect(login?.url).not.toContain(TOKEN);
    expect(login?.headers.authorization).toBeUndefined();

    // …y la llamada protegida siguiente lo manda sólo por el header (nunca por la URL).
    const me = callsTo(fetchMock, '/me')[0];
    expect(me?.headers.authorization).toBe(`Bearer ${TOKEN}`);
