/**
 * Utilidades compartidas por la suite de aceptación de HU-10-01 (pantalla de login).
 *
 * Contiene: el montaje de la app con routing y sesión inyectables (`renderApp`), un mock de
 * `fetch` que discrimina por método + URL como lo haría la API real (`createFetchMock`),
 * constructores de respuestas con el envelope de `00-fundaciones/modelo-de-errores.md`
 * (`jsonResponse` / `errorResponse`) y acceso crudo al registro de sesión persistido.
 */
import { render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { vi, type Mock } from 'vitest';
import { App } from '../src/App';
import { SessionProvider } from '../src/session/SessionProvider';
import { LOGIN_ROUTE } from '../src/routes/paths';
import type { FetchLike } from '../src/api/client';
import type { StoredSession } from '../src/session/storage';

/**
 * Clave de `localStorage` del registro de sesión (contrato de `src/session/storage.ts`).
 * Se replica acá a propósito: los AT-10-01-07/09/10 y RN-3 afirman sobre el estado
 * persistido *desde afuera* del cliente, sin usar sus propios helpers de lectura.
 */
export const STORAGE_KEY = 'cex.web.session.v1';

/** Prefijo de la API que se le pasa explícitamente al provider en los tests. */
export const BASE_URL = '/api/v1';

/** Perfil que devuelve `GET /api/v1/me` (HU-09-01: `{accountId, email, status, createdAt}`). */
export const PROFILE = {
  accountId: 'acc_01HZY0000000000000000001',
  email: 'trader@example.com',
  status: 'ACTIVE',
  createdAt: '2026-01-05T10:00:00.000Z',
} as const;

/** Credenciales que tipea el usuario en la mayoría de los escenarios. */
export const CREDENTIALS = {
  email: 'trader@example.com',
  password: 'Contrasena-Muy-Larga-1234',
} as const;

/** Instante ISO 8601 UTC desplazado `seconds` respecto de ahora. */
export function isoIn(seconds: number): string {
  return new Date(Date.now() + seconds * 1000).toISOString();
}

// --------------------------------------------------------------------------------------
// Mock de `fetch`
// --------------------------------------------------------------------------------------

