import { describe, expect, it } from 'vitest';
import { screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { CREDENTIALS, createFetchMock, dumpLocalStorage, errorResponse, renderApp } from './support';

describe('sonda', () => {
  it('¿corre clear() en un 401 de /auth/login?', async () => {
    globalThis.localStorage.setItem('cex.web.session.v1', 'basura-no-parseable');
    const fetchMock = createFetchMock({ login: () => errorResponse(401, 'UNAUTHENTICATED', 'x') });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });
    expect(dumpLocalStorage()).toContain('basura');
    await user.type(screen.getByLabelText('Email'), CREDENTIALS.email);
    await user.type(screen.getByLabelText('Contraseña'), CREDENTIALS.password);
    await user.click(screen.getByTestId('submit-login'));
    await new Promise((r) => setTimeout(r, 40));
    expect({
      storage: dumpLocalStorage(),
      notice: screen.queryByTestId('session-notice')?.textContent ?? null,
    }).toBe('VER');
  });
});
