describe('AT-10-01-06 — rate limit', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  /**
   * Avanza `seconds` segundos de temporizadores falsos, un tick por vez y cada uno dentro
   * de su propio `act`. Hace falta ir de a uno porque el componente **encadena** un
   * `setTimeout` de 1 s por tick: el temporizador del segundo siguiente sólo se programa
   * cuando React vuelve a renderizar y corre el efecto, y eso ocurre al salir de `act`.
   */
  async function tick(seconds: number) {
    for (let i = 0; i < seconds; i += 1) {
      await act(async () => {
        await vi.advanceTimersByTimeAsync(1000);
      });
    }
  }

  it('AT-10-01-06: RATE_LIMITED (429) deshabilita el botón, informa los 30 segundos de espera y lo rehabilita al transcurrir', async () => {
    vi.useFakeTimers();
    // `retryAfterSeconds` viaja como **entero JSON** (no string), según el escenario 6.
    const fetchMock = createFetchMock({
      login: () =>
        errorResponse(429, 'RATE_LIMITED', 'Se superó el límite de solicitudes.', {
          retryAfterSeconds: 30,
        }),
    });
    renderApp({ fetchImpl: fetchMock });

    // Con temporizadores falsos se usa `fireEvent` en lugar de `user-event`.
    fireEvent.change(emailInput(), { target: { value: CREDENTIALS.email } });
    fireEvent.change(passwordInput(), { target: { value: CREDENTIALS.password } });
    expect(submitButton().disabled).toBe(false);

    await act(async () => {
      fireEvent.submit(loginForm());
    });

    // Botón bloqueado y aviso con el lapso exacto informado por el servidor.
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(1);
    expect(submitButton().disabled).toBe(true);
    expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');

    // A mitad de la espera todavía está bloqueado (la cuenta regresiva avanza).
    await tick(15);
    expect(submitButton().disabled).toBe(true);
    expect(screen.getByTestId('login-error').textContent).toContain('15 segundos');

    // Transcurrido el tiempo indicado, el botón se rehabilita (RN-6).
    await tick(15);
    expect(submitButton().disabled).toBe(false);
    expect(screen.queryByTestId('login-error')).toBeNull();

    // Y un reenvío ya sí llega a la API.
    await act(async () => {
      fireEvent.submit(loginForm());
    });
    expect(callsTo(fetchMock, '/auth/login')).toHaveLength(2);
  });
});

