import userEvent from '@testing-library/user-event';
import {
  CREDENTIALS,
  PROFILE,
  createFetchMock,
  errorResponse,
  isoIn,
  jsonResponse,
  readPersistedSession,
  renderApp,
  seedStoredSession,
} from './support';

const TOKEN = 'tok_borde_0123456789';

function emailInput(): HTMLInputElement {
  return screen.getByLabelText('Email') as HTMLInputElement;
}
function passwordInput(): HTMLInputElement {
  return screen.getByLabelText('Contraseña') as HTMLInputElement;
}
function submitButton(): HTMLButtonElement {
  return screen.getByTestId('submit-login') as HTMLButtonElement;
