describe('HU-10-01 — bordes no fijados por la spec', () => {
  /**
   * RN-6 toma la espera de `details.retryAfterSeconds`, que el escenario 6 fija como entero
   * JSON. Un servidor que lo serializara como string de dígitos no es conforme, pero el
   * cliente lo tolera: perder la espera (y con ella el bloqueo del botón) sería peor que
   * aceptar la forma laxa, y aceptarla no puede alterar el caso conforme.
   */
  it('RN-6 (tolerancia): un `retryAfterSeconds` como string de dígitos también bloquea el botón', async () => {
    const fetchMock = createFetchMock({
      login: () =>
        errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.', { retryAfterSeconds: '30' }),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await user.type(emailInput(), CREDENTIALS.email);
    await user.type(passwordInput(), CREDENTIALS.password);
    await user.click(submitButton());

    await waitFor(() => {
      expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');
    });
    expect(submitButton().disabled).toBe(true);
  });

  /**
   * RN-6 sin espera utilizable: no hay lapso que contar, así que se informa el límite pero
   * no se bloquea el botón por un tiempo inventado. Caso inalcanzable con un backend
   * conforme (`{ retryAfterSeconds }` es el `details` esperado del catálogo).
   */
  it('RN-6 (degradación): sin `retryAfterSeconds` utilizable se informa el límite sin bloquear el botón', async () => {
    const fetchMock = createFetchMock({
      login: () => errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.'),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await user.type(emailInput(), CREDENTIALS.email);
    await user.type(passwordInput(), CREDENTIALS.password);
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    expect(error.textContent).toContain('Demasiados intentos');
    expect(submitButton().disabled).toBe(false);
  });

