  it('RN-11 (fallo de red en la validación): conserva el token, avisa de la conexión y permite reintentar', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
    let attempts = 0;
    const fetchMock = createFetchMock({
      me: () => {
        attempts += 1;
        if (attempts === 1) return Promise.reject(new TypeError('Failed to fetch'));
        return jsonResponse(200, PROFILE);
      },
    });
    renderApp({ fetchImpl: fetchMock });

    // Sin veredicto del servidor no se descarta la sesión…
    await screen.findByTestId('validation-unavailable');
    expect(readPersistedSession()?.token).toBe(TOKEN);
    // …y el formulario está disponible por si el usuario prefiere autenticarse de nuevo.
    expect(submitButton()).toBeTruthy();
    expect(screen.queryByTestId('trading-account')).toBeNull();
    // Tampoco se muestra el aviso de sesión expirada: no hubo 401 (RN-7 no aplica).
    expect(screen.queryByTestId('session-notice')).toBeNull();

    // Al reintentar, el `GET /me` responde 200 y recién ahí se entra a trading.
    const user = userEvent.setup();
    await act(async () => {
      await user.click(screen.getByText('Reintentar validación'));
    });
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(attempts).toBe(2);
  });
});
