   174	  if (error instanceof ApiError) {
   175	    if (isErrorCode(error.code)) {
   176	      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
   177	    }
   178	    return CONNECTION_ERROR_MESSAGE;
   179	  }
   180	  return CONNECTION_ERROR_MESSAGE;
