  1	/**
  2	 * Cliente HTTP de la API del exchange (contrato de la épica 09).
  3	 *
  4	 * - Ruta base `/api/v1` (HU-09-01: "todos los recursos cuelgan de `/api/v1`").
  5	 * - Autenticación por header `Authorization: Bearer <token>` (HU-09-02 RN-1). El contrato
  6	 *   **no** usa cookies de sesión (HU-10-01 RN-3), así que no se envían credenciales de
  7	 *   navegador (`credentials: 'omit'`).
  8	 * - Toda respuesta de error se traduce a `ApiError` con el `code` del catálogo; cualquier
  9	 *   otra falla (red, respuesta ilegible) a `NetworkError`.
 10	 */
 11	import { ApiError, NetworkError } from './errors';
 12	
 13	export type FetchLike = (input: string, init?: RequestInit) => Promise<Response>;
 14	
 15	export interface ApiClientOptions {
 16	  /** Prefijo de la API. Por defecto, `VITE_API_BASE_URL` o `/api/v1`. */
 17	  baseUrl?: string;
 18	  /** Implementación de `fetch` (inyectable para tests). */
 19	  fetchImpl?: FetchLike;
 20	  /** Token Bearer vigente, o `null` si no hay sesión. */
 21	  getToken?: () => string | null;
 22	  /**
 23	   * Se invoca cuando una llamada **protegida** responde `UNAUTHENTICATED` (401): el cliente
 24	   * limpia la sesión local y vuelve a login (HU-10-01 RN-7 / RNE-4).
 25	   */
 26	  onUnauthenticated?: () => void;
 27	}
 28	
 29	export interface RequestOptions {
 30	  method?: 'GET' | 'POST' | 'DELETE';
 31	  body?: unknown;
 32	  /** Adjunta el header `Authorization` si hay token. */
 33	  auth?: boolean;
 34	  /**
 35	   * Si es `false`, un `UNAUTHENTICATED` no dispara el manejo global de sesión expirada.
 36	   * Lo usa la validación de sesión del arranque, que tiene su propio tratamiento
 37	   * (HU-10-01 RN-11: limpia la sesión y **permanece** en login, sin aviso de expiración).
 38	   */
 39	  handleUnauthenticated?: boolean;
 40	}
 41	
 42	function resolveDefaultBaseUrl(): string {
 43	  const fromEnv = import.meta.env?.VITE_API_BASE_URL;
 44	  return typeof fromEnv === 'string' && fromEnv.trim() !== '' ? fromEnv.trim() : '/api/v1';
 45	}
 46	
 47	function joinUrl(baseUrl: string, path: string): string {
 48	  const base = baseUrl.endsWith('/') ? baseUrl.slice(0, -1) : baseUrl;
 49	  const suffix = path.startsWith('/') ? path : `/${path}`;
 50	  return `${base}${suffix}`;
 51	}
 52	
 53	/** Extrae `{ code, details }` del envelope uniforme; `null` si el cuerpo no lo respeta. */
 54	function readErrorEnvelope(payload: unknown): { code: string; details?: Record<string, unknown> } | null {
 55	  if (typeof payload !== 'object' || payload === null) return null;
 56	  const error = (payload as Record<string, unknown>).error;
 57	  if (typeof error !== 'object' || error === null) return null;
 58	  const { code, details } = error as Record<string, unknown>;
 59	  if (typeof code !== 'string' || code === '') return null;
 60	  return {
 61	    code,
 62	    details:
 63	      typeof details === 'object' && details !== null && !Array.isArray(details)
 64	        ? (details as Record<string, unknown>)
 65	        : undefined,
 66	  };
 67	}
 68	
 69	export class ApiClient {
 70	  private readonly baseUrl: string;
 71	  private readonly fetchImpl: FetchLike;
 72	  private readonly getToken: () => string | null;
 73	  private readonly onUnauthenticated: (() => void) | undefined;
 74	
 75	  constructor(options: ApiClientOptions = {}) {
 76	    this.baseUrl = options.baseUrl ?? resolveDefaultBaseUrl();
 77	    this.fetchImpl =
 78	      options.fetchImpl ??
 79	      ((input, init) => {
 80	        if (typeof globalThis.fetch !== 'function') {
 81	          return Promise.reject(new NetworkError());
 82	        }
 83	        return globalThis.fetch(input, init);
 84	      });
 85	    this.getToken = options.getToken ?? (() => null);
 86	    this.onUnauthenticated = options.onUnauthenticated;
 87	  }
 88	
 89	  async request<T>(path: string, options: RequestOptions = {}): Promise<T> {
 90	    const { method = 'GET', body, auth = false, handleUnauthenticated = true } = options;
 91	    const headers: Record<string, string> = { accept: 'application/json' };
 92	    if (body !== undefined) headers['content-type'] = 'application/json';
 93	    if (auth) {
 94	      const token = this.getToken();
 95	      // El token viaja sólo en el header: nunca en la URL ni en el cuerpo (RN-3 / RNE-4).
 96	      if (token) headers.authorization = `Bearer ${token}`;
 97	    }
 98	
 99	    let response: Response;
100	    try {
101	      response = await this.fetchImpl(joinUrl(this.baseUrl, path), {
102	        method,
103	        headers,
104	        credentials: 'omit',
105	        ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
106	      });
107	    } catch {
108	      // Fallo de red: no se filtra el detalle del error subyacente (RN-8).
109	      throw new NetworkError();
110	    }
111	
112	    const raw = await response.text().catch(() => '');
113	    let payload: unknown = undefined;
114	    if (raw !== '') {
115	      try {
116	        payload = JSON.parse(raw);
117	      } catch {
118	        payload = undefined;
119	      }
120	    }
121	
122	    if (!response.ok) {
123	      const envelope = readErrorEnvelope(payload);
124	      // Una respuesta de error sin envelope del catálogo no es interpretable por `code`
125	      // (RN-10): se trata como falla de conexión y se informa con el mensaje de RN-8.
126	      if (!envelope) throw new NetworkError();
127	      if (envelope.code === 'UNAUTHENTICATED' && handleUnauthenticated) {
128	        this.onUnauthenticated?.();
129	      }
130	      throw new ApiError(envelope.code, response.status, envelope.details);
131	    }
132	
133	    return payload as T;
134	  }
135	}
136	/**
137	 * Catálogo de errores de la API y derivación de los mensajes que ve el usuario.
138	 *
139	 * Fuente de verdad: `spec/00-fundaciones/modelo-de-errores.md` y
140	 * `spec/09-api-http-websocket/HU-09-05-modelo-de-errores-api.md`.
141	 *
142	 * Regla central (épica 10 RNE-3 / HU-10-01 RN-10): **todo error se discrimina por su
143	 * `code`**, nunca por el `message` del servidor. El `message` que llega en el envelope
144	 * está orientado a diagnóstico y su literal no es estable: no se muestra en la UI, para no
145	 * acoplarse a él y para no filtrar detalle del error (HU-10-01 RN-8).
146	 */
147	
148	/** Códigos del catálogo (espacio de nombres plano y cerrado, §3 del modelo de errores). */
149	export const ERROR_CODES = [
150	  // 3.1 Autenticación y autorización
151	  'UNAUTHENTICATED',
152	  'UNAUTHORIZED',
153	  'RATE_LIMITED',
154	  // 3.2 Validación general
155	  'VALIDATION_ERROR',
156	  'NOT_FOUND',
157	  'METHOD_NOT_ALLOWED',
158	  // 3.3 Trading: validación de órdenes
159	  'INVALID_PRICE_TICK',
160	  'INVALID_LOT_SIZE',
161	  'BELOW_MIN_NOTIONAL',
162	  'INVALID_SIDE',
163	  'INVALID_ORDER_TYPE',
164	  'PRICE_REQUIRED',
165	  'PRICE_NOT_ALLOWED',
166	  // 3.4 Trading: estado y ejecución
167	  'INSUFFICIENT_FUNDS',
168	  'ORDER_NOT_FOUND',
169	  'ORDER_NOT_CANCELLABLE',
170	  'SELF_TRADE_BLOCKED',
171	  'MARKET_NO_LIQUIDITY',
172	  'MARKET_BUDGET_INSUFFICIENT',
173	  'DUPLICATE_CLIENT_ORDER_ID',
174	  // 3.5 On-chain
175	  'INVALID_ADDRESS',
176	  'WITHDRAWAL_BELOW_MIN',
177	  'WITHDRAWAL_AMOUNT_INVALID',
178	  'DEPOSIT_ALREADY_CREDITED',
179	  'DEPOSIT_NOT_CONFIRMED',
180	  'CHAIN_ID_MISMATCH',
181	  'NONCE_CONFLICT',
182	  'BROADCAST_FAILED',
183	  // 3.6 Cuentas
184	  'EMAIL_ALREADY_EXISTS',
185	  'INVALID_CREDENTIALS',
186	  'ACCOUNT_NOT_FOUND',
187	  // 3.7 Genéricos / sistema
188	  'CONFLICT',
189	  'INTERNAL_ERROR',
190	] as const;
191	
192	export type ErrorCode = (typeof ERROR_CODES)[number];
193	
194	export function isErrorCode(value: unknown): value is ErrorCode {
195	  return typeof value === 'string' && (ERROR_CODES as readonly string[]).includes(value);
196	}
197	
198	/** Una causa de fallo de esquema, tal como viaja en `details.issues` (HU-10-01 RN-5). */
199	export interface ValidationIssue {
200	  field: string;
201	  message: string;
202	}
203	
204	/**
205	 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
206	 *
207	 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
208	 * `code` (RN-10) y así ningún detalle del error del backend puede terminar en pantalla
209	 * (RN-8).
210	 */
211	export class ApiError extends Error {
212	  readonly code: ErrorCode | string;
213	  readonly httpStatus: number;
214	  readonly details: Record<string, unknown> | undefined;
215	
216	  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
217	    super(`ApiError(${code})`);
218	    this.name = 'ApiError';
219	    this.code = code;
220	    this.httpStatus = httpStatus;
221	    this.details = details;
222	  }
223	
224	  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
225	  get issues(): ValidationIssue[] {
226	    const raw = this.details?.issues;
227	    if (!Array.isArray(raw)) return [];
228	    const issues: ValidationIssue[] = [];
229	    for (const item of raw) {
230	      if (typeof item === 'string') {
231	        issues.push({ field: '', message: item });
232	        continue;
233	      }
234	      if (typeof item !== 'object' || item === null) continue;
235	      const record = item as Record<string, unknown>;
236	      const field = record.field ?? record.path ?? record.name ?? '';
237	      const message = record.message ?? record.msg ?? '';
238	      issues.push({
239	        field: typeof field === 'string' ? field : String(field),
240	        message: typeof message === 'string' ? message : '',
241	      });
242	    }
243	    return issues;
244	  }
245	
246	  /**
