291	  UNAUTHENTICATED: SESSION_EXPIRED_MESSAGE,
292	  UNAUTHORIZED: 'No tenés permiso para esta operación',
293	  RATE_LIMITED: 'Demasiados intentos. Esperá unos segundos antes de reintentar',
294	  VALIDATION_ERROR: 'Revisá los datos ingresados',
295	  NOT_FOUND: 'El recurso solicitado no existe',
