309	  if (error instanceof ApiError) {
310	    if (isErrorCode(error.code)) {
311	      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
312	    }
313	    return CONNECTION_ERROR_MESSAGE;
314	  }
315	  return CONNECTION_ERROR_MESSAGE;
