  1	/**
  2	 * Estado de sesión del cliente (HU-10-01 RN-3, RN-7, RN-9, RN-11).
  3	 *
  4	 * Máquina de estados:
  5	 *
  6	 *   validating ──(GET /me → 200)──────────────► authenticated
  7	 *        │                                            │
  8	 *        ├─(sin token | token expirado local | 401)──►│
  9	 *        │                                            │
 10	 *        ▼                                            ▼
 11	 *     anonymous ◄──(UNAUTHENTICATED en llamada protegida: limpia sesión + aviso)──┘
 12	 *
 13	 * `validating` es el estado inicial sólo si hay un token persistido y no expirado: en ese
 14	 * caso la validez la decide el servidor con una llamada liviana `GET /me` (RN-11), no la
 15	 * inspección del token.
 16	 */
 17	import {
 18	  createContext,
 19	  useCallback,
 20	  useContext,
 21	  useEffect,
 22	  useMemo,
 23	  useRef,
 24	  useState,
 25	  type ReactNode,
 26	} from 'react';
 27	import { ApiClient, type FetchLike } from '../api/client';
 28	import { getProfile } from '../api/auth';
 29	import { ApiError, SESSION_EXPIRED_MESSAGE } from '../api/errors';
 30	import type { Profile } from '../api/auth';
 31	import {
 32	  clearStoredSession,
 33	  isExpired,
 34	  readStoredSession,
 35	  writeStoredSession,
 36	  type StoredSession,
 37	} from './storage';
 38	
 39	export type SessionStatus = 'validating' | 'anonymous' | 'authenticated';
 40	
 41	export interface SessionContextValue {
 42	  status: SessionStatus;
 43	  /** Perfil de la cuenta autenticada, cuando la validación de RN-11 lo devolvió. */
 44	  profile: Profile | null;
 45	  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-7). */
