189	export function useSession(): SessionContextValue {
190	  const value = useContext(SessionContext);
191	  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
192	  return value;
193	}
194	/**
195	 * Persistencia local de la sesión (HU-10-01 RN-3).
196	 *
197	 * El contrato de la épica 09 **no** emite cookies de sesión: la autenticación es por
198	 * header `Authorization: Bearer <token>`. Por eso el cliente "mantiene el token en memoria
199	 * de la SPA y lo persiste del lado del cliente junto con su expiración para sobrevivir
200	 * recargas, re-validando la sesión contra el servidor al cargar la app" (RN-3 / RN-11).
201	 *
202	 * Se usa `localStorage` para que la sesión sobreviva la recarga y el cierre de la pestaña
203	 * hasta su expiración. El token **nunca** se escribe en la URL, ni se renderiza, ni se
204	 * loguea (RNE-4). Si el almacenamiento no está disponible (modo privado, cuota, etc.) la
205	 * sesión sigue funcionando sólo en memoria: la lectura/escritura degrada sin romper.
206	 */
207	
208	const STORAGE_KEY = 'cex.web.session.v1';
209	
210	/** Sesión tal como se persiste: token y su expiración declarada por el servidor. */
211	export interface StoredSession {
212	  token: string;
213	  expiresAt: string;
214	}
215	
216	function storage(): Storage | null {
217	  try {
218	    return globalThis.localStorage ?? null;
219	  } catch {
220	    return null;
221	  }
222	}
223	
224	export function readStoredSession(): StoredSession | null {
225	  const store = storage();
226	  if (!store) return null;
227	  let raw: string | null;
228	  try {
229	    raw = store.getItem(STORAGE_KEY);
230	  } catch {
231	    return null;
232	  }
233	  if (!raw) return null;
234	  try {
235	    const parsed: unknown = JSON.parse(raw);
236	    if (typeof parsed !== 'object' || parsed === null) return null;
237	    const { token, expiresAt } = parsed as Record<string, unknown>;
238	    if (typeof token !== 'string' || token === '') return null;
239	    if (typeof expiresAt !== 'string' || expiresAt === '') return null;
240	    // Un `expiresAt` que no es una fecha parseable no permite aplicar el chequeo local de
241	    // expiración de RN-11: se descarta el registro entero.
242	    if (Number.isNaN(Date.parse(expiresAt))) return null;
243	    return { token, expiresAt };
244	  } catch {
245	    return null;
246	  }
247	}
248	
249	export function writeStoredSession(session: StoredSession): void {
250	  const store = storage();
251	  if (!store) return;
252	  try {
253	    store.setItem(STORAGE_KEY, JSON.stringify(session));
254	  } catch {
255	    /* almacenamiento no disponible: la sesión queda sólo en memoria */
256	  }
257	}
258	
259	export function clearStoredSession(): void {
260	  const store = storage();
261	  if (!store) return;
262	  try {
263	    store.removeItem(STORAGE_KEY);
264	  } catch {
265	    /* nada que limpiar si el almacenamiento no está disponible */
266	  }
267	}
268	
269	/** `true` si la expiración registrada ya pasó (chequeo **local** de RN-11). */
270	export function isExpired(session: StoredSession, now: number = Date.now()): boolean {
271	  const expiresAtMs = Date.parse(session.expiresAt);
272	  if (Number.isNaN(expiresAtMs)) return true;
273	  return expiresAtMs <= now;
274	}

