295	            <p className="field-error" id={`${passwordId}-error`} data-testid="password-error">
296	              {fieldErrors.password}
297	            </p>
298	          )}
299	        </div>
300	
301	        {generalIssues.length > 0 && (
302	          <ul className="alert alert-error" role="alert" data-testid="general-issues">
303	            {generalIssues.map((issue) => (
304	              <li key={issue}>{issue}</li>
305	            ))}
306	          </ul>
307	        )}
308	
309	        {errorMessage !== null && (
310	          <p className="alert alert-error" role="alert" data-testid="login-error">
311	            {errorMessage}
312	            {retryable && (
313	              <>
314	                {' '}
315	                <button
316	                  type="button"
317	                  className="link"
318	                  onClick={() => void attemptLogin()}
319	                  data-testid="retry-login"
320	                >
321	                  Reintentar
322	                </button>
323	              </>
324	            )}
325	          </p>
326	        )}
327	
328	        <button type="submit" disabled={!canSubmit} data-testid="submit-login">
329	          {submitting ? 'Ingresando…' : 'Ingresar'}
330	        </button>
331	      </form>
332	    </main>
333	  );
334	}

