  1	/**
  2	 * Superficie HTTP de la API (épica 09, alcance de esta etapa).
  3	 *
  4	 * Contrato: ruta base `/api/v1`, envelope uniforme de error
  5	 * `{ error: { code, message, details? } }`, un solo error por respuesta según la
  6	 * precedencia determinista, y autenticación por token Bearer en los recursos protegidos.
  7	 */
  8	import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from 'fastify';
  9	import { AppError, validationError } from '../core/errors';
 10	import { CHAIN_ID, NETWORK_NAME, type Config } from '../core/config';
 11	import { nowIso } from '../core/time';
 12	import { normalizeEmail } from '../core/validation';
 13	import type { Db } from '../db/index';
 14	import type { AuditLog } from '../core/audit';
 15	import type { AccountService } from '../modules/accounts/service';
 16	import type { SessionService } from '../modules/accounts/sessions';
 17	import type { WalletService } from '../modules/wallet/service';
 18	import { SlidingWindowLimiter } from './rateLimit';
 19	
 20	export interface AppDependencies {
 21	  config: Config;
 22	  db: Db;
 23	  accounts: AccountService;
 24	  sessions: SessionService;
 25	  wallet: WalletService;
 26	  audit: AuditLog;
 27	}
 28	
 29	/** Verbos soportados por cada ruta existente (para responder 405 y no 404). */
 30	const ROUTE_METHODS: Record<string, string[]> = {
 31	  '/health': ['GET', 'HEAD'],
 32	  '/api/v1/auth/register': ['POST'],
 33	  '/api/v1/auth/login': ['POST'],
 34	  '/api/v1/me': ['GET', 'HEAD'],
 35	  '/api/v1/deposit-address': ['GET', 'HEAD'],
 36	  '/internal/deposit-addresses': ['GET', 'HEAD'],
 37	};
 38	
 39	const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
 40	type SupportedAsset = (typeof SUPPORTED_ASSETS)[number];
 41	
 42	function normalizePath(url: string): string {
 43	  const pathname = url.split('?')[0];
 44	  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
 45	  return pathname;
 46	}
 47	
 48	/**
 49	 * Error de parseo del cuerpo diferido hasta después del paso 0 de la precedencia
 50	 * (rate limiting) y de la autenticación. Se guarda en la request bajo un símbolo propio.
 51	 */
 52	const DEFERRED_BODY_ERROR = Symbol('deferredBodyError');
 53	
 54	type RequestWithDeferredError = { [DEFERRED_BODY_ERROR]?: AppError };
 55	
 56	function deferBodyError(request: unknown, error: AppError): void {
 57	  (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR] = error;
 58	}
 59	
 60	/** Levanta el error de parseo diferido, si lo hubo. */
 61	function throwDeferredBodyError(request: unknown): void {
 62	  const error = (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR];
 63	  if (error) throw error;
 64	}
 65	
 66	function singleQueryValue(value: unknown): string | undefined {
 67	  if (value === undefined) return undefined;
 68	  if (Array.isArray(value)) return value.length > 0 ? String(value[value.length - 1]) : undefined;
 69	  return String(value);
 70	}
 71	
 72	export function buildApp(deps: AppDependencies): FastifyInstance {
 73	  const { config, accounts, sessions, wallet, audit } = deps;
 74	
 75	  const app = Fastify({
 76	    logger: { level: config.logLevel },
 77	    ajv: { customOptions: { allErrors: true } },
 78	  });
 79	
 80	  const apiLimiter = new SlidingWindowLimiter(config.apiRateLimit);
 81	  const registerLimiter = new SlidingWindowLimiter(config.registerRateLimit);
 82	  const loginFailureLimiter = new SlidingWindowLimiter(config.loginRateLimit);
 83	
 84	  // ---------------------------------------------------------------------------
 85	  // CORS (soporte de despliegue, NO especificado): la spec no menciona CORS. El cliente
 86	  // web de la épica 10 corre en otro origen (`http://localhost:5173` en desarrollo) y, si
 87	  // le pega directo al backend en lugar de vía proxy, el navegador exige estos headers.
 88	  //
 89	  // Apagado por defecto: con `CORS_ALLOWED_ORIGINS` vacía o ausente no se emite ningún
 90	  // header de CORS y el comportamiento observable es idéntico al de antes. Sólo se
 91	  // habilitan orígenes **exactos** de la lista; un `Origin` que no está en ella no recibe
 92	  // headers (el navegador bloquea) y su status no cambia.
 93	  //
 94	  // No se habilita `Access-Control-Allow-Credentials`: el contrato no usa cookies
 95	  // (HU-10-01 RN-3), la autenticación es por header `Authorization: Bearer`.
 96	  // ---------------------------------------------------------------------------
 97	  if (config.corsAllowedOrigins.length > 0) {
 98	    const allowedOrigins = new Set(config.corsAllowedOrigins);
 99	    const allowedMethods = 'GET, HEAD, POST, DELETE, OPTIONS';
100	    const allowedHeaders = 'Authorization, Content-Type';
101	    const maxAgeSeconds = '600';
102	    app.addHook('onRequest', async (request, reply) => {
103	      const origin = request.headers.origin;
104	      if (typeof origin !== 'string' || !allowedOrigins.has(origin)) return;
105	      reply.header('Access-Control-Allow-Origin', origin);
106	      // La respuesta depende del `Origin` de la request: es cacheable por origen (RFC 9110).
107	      reply.header('Vary', 'Origin');
108	      if (request.method !== 'OPTIONS') return;
109	      // Preflight: se responde acá mismo, antes del enrutado, para que no caiga en el
110	      // handler de 404/405 ni en el de errores.
111	      reply.header('Access-Control-Allow-Methods', allowedMethods);
112	      reply.header('Access-Control-Allow-Headers', allowedHeaders);
113	      reply.header('Access-Control-Max-Age', maxAgeSeconds);
114	      await reply.status(204).send();
115	      return reply;
116	    });
117	  }
118	
119	  // ---------------------------------------------------------------------------
120	  // Parseo del cuerpo: cualquier cuerpo se interpreta como JSON. Un cuerpo que no sea
121	  // JSON válido produce VALIDATION_ERROR (422) — HU-09-01 RN-3.
122	  //
123	  // El fallo de parseo NO se emite acá: el parser corre antes que los handlers, y el rate
124	  // limiting es el **paso 0** de la precedencia, anterior a cualquier validación "incluso
125	  // la de esquema" (HU-01-01 RN-9/RN-10, HU-01-02 RN-8/RN-9). Por eso el error queda
126	  // diferido en la request y lo levanta el handler *después* de evaluar el límite y, en los
127	  // recursos protegidos, después de autenticar (HU-09-02 RN-9 / AT-09-05-04). Para las
128	  // rutas sin cuerpo ni precedencia propia, el hook `preHandler` de más abajo lo levanta
129	  // antes del handler, de modo que nunca se ignora en silencio.
130	  // ---------------------------------------------------------------------------
131	  app.removeContentTypeParser(['application/json', 'text/plain']);
132	  app.addContentTypeParser('*', { parseAs: 'string' }, (request, body: string, done) => {
133	    const contentType = request.headers['content-type'];
134	    if (contentType && !/json/i.test(contentType)) {
135	      deferBodyError(
136	        request,
137	        validationError([{ field: 'Content-Type', message: 'Se espera application/json.' }]),
138	      );
139	      done(null, undefined);
140	      return;
141	    }
142	    if (body === undefined || body === null || body.length === 0) {
143	      done(null, undefined);
144	      return;
145	    }
146	    try {
147	      done(null, JSON.parse(body));
148	    } catch {
149	      deferBodyError(
150	        request,
151	        validationError([{ field: 'body', message: 'El cuerpo no es JSON válido.' }]),
152	      );
153	      done(null, undefined);
154	    }
155	  });
156	
157	  // Rutas cuyo handler levanta el error diferido en el punto exacto que le fija su
158	  // precedencia (después del rate limiting y de la autenticación). Para cualquier otra
159	  // ruta, la red de seguridad de abajo lo levanta antes del handler, de modo que un cuerpo
160	  // que no parsea nunca se ignora en silencio.
161	  const ROUTES_WITH_ORDERED_BODY_CHECK = new Set([
162	    '/api/v1/auth/register',
163	    '/api/v1/auth/login',
164	    '/api/v1/me',
165	    '/api/v1/deposit-address',
166	    '/internal/deposit-addresses',
167	  ]);
168	  app.addHook('preHandler', async (request) => {
169	    if (ROUTES_WITH_ORDERED_BODY_CHECK.has(normalizePath(request.url))) return;
170	    throwDeferredBodyError(request);
171	  });
172	
173	  // ---------------------------------------------------------------------------
174	  // Manejo uniforme de errores (HU-09-05).
175	  // ---------------------------------------------------------------------------
176	  function sendError(reply: FastifyReply, error: AppError): FastifyReply {
177	    if (error.headers) {
178	      for (const [name, value] of Object.entries(error.headers)) reply.header(name, value);
179	    }
180	    return reply.status(error.httpStatus).send(error.toEnvelope());
181	  }
182	
183	  app.setErrorHandler((error, request, reply) => {
184	    if (error instanceof AppError) {
185	      return sendError(reply, error);
186	    }
187	    const fastifyCode = (error as { code?: string }).code ?? '';
188	    if (
189	      fastifyCode.startsWith('FST_ERR_CTP_') ||
190	      fastifyCode === 'FST_ERR_VALIDATION' ||
191	      (typeof (error as { statusCode?: number }).statusCode === 'number' &&
192	        (error as { statusCode: number }).statusCode === 400)
193	    ) {
194	      return sendError(
195	        reply,
196	        validationError([{ field: 'body', message: 'Cuerpo o parámetros inválidos.' }]),
197	      );
198	    }
199	    // INTERNAL_ERROR no filtra detalles sensibles (HU-09-05 RN-9); el detalle queda en el
200	    // log del servidor.
201	    request.log.error({ err: error }, 'error interno no clasificado');
202	    return sendError(reply, new AppError('INTERNAL_ERROR', 'Error interno del servidor.'));
203	  });
204	
205	  app.setNotFoundHandler((request, reply) => {
206	    const pathname = normalizePath(request.url);
207	    const allowed = ROUTE_METHODS[pathname];
208	    if (allowed && !allowed.includes(request.method)) {
209	      return sendError(
210	        reply,
211	        new AppError('METHOD_NOT_ALLOWED', 'Método no permitido sobre la ruta.', {
212	          method: request.method,
213	          allowed,
214	        }),
215	      );
216	    }
217	    return sendError(
218	      reply,
219	      new AppError('NOT_FOUND', 'Recurso inexistente.', { resource: 'route', id: pathname }),
220	    );
221	  });
222	
223	  // ---------------------------------------------------------------------------
224	  // Autenticación (HU-09-02 RN-1..RN-4): se evalúa antes que cualquier validación de
225	  // esquema o regla de negocio (RN-9).
226	  // ---------------------------------------------------------------------------
227	  function authenticate(request: FastifyRequest): { accountId: string } {
228	    const header = request.headers.authorization;
229	    if (!header || typeof header !== 'string') throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
230	    // El nombre del esquema es case-insensitive (RFC 7235); el valor del token no.
231	    const match = /^Bearer[ \t]+(.+)$/i.exec(header.trim());
232	    if (!match) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
233	    const identity = sessions.resolve(match[1].trim());
234	    if (!identity) throw new AppError('UNAUTHENTICATED', 'Credencial ausente o inválida.');
235	    return { accountId: identity.accountId };
236	  }
237	
238	  function enforceApiRateLimit(accountId: string, routeKey: string): void {
239	    const decision = apiLimiter.consume(`${accountId}|${routeKey}`);
240	    if (decision.limited) {
241	      throw new AppError(
242	        'RATE_LIMITED',
243	        'Se superó el límite de solicitudes permitido.',
244	        { retryAfterSeconds: decision.retryAfterSeconds },
245	        { 'Retry-After': String(decision.retryAfterSeconds) },
246	      );
247	    }
248	  }
249	
250	  // ---------------------------------------------------------------------------
251	  // Health check
252	  // ---------------------------------------------------------------------------
253	  app.get('/health', async () => ({
254	    status: 'ok',
255	    service: 'cex-backend',
256	    time: nowIso(),
257	    network: NETWORK_NAME,
258	    chainId: CHAIN_ID,
259	    rpcConfigured: config.ethRpcUrl !== '',
260	  }));
261	
262	  // ---------------------------------------------------------------------------
263	  // HU-01-01 — Registro (público, 201)
264	  // ---------------------------------------------------------------------------
265	  app.post('/api/v1/auth/register', async (request, reply) => {
266	    // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): rate limiting antes de todo.
267	    const decision = registerLimiter.consume(`${request.ip}`);
268	    if (decision.limited) {
269	      throw new AppError(
270	        'RATE_LIMITED',
271	        'Se superó el límite de registros permitido desde este origen.',
272	        { retryAfterSeconds: decision.retryAfterSeconds },
273	        { 'Retry-After': String(decision.retryAfterSeconds) },
274	      );
275	    }
276	    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
277	    throwDeferredBodyError(request);
278	    const account = await accounts.register(request.body, request.ip ?? null);
279	    return reply.status(201).send(account);
280	  });
281	
282	  // ---------------------------------------------------------------------------
283	  // HU-01-02 — Login (público, 200)
284	  // ---------------------------------------------------------------------------
285	  app.post('/api/v1/auth/login', async (request, reply) => {
286	    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
287	    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
288	    const rawEmail =
289	      typeof request.body === 'object' &&
290	      request.body !== null &&
291	      typeof (request.body as Record<string, unknown>).email === 'string'
292	        ? normalizeEmail((request.body as Record<string, string>).email)
293	        : '';
294	    const limiterKey = `${request.ip}|${rawEmail}`;
295	    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
296	    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
297	    // (HU-01-02 RN-8).
298	    const decision =
299	      rawEmail === ''
300	        ? loginFailureLimiter.peekByPrefix(`${request.ip}|`)
301	        : loginFailureLimiter.peek(limiterKey);
302	    if (decision.limited) {
303	      audit.record({
304	        event: 'LOGIN',
305	        email: rawEmail || null,
306	        result: 'FAILURE',
307	        reason: 'RATE_LIMITED',
308	        origin: request.ip ?? null,
309	      });
310	      throw new AppError(
311	        'RATE_LIMITED',
312	        'Se superó el límite de intentos de autenticación.',
313	        { retryAfterSeconds: decision.retryAfterSeconds },
314	        { 'Retry-After': String(decision.retryAfterSeconds) },
315	      );
316	    }
317	    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-8).
318	    throwDeferredBodyError(request);
319	    try {
320	      const result = await accounts.login(request.body, request.ip ?? null);
321	      return reply.status(200).send(result);
322	    } catch (err) {
323	      if (err instanceof AppError && err.code === 'INVALID_CREDENTIALS') {
324	        loginFailureLimiter.record(limiterKey);
325	      }
326	      throw err;
327	    }
328	  });
329	
330	  // ---------------------------------------------------------------------------
331	  // HU-01-04 — Consulta de perfil propio (protegido, 200) — `GET /api/v1/me`
332	  // (mapa de endpoints de HU-09-01, AT-09-01-03).
333	  //
334	  // Sobre AT-01-04-05/06 (perfil de una cuenta ajena, `UNAUTHORIZED` 403): esos AT están
335	  // redactados **condicionalmente** ("Si la API expone el perfil por identificador, p. ej.
336	  // `/accounts/{accountId}`" — HU-01-04 RN-3). El contrato de la épica 09 **no** expone
337	  // `/accounts/{accountId}`: el único endpoint de perfil es `GET /api/v1/me`, que resuelve
338	  // la cuenta exclusivamente desde el token (RN-2 / HU-09-02 RN-4), así que no existe
339	  // superficie por la cual pedir el perfil de otra cuenta y la premisa del condicional no
340	  // se cumple. No se inventan rutas que la épica 09 no declara.
341	  //
342	  // En consecuencia, cualquier selector de cuenta inyectado (`?accountId=`, `X-Account-Id`,
343	  // un cuerpo con `accountId`) se **ignora**, igual que en `GET /api/v1/deposit-address`
344	  // (HU-06-04 RN-2): la respuesta es siempre el perfil del dueño del token, nunca un 403.
345	  // Eso mantiene el criterio del catálogo de errores (`UNAUTHORIZED` queda reservado a
346	  // operaciones que actúan explícitamente **a nombre de** otra cuenta, y los recursos
347	  // ajenos referenciados por id usan la familia NOT_FOUND para no filtrar existencia:
348	  // `modelo-de-errores.md` §3.1 y la nota de §3.4) y no filtra si la cuenta ajena existe.
349	  // La precedencia RN-8 se preserva de todos modos: sin credencial válida la respuesta es
350	  // `UNAUTHENTICATED` (401) antes de cualquier otra evaluación (AT-01-04-06).
351	  // ---------------------------------------------------------------------------
352	  app.get('/api/v1/me', async (request, reply) => {
353	    // Precedencia: UNAUTHENTICATED → rate limiting por cuenta y endpoint → esquema.
354	    const identity = authenticate(request);
355	    enforceApiRateLimit(identity.accountId, 'GET /api/v1/me');
356	    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
357	    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
358	    // VALIDATION_ERROR. Verificado por test: en un `GET` el cuerpo no se parsea, así que
359	    // hoy esto (y la pertenencia de la ruta a `ROUTES_WITH_ORDERED_BODY_CHECK`) es
360	    // defensivo — sostiene la precedencia por construcción, igual que en
361	    // `GET /api/v1/deposit-address`, sin depender de ese detalle del framework.
362	    throwDeferredBodyError(request);
363	
364	    const account = accounts.repository.findById(identity.accountId);
365	    // Defensa en profundidad: un token válido siempre resuelve a una cuenta existente
366	    // (la sesión tiene FK contra `accounts`). Si no existiera, se responde con el código
367	    // de cuentas del catálogo (`modelo-de-errores.md` §3.6) y nunca un 500.
368	    if (!account) {
369	      // `details` sigue la forma que el catálogo espera para este código: `{ accountId }`
370	      // (`modelo-de-errores.md` §3.6). Es la cuenta propia del token, no una ajena, así
371	      // que no revela nada de terceros.
372	      throw new AppError('ACCOUNT_NOT_FOUND', 'La cuenta no existe.', {
373	        accountId: identity.accountId,
374	      });
375	    }
376	    // Proyección explícita de los cuatro campos de identidad (HU-01-04 RN-4): sin
377	    // balances (RN-6), sin hash, sin sal y sin token (RN-5). La lectura no toca la sesión:
378	    // no se renueva `expires_at` (RN-7).
379	    return reply.status(200).send({
380	      accountId: account.accountId,
381	      email: account.email,
382	      status: account.status,
383	      createdAt: account.createdAt,
384	    });
385	  });
386	
387	  // ---------------------------------------------------------------------------
388	  // HU-06-04 — Consulta de dirección de depósito (protegido, 200)
389	  // ---------------------------------------------------------------------------
390	  app.get('/api/v1/deposit-address', async (request, reply) => {
391	    // Precedencia (HU-06-04 RN-9): UNAUTHENTICATED → UNAUTHORIZED → esquema/activo →
392	    // red → asignación/lectura.
393	    const identity = authenticate(request);
394	    enforceApiRateLimit(identity.accountId, 'GET /api/v1/deposit-address');
395	    // Recién ahora, después de la autenticación (HU-09-02 RN-9 / AT-09-05-04), se reporta
396	    // un cuerpo que no parsea: sin token la respuesta es UNAUTHENTICATED, no
397	    // VALIDATION_ERROR.
398	    throwDeferredBodyError(request);
399	
400	    const query = (request.query ?? {}) as Record<string, unknown>;
401	    const asset = singleQueryValue(query.asset);
402	    if (asset === undefined || !SUPPORTED_ASSETS.includes(asset as SupportedAsset)) {
403	      throw validationError([
404	        {
405	          field: 'asset',
406	          message: `El activo debe ser uno de: ${SUPPORTED_ASSETS.join(', ')}.`,
407	        },
408	      ]);
409	    }
410	
411	    // La red es implícitamente Sepolia; si la consulta declara otra, se rechaza (RN-4).
412	    const chainIdParam = singleQueryValue(query.chainId);
413	    if (chainIdParam !== undefined && chainIdParam.trim() !== CHAIN_ID) {
414	      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
415	        expected: CHAIN_ID,
416	        got: chainIdParam,
417	      });
418	    }
419	    const networkParam = singleQueryValue(query.network);
420	    if (networkParam !== undefined && networkParam.trim().toLowerCase() !== NETWORK_NAME) {
421	      throw new AppError('CHAIN_ID_MISMATCH', 'La única red soportada es Sepolia.', {
422	        expected: CHAIN_ID,
423	        got: networkParam,
424	      });
425	    }
426	
427	    // La identidad sale exclusivamente del token: cualquier selector de cuenta inyectado
428	    // por query o body se ignora (RN-2).
429	    const record = wallet.getOrAssign(identity.accountId);
430	
431	    const body: Record<string, string> = {
432	      asset,
433	      address: record.address,
434	      network: record.network,
435	      chainId: record.chainId,
436	      derivationPath: record.derivationPath,
437	    };
438	    if (asset === 'USDC') body.tokenAddress = config.usdcContractAddress;
439	    return reply.status(200).send(body);
440	  });
441	
442	  // ---------------------------------------------------------------------------
443	  // Consulta interna del conjunto de direcciones asignadas (HU-06-03 RN-11).
444	  // No es pública: requiere `X-Internal-Token` o provenir de loopback.
445	  // ---------------------------------------------------------------------------
446	  app.get('/internal/deposit-addresses', async (request, reply) => {
447	    const token = request.headers['x-internal-token'];
448	    const isLoopback = ['127.0.0.1', '::1', '::ffff:127.0.0.1'].includes(request.ip);
449	    const authorized = config.internalApiToken
450	      ? token === config.internalApiToken
451	      : isLoopback;
452	    if (!authorized) throw new AppError('UNAUTHENTICATED', 'Credencial interna ausente o inválida.');
453	    throwDeferredBodyError(request);
454	    return reply.status(200).send({
455	      network: NETWORK_NAME,
456	      chainId: CHAIN_ID,
457	      items: wallet.listAll().map((record) => ({
458	        accountId: record.accountId,
459	        addressIndex: record.addressIndex,
