    14	export interface RateLimitDecision {
    15	  limited: boolean;
    16	  retryAfterSeconds: number;
    17	}
    18	
    19	export class SlidingWindowLimiter {
    20	  private readonly hits = new Map<string, number[]>();
    21	
    22	  constructor(private readonly policy: RateLimitPolicy) {}
    23	
    24	  get enabled(): boolean {
    25	    return this.policy.enabled;
    26	  }
    27	
    28	  private prune(key: string, now: number): number[] {
    29	    const windowMs = this.policy.windowSeconds * 1000;
    30	    const entries = (this.hits.get(key) ?? []).filter((t) => now - t < windowMs);
    31	    if (entries.length > 0) this.hits.set(key, entries);
    32	    else this.hits.delete(key);
    33	    return entries;
    34	  }
    35	
    36	  private retryAfter(entries: number[], now: number): number {
    37	    const windowMs = this.policy.windowSeconds * 1000;
    38	    const oldest = entries[0];
    39	    if (oldest === undefined) return 0;
    40	    return Math.max(0, Math.ceil((oldest + windowMs - now) / 1000));
    41	  }
    42	
    43	  /** Consume una unidad de cuota. Devuelve si la request debe rechazarse con 429. */
    44	  consume(key: string, now = Date.now()): RateLimitDecision {
    45	    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    46	    const entries = this.prune(key, now);
    47	    if (entries.length >= this.policy.max) {
    48	      return { limited: true, retryAfterSeconds: this.retryAfter(entries, now) };
    49	    }
    50	    entries.push(now);
    51	    this.hits.set(key, entries);
    52	    return { limited: false, retryAfterSeconds: 0 };
    53	  }
    54	
    55	  /** Consulta sin consumir cuota (para políticas que sólo cuentan fallos). */
    56	  peek(key: string, now = Date.now()): RateLimitDecision {
    57	    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    58	    const entries = this.prune(key, now);
    59	    if (entries.length >= this.policy.max) {
    60	      return { limited: true, retryAfterSeconds: this.retryAfter(entries, now) };
    61	    }
    62	    return { limited: false, retryAfterSeconds: 0 };
    63	  }
    64	
    65	  /**
    66	   * Igual que `peek`, pero sobre **todas** las claves que empiezan con `prefix`: devuelve
    67	   * la decisión más restrictiva. Lo usa el login cuando el cuerpo de la solicitud no se
    68	   * pudo parsear y por lo tanto no hay email con el cual armar la clave exacta: el paso 0
    69	   * se evalúa igual (HU-01-02 RN-8/RN-9), tomando el origen como granularidad.
    70	   */
    71	  peekByPrefix(prefix: string, now = Date.now()): RateLimitDecision {
    72	    if (!this.policy.enabled) return { limited: false, retryAfterSeconds: 0 };
    73	    let worst: RateLimitDecision = { limited: false, retryAfterSeconds: 0 };
    74	    for (const key of [...this.hits.keys()]) {
    75	      if (!key.startsWith(prefix)) continue;
    76	      const decision = this.peek(key, now);
    77	      if (decision.limited && decision.retryAfterSeconds >= worst.retryAfterSeconds) {
    78	        worst = decision;
    79	      }
    80	    }
    81	    return worst;
    82	  }
    83	
    84	  /** Registra un evento (p. ej. un intento de login fallido) sin evaluar el umbral. */
    85	  record(key: string, now = Date.now()): void {
    86	    if (!this.policy.enabled) return;
    87	    const entries = this.prune(key, now);
    88	    entries.push(now);
    89	    this.hits.set(key, entries);
    90	  }
    91	
    92	  reset(): void {
    93	    this.hits.clear();
    94	  }
    95	}
