    34	      throw new ConfigError(
    35	        'CORS_ALLOWED_ORIGINS no admite el comodín "*": hay que listar orígenes exactos.',
    36	      );
    37	    }
    38	    let url: URL;
    39	    try {
    40	      url = new URL(value);
    41	    } catch {
    42	      throw new ConfigError(
    43	        `CORS_ALLOWED_ORIGINS debe listar orígenes con la forma "esquema://host[:puerto]"; ` +
    44	          `se recibió "${value}".`,
    45	      );
    46	    }
