    48	      (url.protocol === 'http:' || url.protocol === 'https:') &&
    49	      url.username === '' &&
    50	      url.password === '' &&
    51	      url.search === '' &&
    52	      url.hash === '' &&
    53	      (url.pathname === '' || url.pathname === '/') &&
    54	      url.origin === value;
