    56	      throw new ConfigError(
    57	        `CORS_ALLOWED_ORIGINS debe listar orígenes exactos "esquema://host[:puerto]" (http o ` +
    58	          `https, sin path, query, fragmento ni credenciales); se recibió "${value}".`,
    59	      );
