/**
 * Verificación end-to-end de la pantalla de login **contra el backend corriendo**.
 *
 * A diferencia del resto de la suite (que mockea `fetch` para poder fijar cada respuesta
 * del catálogo de errores), este archivo renderiza la pantalla real y la hace hablar por
 * HTTP con el backend de verdad: comprueba que el contrato que consume el cliente
 * (`POST /api/v1/auth/login`, `GET /api/v1/me` — épica 09) es el que el servidor expone.
 *
 * Está desactivado por defecto porque necesita un backend levantado. Para correrlo:
 *
 *   # terminal 1, en la raíz del repo
 *   npm run dev
 *   # terminal 2
 *   cd web && npm run test:e2e
 *
 * Variables: `WEB_E2E=1` lo habilita; `E2E_API_BASE_URL` apunta a la API
 * (default `http://localhost:3000/api/v1`).
 */
import { describe, expect, it, beforeAll } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter } from 'react-router-dom';
import { App } from '../src/App';
import { SessionProvider } from '../src/session/SessionProvider';
import { LOGIN_ROUTE } from '../src/routes/paths';

const enabled = process.env.WEB_E2E === '1';
const baseUrl = process.env.E2E_API_BASE_URL ?? 'http://localhost:3000/api/v1';

// `fetch` real (undici de Node): jsdom no implementa fetch, así que se inyecta explícito.
const realFetch: typeof fetch = (input, init) => globalThis.fetch(input as string, init);

const password = 'Sup3rSecreta';
let email = '';

function renderApp() {
  return render(
    <SessionProvider baseUrl={baseUrl} fetchImpl={realFetch}>
      <MemoryRouter initialEntries={[LOGIN_ROUTE]}>
        <App />
      </MemoryRouter>
    </SessionProvider>,
  );
}

describe.runIf(enabled)('E2E contra el backend corriendo (HU-10-01)', () => {
  beforeAll(async () => {
    // Cuenta nueva por corrida: el registro es idempotente sólo por email (HU-01-01 RN-8).
    email = `e2e-${Date.now()}-${Math.floor(Math.random() * 1e6)}@example.com`;
    const response = await realFetch(`${baseUrl}/auth/register`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    if (response.status !== 201) {
      throw new Error(
        `El backend no respondió 201 al registro (status ${response.status}). ` +
          `¿Está corriendo en ${baseUrl}?`,
      );
    }
  });

  it('login con credenciales correctas navega a la vista de trading [AT-10-01-01]', async () => {
    const user = userEvent.setup();
    renderApp();

    await user.type(await screen.findByLabelText('Email'), email);
    await user.type(screen.getByLabelText('Contraseña'), password);
    await user.click(screen.getByTestId('submit-login'));

    // La navegación posterior al login y la llamada protegida `GET /me` que muestra la
    // identidad de la cuenta prueban que la sesión quedó establecida y es utilizable.
    const account = await screen.findByTestId('trading-account', undefined, { timeout: 10_000 });
    await waitFor(() => expect(account.textContent).toContain(email));

    // El token no aparece en el DOM renderizado (RN-3 / RNE-4).
    const stored = JSON.parse(globalThis.localStorage.getItem('cex.web.session.v1') ?? '{}');
    expect(typeof stored.token).toBe('string');
    expect(stored.token.length).toBeGreaterThan(0);
    expect(document.body.innerHTML).not.toContain(stored.token);
  });

  it('credenciales incorrectas muestran el mensaje genérico [AT-10-01-02b]', async () => {
    const user = userEvent.setup();
