104	/**
105	 * `fetch` de mentira que enruta por método + URL. Una ruta sin handler declarado hace
106	 * fallar el test (el cliente la verá como fallo de red, pero la aserción del escenario no
107	 * se cumplirá y el mensaje queda en el listado de llamadas).
108	 */
109	export function createFetchMock(routes: RouteMap): FetchMock {
110	  return vi.fn(async (input: string, init?: RequestInit): Promise<Response> => {
111	    const call = describeCall(input, init);
112	    if (call.method === 'POST' && call.url.endsWith('/auth/login')) {
113	      if (!routes.login) throw new Error(`El test no esperaba una llamada a ${call.url}`);
114	      return routes.login(call);
115	    }
116	    if (call.method === 'GET' && call.url.endsWith('/me')) {
117	      if (!routes.me) throw new Error(`El test no esperaba una llamada a ${call.url}`);
118	      return routes.me(call);
119	    }
120	    throw new Error(`Ruta no mockeada: ${call.method} ${call.url}`);
121	  });
122	}
