161	export function deferred<T>(): Deferred<T> {
162	  let resolve!: (value: T) => void;
163	  let reject!: (reason: unknown) => void;
164	  const promise = new Promise<T>((res, rej) => {
165	    resolve = res;
166	    reject = rej;
167	  });
168	  return { promise, resolve, reject };
