206	/** Códigos del catálogo (espacio de nombres plano y cerrado, §3 del modelo de errores). */
207	export const ERROR_CODES = [
208	  // 3.1 Autenticación y autorización
209	  'UNAUTHENTICATED',
210	  'UNAUTHORIZED',
211	  'RATE_LIMITED',
212	  // 3.2 Validación general
213	  'VALIDATION_ERROR',
214	  'NOT_FOUND',
215	  'METHOD_NOT_ALLOWED',
216	  // 3.3 Trading: validación de órdenes
217	  'INVALID_PRICE_TICK',
218	  'INVALID_LOT_SIZE',
219	  'BELOW_MIN_NOTIONAL',
220	  'INVALID_SIDE',
221	  'INVALID_ORDER_TYPE',
222	  'PRICE_REQUIRED',
223	  'PRICE_NOT_ALLOWED',
224	  // 3.4 Trading: estado y ejecución
225	  'INSUFFICIENT_FUNDS',
226	  'ORDER_NOT_FOUND',
227	  'ORDER_NOT_CANCELLABLE',
228	  'SELF_TRADE_BLOCKED',
229	  'MARKET_NO_LIQUIDITY',
230	  'MARKET_BUDGET_INSUFFICIENT',
231	  'DUPLICATE_CLIENT_ORDER_ID',
232	  // 3.5 On-chain
233	  'INVALID_ADDRESS',
234	  'WITHDRAWAL_BELOW_MIN',
235	  'WITHDRAWAL_AMOUNT_INVALID',
236	  'DEPOSIT_ALREADY_CREDITED',
237	  'DEPOSIT_NOT_CONFIRMED',
238	  'CHAIN_ID_MISMATCH',
239	  'NONCE_CONFLICT',
240	  'BROADCAST_FAILED',
241	  // 3.6 Cuentas
242	  'EMAIL_ALREADY_EXISTS',
243	  'INVALID_CREDENTIALS',
244	  'ACCOUNT_NOT_FOUND',
245	  // 3.7 Genéricos / sistema
246	  'CONFLICT',
247	  'INTERNAL_ERROR',
248	] as const;
249	
250	export type ErrorCode = (typeof ERROR_CODES)[number];
251	
252	export function isErrorCode(value: unknown): value is ErrorCode {
253	  return typeof value === 'string' && (ERROR_CODES as readonly string[]).includes(value);
254	}
255	
256	/** Una causa de fallo de esquema, tal como viaja en `details.issues` (HU-10-01 RN-5). */
257	export interface ValidationIssue {
258	  field: string;
259	  message: string;
260	}
261	
262	/**
263	 * Error de dominio devuelto por la API: `{ error: { code, message, details } }`.
264	 *
265	 * Deliberadamente **no** conserva el `message` del servidor: la UI deriva su texto del
266	 * `code` (RN-10) y así ningún detalle del error del backend puede terminar en pantalla
267	 * (RN-8).
268	 */
269	export class ApiError extends Error {
270	  readonly code: ErrorCode | string;
271	  readonly httpStatus: number;
272	  readonly details: Record<string, unknown> | undefined;
273	
274	  constructor(code: ErrorCode | string, httpStatus: number, details?: Record<string, unknown>) {
275	    super(`ApiError(${code})`);
276	    this.name = 'ApiError';
277	    this.code = code;
278	    this.httpStatus = httpStatus;
279	    this.details = details;
280	  }
281	
282	  /** `details.issues` normalizado, o `[]` si el error no trae issues utilizables. */
283	  get issues(): ValidationIssue[] {
284	    const raw = this.details?.issues;
285	    if (!Array.isArray(raw)) return [];
286	    const issues: ValidationIssue[] = [];
287	    for (const item of raw) {
288	      if (typeof item === 'string') {
289	        issues.push({ field: '', message: item });
290	        continue;
291	      }
292	      if (typeof item !== 'object' || item === null) continue;
293	      const record = item as Record<string, unknown>;
294	      const field = record.field ?? record.path ?? record.name ?? '';
295	      const message = record.message ?? record.msg ?? '';
296	      issues.push({
297	        field: typeof field === 'string' ? field : String(field),
298	        message: typeof message === 'string' ? message : '',
299	      });
300	    }
301	    return issues;
302	  }
