307	   *
308	   * Se tolera además un string de dígitos (`"30"`): no es la forma que fija la spec, pero
309	   * aceptarlo no puede alterar el caso conforme y evita perder la espera si el servidor la
310	   * serializa como monto por error. Devuelve `null` si no hay un entero no negativo
311	   * utilizable.
312	   */
313	  get retryAfterSeconds(): number | null {
314	    const raw = this.details?.retryAfterSeconds;
315	    if (typeof raw === 'number') {
316	      return Number.isInteger(raw) && raw >= 0 ? raw : null;
317	    }
318	    if (typeof raw === 'string' && /^(0|[1-9][0-9]*)$/.test(raw)) {
319	      const parsed = Number(raw);
320	      return Number.isSafeInteger(parsed) ? parsed : null;
321	    }
322	    return null;
323	  }
