348	const MESSAGE_BY_CODE: Partial<Record<ErrorCode, string>> = {
349	  UNAUTHENTICATED: SESSION_EXPIRED_MESSAGE,
350	  UNAUTHORIZED: 'No tenés permiso para esta operación',
351	  RATE_LIMITED: 'Demasiados intentos. Esperá unos segundos antes de reintentar',
352	  VALIDATION_ERROR: 'Revisá los datos ingresados',
353	  NOT_FOUND: 'El recurso solicitado no existe',
354	  METHOD_NOT_ALLOWED: CONNECTION_ERROR_MESSAGE,
355	  INVALID_CREDENTIALS: INVALID_CREDENTIALS_MESSAGE,
356	  ACCOUNT_NOT_FOUND: 'El recurso solicitado no existe',
357	  EMAIL_ALREADY_EXISTS: 'Ya existe una cuenta con ese email',
358	  CONFLICT: 'La operación no se pudo completar por un conflicto de estado',
359	  INTERNAL_ERROR: CONNECTION_ERROR_MESSAGE,
360	};
