362	/**
363	 * Mensaje a mostrar para un error cualquiera. Un `code` desconocido (o un fallo de red)
364	 * cae en el mensaje no técnico de RN-8: nunca se muestra texto proveniente del servidor.
365	 */
366	export function messageForError(error: unknown): string {
367	  if (error instanceof ApiError) {
368	    if (isErrorCode(error.code)) {
369	      return MESSAGE_BY_CODE[error.code] ?? CONNECTION_ERROR_MESSAGE;
370	    }
371	    return CONNECTION_ERROR_MESSAGE;
372	  }
373	  return CONNECTION_ERROR_MESSAGE;
374	}

