 60	const SessionContext = createContext<SessionContextValue | null>(null);
 61	
 62	export interface SessionProviderProps {
 63	  children: ReactNode;
 64	  /** Sobrescribe el prefijo de la API (tests / configuración explícita). */
 65	  baseUrl?: string;
 66	  /** Sobrescribe la implementación de `fetch` (tests). */
 67	  fetchImpl?: FetchLike;
 68	}
 69	
 70	export function SessionProvider({ children, baseUrl, fetchImpl }: SessionProviderProps) {
 71	  // Token en memoria de la SPA (RN-3): la copia persistida es sólo para sobrevivir recargas.
 72	  const tokenRef = useRef<string | null>(null);
 73	  const onUnauthenticatedRef = useRef<() => void>(() => {});
 74	  // Identifica la validación en curso: una sesión establecida o limpiada mientras el
 75	  // `GET /me` viaja invalida su resultado.
 76	  const generationRef = useRef(0);
 77	
 78	  const [status, setStatus] = useState<SessionStatus>('anonymous');
 79	  const [profile, setProfile] = useState<Profile | null>(null);
 80	  const [notice, setNotice] = useState<string | null>(null);
 81	  const [validationUnavailable, setValidationUnavailable] = useState(false);
 82	
 83	  const api = useMemo(
 84	    () =>
 85	      new ApiClient({
 86	        ...(baseUrl !== undefined ? { baseUrl } : {}),
 87	        ...(fetchImpl !== undefined ? { fetchImpl } : {}),
 88	        getToken: () => tokenRef.current,
 89	        onUnauthenticated: () => onUnauthenticatedRef.current(),
 90	      }),
 91	    [baseUrl, fetchImpl],
 92	  );
 93	
 94	  const clear = useCallback((nextNotice: string | null = null) => {
 95	    generationRef.current += 1;
 96	    tokenRef.current = null;
 97	    clearStoredSession();
 98	    setProfile(null);
 99	    setValidationUnavailable(false);
100	    setStatus('anonymous');
101	    setNotice(nextNotice);
102	  }, []);
103	
104	  // RN-7 / RNE-4: `UNAUTHENTICATED` en cualquier llamada protegida limpia la sesión local y
105	  // devuelve al login con el aviso de sesión expirada. Se registra antes del efecto de
106	  // validación de más abajo (los efectos corren en orden de declaración), así que ninguna
107	  // request puede resolver sin el handler puesto.
108	  useEffect(() => {
109	    onUnauthenticatedRef.current = () => clear(SESSION_EXPIRED_MESSAGE);
110	  }, [clear]);
111	
112	  const establish = useCallback((session: StoredSession) => {
113	    generationRef.current += 1;
114	    tokenRef.current = session.token;
115	    writeStoredSession(session);
116	    setNotice(null);
117	    setValidationUnavailable(false);
118	    setProfile(null);
119	    setStatus('authenticated');
120	  }, []);
121	
122	  const validate = useCallback(() => {
123	    const stored = readStoredSession();
124	    // Token ausente, o expirado según la expiración registrada: se limpia todo estado de
125	    // sesión local y se permanece en login (RN-11). No se muestra aviso de expiración: el
126	    // de RN-7 corresponde a una sesión que estaba activa y se cayó, no al arranque.
127	    if (!stored || isExpired(stored)) {
128	      if (stored) clearStoredSession();
129	      tokenRef.current = null;
130	      setProfile(null);
131	      setValidationUnavailable(false);
132	      setStatus('anonymous');
133	      return;
134	    }
135	
136	    const generation = generationRef.current + 1;
137	    generationRef.current = generation;
138	    tokenRef.current = stored.token;
139	    setValidationUnavailable(false);
140	    setStatus('validating');
141	
142	    // La validez la decide el servidor (RNE-2): 200 ⇒ sesión válida; 401 ⇒ se limpia.
143	    getProfile(api, { handleUnauthenticated: false }).then(
144	      (loaded) => {
145	        if (generationRef.current !== generation) return;
146	        setProfile(loaded);
147	        setStatus('authenticated');
148	      },
149	      (error: unknown) => {
150	        if (generationRef.current !== generation) return;
151	        if (error instanceof ApiError && error.code === 'UNAUTHENTICATED') {
152	          tokenRef.current = null;
153	          clearStoredSession();
154	          setProfile(null);
155	          setStatus('anonymous');
156	          return;
157	        }
158	        // Sin respuesta del servidor no hay veredicto: sólo un 401 invalida la sesión
159	        // (RNE-2). Se muestra el login con el aviso de conexión y opción de reintentar,
160	        // conservando el token persistido.
161	        setValidationUnavailable(true);
162	        setStatus('anonymous');
163	      },
164	    );
165	  }, [api]);
166	
167	  useEffect(() => {
168	    validate();
169	  }, [validate]);
170	
171	  const value = useMemo<SessionContextValue>(
172	    () => ({
173	      status,
174	      profile,
175	      notice,
176	      validationUnavailable,
177	      api,
178	      establish,
179	      clear,
180	      revalidate: validate,
181	      dismissNotice: () => setNotice(null),
182	    }),
183	    [status, profile, notice, validationUnavailable, api, establish, clear, validate],
184	  );
185	
186	  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
187	}
188	
189	export function useSession(): SessionContextValue {
190	  const value = useContext(SessionContext);
191	  if (!value) throw new Error('useSession requiere un <SessionProvider> ancestro');
192	  return value;
193	}

     1	/**
     2	 * Persistencia local de la sesión (HU-10-01 RN-3).
     3	 *
     4	 * El contrato de la épica 09 **no** emite cookies de sesión: la autenticación es por
     5	 * header `Authorization: Bearer <token>`. Por eso el cliente "mantiene el token en memoria
     6	 * de la SPA y lo persiste del lado del cliente junto con su expiración para sobrevivir
     7	 * recargas, re-validando la sesión contra el servidor al cargar la app" (RN-3 / RN-11).
     8	 *
     9	 * Se usa `localStorage` para que la sesión sobreviva la recarga y el cierre de la pestaña
    10	 * hasta su expiración. El token **nunca** se escribe en la URL, ni se renderiza, ni se
    11	 * loguea (RNE-4). Si el almacenamiento no está disponible (modo privado, cuota, etc.) la
    12	 * sesión sigue funcionando sólo en memoria: la lectura/escritura degrada sin romper.
    13	 */
    14	
    15	const STORAGE_KEY = 'cex.web.session.v1';
    16	
    17	/** Sesión tal como se persiste: token y su expiración declarada por el servidor. */
    18	export interface StoredSession {
    19	  token: string;
    20	  expiresAt: string;
    21	}
    22	
    23	function storage(): Storage | null {
    24	  try {
    25	    return globalThis.localStorage ?? null;
    26	  } catch {
    27	    return null;
    28	  }
    29	}
    30	
    31	export function readStoredSession(): StoredSession | null {
    32	  const store = storage();
    33	  if (!store) return null;
    34	  let raw: string | null;
    35	  try {
    36	    raw = store.getItem(STORAGE_KEY);
    37	  } catch {
    38	    return null;
    39	  }
    40	  if (!raw) return null;
    41	  try {
    42	    const parsed: unknown = JSON.parse(raw);
    43	    if (typeof parsed !== 'object' || parsed === null) return null;
    44	    const { token, expiresAt } = parsed as Record<string, unknown>;
    45	    if (typeof token !== 'string' || token === '') return null;
    46	    if (typeof expiresAt !== 'string' || expiresAt === '') return null;
    47	    // Un `expiresAt` que no es una fecha parseable no permite aplicar el chequeo local de
    48	    // expiración de RN-11: se descarta el registro entero.
    49	    if (Number.isNaN(Date.parse(expiresAt))) return null;
    50	    return { token, expiresAt };
    51	  } catch {
    52	    return null;
    53	  }
    54	}
    55	
    56	export function writeStoredSession(session: StoredSession): void {
    57	  const store = storage();
    58	  if (!store) return;
    59	  try {
    60	    store.setItem(STORAGE_KEY, JSON.stringify(session));
    61	  } catch {
    62	    /* almacenamiento no disponible: la sesión queda sólo en memoria */
    63	  }
    64	}
    65	
    66	export function clearStoredSession(): void {
    67	  const store = storage();
    68	  if (!store) return;
    69	  try {
    70	    store.removeItem(STORAGE_KEY);
    71	  } catch {
    72	    /* nada que limpiar si el almacenamiento no está disponible */
    73	  }
    74	}
    75	
    76	/** `true` si la expiración registrada ya pasó (chequeo **local** de RN-11). */
    77	export function isExpired(session: StoredSession, now: number = Date.now()): boolean {
    78	  const expiresAtMs = Date.parse(session.expiresAt);
    79	  if (Number.isNaN(expiresAtMs)) return true;
    80	  return expiresAtMs <= now;
    81	}
