# ---------------------------------------------------------------------------
# Configuración del backend del exchange (etapa 1)
# Copiar a `.env` y completar. El archivo `.env` se carga automáticamente al
# arrancar (no sobreescribe variables ya presentes en el entorno).
# Se busca en el directorio de trabajo del proceso (`process.cwd()`): `npm start`
# y `npm run dev` deben ejecutarse DESDE LA RAÍZ DEL REPOSITORIO.
# ---------------------------------------------------------------------------

# --- Carga del propio .env -------------------------------------------------
# Default: true. Con LOAD_DOTENV=false no se lee este archivo y la
# configuración sale sólo del entorno del proceso. Se evalúa ANTES de leer el
# `.env`, así que hay que exportarla desde el entorno (acá no tiene efecto).
# LOAD_DOTENV=true

# --- Servidor HTTP ---------------------------------------------------------
HOST=0.0.0.0
PORT=3000
LOG_LEVEL=info

# --- Persistencia ----------------------------------------------------------
# Base SQLite (se crea sola). El estado (cuentas, sesiones, seed cifrado,
# direcciones de depósito) sobrevive a reinicios (INV-8).
DATABASE_PATH=./data/exchange.db

# --- Sesiones (HU-01-02 RN-3) ----------------------------------------------
# TTL del token en segundos: entero en [60, 86400]. Fuera de rango el servicio
# NO arranca. Default del proyecto: 3600 (1 hora).
SESSION_TTL_SECONDS=3600

# --- Wallet HD (HU-06-01) --------------------------------------------------
# OBLIGATORIA: clave AES-256-GCM de 32 bytes (64 hex o base64) con la que se
# cifra el seed en reposo. Nunca se persiste junto al material cifrado.
# Generar una con: npm run genkey
# Si ya hay un seed persistido y la credencial está ausente, es incorrecta o
# está malformada, el arranque aborta con INTERNAL_ERROR (AT-06-01-11) y NO se
# regenera el seed. Si todavía no hay seed, ausente o malformada => VALIDATION_ERROR.
WALLET_ENCRYPTION_KEY=

# Opcional: mnemonic BIP-39 de 24 palabras a importar en el primer arranque.
# Si se omite, el sistema genera uno con el CSPRNG del sistema. Si ya hay un
# seed provisionado, NUNCA se regenera ni se sobreescribe.
# WALLET_MNEMONIC=
# WALLET_MNEMONIC_PASSPHRASE=

# --- Red on-chain (Sepolia, chainId 11155111) ------------------------------
# Única red soportada (INV-6). Se lee del entorno: cualquier valor distinto de
# 11155111 IMPIDE EL ARRANQUE (VALIDATION_ERROR). Default: 11155111.
# CHAIN_ID=11155111

# Endpoint JSON-RPC. Si se define, al arrancar se verifica que reporte
# chainId 11155111: si reporta otro, el proceso ABORTA con el código
# CHAIN_ID_MISMATCH. Si el endpoint no responde, sólo se emite un aviso y el
# backend arranca igual. Si no se define, tampoco se verifica nada (esta etapa
# no ejecuta operaciones on-chain).
ETH_RPC_URL=

