/**
 * Bordes de HU-10-01 que la spec no fija de forma explícita y que el cliente resuelve con
 * una decisión propia. Se testean para que la decisión quede congelada y no se pierda en un
 * refactor; cada test dice de dónde sale el criterio.
 *
 * Los criterios de aceptación de la HU (AT-10-01-*) están en `hu-10-01-login.test.tsx`.
 */
import { describe, expect, it } from 'vitest';
import { act, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import {
  CREDENTIALS,
  PROFILE,
  createFetchMock,
  errorResponse,
  isoIn,
  jsonResponse,
  readPersistedSession,
  renderApp,
  seedStoredSession,
} from './support';

const TOKEN = 'tok_borde_0123456789';

function emailInput(): HTMLInputElement {
  return screen.getByLabelText('Email') as HTMLInputElement;
}
function passwordInput(): HTMLInputElement {
  return screen.getByLabelText('Contraseña') as HTMLInputElement;
}
function submitButton(): HTMLButtonElement {
  return screen.getByTestId('submit-login') as HTMLButtonElement;
}

describe('HU-10-01 — bordes no fijados por la spec', () => {
  /**
   * RN-6 toma la espera de `details.retryAfterSeconds`, que el escenario 6 fija como entero
   * JSON. Un servidor que lo serializara como string de dígitos no es conforme, pero el
   * cliente lo tolera: perder la espera (y con ella el bloqueo del botón) sería peor que
   * aceptar la forma laxa, y aceptarla no puede alterar el caso conforme.
   */
  it('RN-6 (tolerancia): un `retryAfterSeconds` como string de dígitos también bloquea el botón', async () => {
    const fetchMock = createFetchMock({
      login: () =>
        errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.', { retryAfterSeconds: '30' }),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await user.type(emailInput(), CREDENTIALS.email);
    await user.type(passwordInput(), CREDENTIALS.password);
    await user.click(submitButton());

    await waitFor(() => {
      expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');
    });
    expect(submitButton().disabled).toBe(true);
  });

  /**
   * RN-6 sin espera utilizable: no hay lapso que contar, así que se informa el límite pero
   * no se bloquea el botón por un tiempo inventado. Caso inalcanzable con un backend
   * conforme (`{ retryAfterSeconds }` es el `details` esperado del catálogo).
   */
  it('RN-6 (degradación): sin `retryAfterSeconds` utilizable se informa el límite sin bloquear el botón', async () => {
    const fetchMock = createFetchMock({
      login: () => errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.'),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await user.type(emailInput(), CREDENTIALS.email);
    await user.type(passwordInput(), CREDENTIALS.password);
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    expect(error.textContent).toContain('Demasiados intentos');
    expect(submitButton().disabled).toBe(false);
  });

  /**
   * `UNAUTHENTICATED` sobre el endpoint **público** de login: contra un backend conforme no
   * ocurre (HU-01-02 RN-2 fija `INVALID_CREDENTIALS`), pero si ocurriera sólo puede
   * significar que la credencial no fue aceptada. Se muestra el mensaje genérico de RN-4 y
   * **no** se dispara el manejo global de RN-7: el usuario nunca tuvo sesión, así que no hay
   * nada que limpiar ni aviso de expiración que dar.
   */
  it('RN-4/RN-7: un UNAUTHENTICATED en el login no se confunde con una sesión expirada', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
    const fetchMock = createFetchMock({
      me: () => jsonResponse(401, { error: { code: 'UNAUTHENTICATED', message: 'nope' } }),
      login: () => errorResponse(401, 'UNAUTHENTICATED', 'Credencial ausente o inválida.'),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    // Arranca sin sesión: el token persistido lo rechazó el servidor (RN-11).
    await screen.findByLabelText('Email');
    await user.type(emailInput(), CREDENTIALS.email);
    await user.type(passwordInput(), CREDENTIALS.password);
    await user.click(submitButton());

    const error = await screen.findByTestId('login-error');
    expect(error.textContent).toContain('Email o contraseña incorrectos');
    expect(error.textContent).not.toContain('sesión expiró');
    expect(screen.queryByTestId('session-notice')).toBeNull();
    expect(passwordInput().value).toBe('');
  });

  /**
   * RN-11 enumera exactamente tres causas para descartar el token persistido: ausente,
   * expirado según su expiración registrada, o `UNAUTHENTICATED` del servidor. Un `GET /me`
   * que no llega a destino no es ninguna de las tres y RNE-2 pone la decisión en el
   * servidor: el token se conserva, se muestra el aviso de conexión de RN-8 y se ofrece
   * reintentar la validación.
   */
  it('RN-11 (fallo de red en la validación): conserva el token, avisa de la conexión y permite reintentar', async () => {
    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
    let attempts = 0;
    const fetchMock = createFetchMock({
      me: () => {
        attempts += 1;
        if (attempts === 1) return Promise.reject(new TypeError('Failed to fetch'));
        return jsonResponse(200, PROFILE);
      },
    });
    renderApp({ fetchImpl: fetchMock });

    // Sin veredicto del servidor no se descarta la sesión…
    await screen.findByTestId('validation-unavailable');
    expect(readPersistedSession()?.token).toBe(TOKEN);
    // …y el formulario está disponible por si el usuario prefiere autenticarse de nuevo.
    expect(submitButton()).toBeTruthy();
    expect(screen.queryByTestId('trading-account')).toBeNull();
    // Tampoco se muestra el aviso de sesión expirada: no hubo 401 (RN-7 no aplica).
    expect(screen.queryByTestId('session-notice')).toBeNull();

    // Al reintentar, el `GET /me` responde 200 y recién ahí se entra a trading.
    const user = userEvent.setup();
    await act(async () => {
      await user.click(screen.getByText('Reintentar validación'));
    });
    expect(await screen.findByTestId('trading-account')).toBeTruthy();
    expect(attempts).toBe(2);
  });
});

