import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import { login } from '../api/auth';
import {
  ApiError,
  CONNECTION_ERROR_MESSAGE,
  INVALID_CREDENTIALS_MESSAGE,
  messageForError,
  NetworkError,
} from '../api/errors';
import { useSession } from '../session/SessionProvider';
import { TRADING_ROUTE } from './paths';

/** Mensaje por campo derivado de `details.issues` (RN-5). */
interface FieldErrors {
  email?: string;
  password?: string;
}

/** Los campos del formulario a los que se puede anclar un issue. */
const FORM_FIELDS = ['email', 'password'] as const;

/** Límite defensivo: el detalle del servidor se muestra acotado y sin reformatear. */
const MAX_ISSUE_LENGTH = 200;

function truncate(text: string): string {
  const clean = text.trim();
  return clean.length > MAX_ISSUE_LENGTH ? `${clean.slice(0, MAX_ISSUE_LENGTH)}…` : clean;
}

function defaultIssueMessage(field: string): string {
  if (field === 'email') return 'Revisá el email ingresado.';
  if (field === 'password') return 'Revisá la contraseña ingresada.';
  return 'Revisá los datos ingresados.';
}

/**
 * Reparte los `issues` entre los campos del formulario y una lista general. Sólo se
 * muestra el texto del issue (nunca el valor enviado), de modo que no se expone ningún
 * dato sensible (RN-5).
 */
function splitIssues(error: ApiError): { fields: FieldErrors; general: string[] } {
  const fields: FieldErrors = {};
  const general: string[] = [];
  for (const issue of error.issues) {
    const field = issue.field.split('.').pop() ?? '';
    const message = issue.message.trim() === '' ? defaultIssueMessage(field) : truncate(issue.message);
    if ((FORM_FIELDS as readonly string[]).includes(field)) {
      const key = field as (typeof FORM_FIELDS)[number];
      if (fields[key] === undefined) fields[key] = message;
    } else {
      general.push(message);
    }
  }
  if (Object.keys(fields).length === 0 && general.length === 0) {
    general.push('Revisá los datos ingresados.');
  }
  return { fields, general };
}

function waitMessage(seconds: number): string {
  const unit = seconds === 1 ? 'segundo' : 'segundos';
  return `Demasiados intentos. Esperá ${seconds} ${unit} antes de reintentar.`;
}

export function LoginPage() {
  const session = useSession();
  const navigate = useNavigate();
  const emailId = useId();
  const passwordId = useId();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
  const [generalIssues, setGeneralIssues] = useState<string[]>([]);
  const [retryable, setRetryable] = useState(false);
  const [cooldown, setCooldown] = useState(0);

  // Guarda de envío único (RN-2): sobrevive a los re-renders y se evalúa antes de disparar
  // la llamada, así un segundo submit no puede colarse entre el `setState` y el `fetch`.
  const inFlightRef = useRef(false);

  // Cuenta regresiva del rate limit (RN-6). Al llegar a cero el botón se rehabilita solo.
  useEffect(() => {
    if (cooldown <= 0) return;
    const timer = setTimeout(() => setCooldown((current) => (current <= 1 ? 0 : current - 1)), 1000);
    return () => clearTimeout(timer);
  }, [cooldown]);

  // RN-9: con la sesión ya validada no se piden credenciales de nuevo.
  if (session.status === 'authenticated') {
    return <Navigate to={TRADING_ROUTE} replace />;
  }

  // RN-11: mientras el `GET /me` de validación está en vuelo no se muestra el formulario
  // (evita pedir credenciales que quizá no hagan falta).
  if (session.status === 'validating') {
    return (
      <main className="card" aria-busy="true">
        <h1>Exchange ETH/USDC</h1>
        <p className="muted" data-testid="session-validating">
          Validando tu sesión…
        </p>
      </main>
    );
  }

  const hasCredentials = email.trim() !== '' && password !== '';
  const blockedByRateLimit = cooldown > 0;
  const canSubmit = hasCredentials && !submitting && !blockedByRateLimit;

  function resetFeedback() {
    setFormError(null);
    setFieldErrors({});
    setGeneralIssues([]);
    setRetryable(false);
  }

  function handleFailure(error: unknown) {
    if (error instanceof ApiError) {
      switch (error.code) {
        case 'INVALID_CREDENTIALS':
        // RN-4: mismo mensaje genérico exista o no el email; la contraseña se limpia y el
        // usuario permanece en login para reintentar.
        //
        // `UNAUTHENTICATED` cae en la misma rama: contra un backend conforme el login
        // responde `INVALID_CREDENTIALS` (HU-01-02 RN-2), pero si igual devolviera el otro
        // código de la familia 401, sobre un endpoint **público** sólo puede significar que
        // la credencial no fue aceptada. Mostrar acá el aviso de "sesión expirada" sería
        // engañoso: el usuario nunca tuvo sesión. (El manejo global de RN-7 no se dispara en
        // el login: `api/auth.ts` pasa `handleUnauthenticated: false`.)
        case 'UNAUTHENTICATED':
          setPassword('');
          setFormError(INVALID_CREDENTIALS_MESSAGE);
          return;
        case 'VALIDATION_ERROR': {
          // RN-5: detalle por campo desde `details.issues`.
          const { fields, general } = splitIssues(error);
          setFieldErrors(fields);
          setGeneralIssues(general);
          return;
        }
        case 'RATE_LIMITED': {
          // RN-6: la espera sale de `details.retryAfterSeconds` (entero JSON). Si el error
          // no la trae, no hay lapso que contar: se informa el límite sin bloquear el botón.
          const seconds = error.retryAfterSeconds;
          if (seconds !== null && seconds > 0) {
            setCooldown(seconds);
            return;
          }
          setFormError(messageForError(error));
          return;
        }
        case 'INTERNAL_ERROR':
          // RN-8: mensaje no técnico, con reintento y sin filtrar detalle del error.
          setFormError(CONNECTION_ERROR_MESSAGE);
          setRetryable(true);
          return;
        default:
          // RN-10: cualquier otro `code` del catálogo se resuelve por su código, no por el
          // texto del servidor.
          setFormError(messageForError(error));
          return;
      }
    }
    // `NetworkError` o cualquier falla no clasificada: RN-8.
    setFormError(CONNECTION_ERROR_MESSAGE);
    setRetryable(true);
  }

  async function attemptLogin() {
    // RN-2: durante una solicitud en curso el intento se ignora.
    if (inFlightRef.current) return;
    // RN-1: sin ambos campos no se llama a la API.
    if (!hasCredentials) return;
    // RN-6: durante la espera del rate limit tampoco se reintenta.
    if (blockedByRateLimit) return;

    inFlightRef.current = true;
    setSubmitting(true);
    resetFeedback();
    session.dismissNotice();

    try {
      // El email se envía tal como se tipeó: el login **no** valida su formato y la
      // normalización (trim + lowercase) es del servidor (HU-01-02 RN-1/RN-11).
      const response = await login(session.api, { email, password });
      // RNE-2: no se asume éxito sin una respuesta utilizable del servidor.
      if (
        typeof response?.token !== 'string' ||
        response.token === '' ||
        typeof response.expiresAt !== 'string'
      ) {
        throw new NetworkError();
      }
      // RN-3: sesión establecida y navegación a la vista de trading (HU-10-02).
      session.establish({ token: response.token, expiresAt: response.expiresAt });
      navigate(TRADING_ROUTE, { replace: true });
    } catch (error) {
      handleFailure(error);
    } finally {
      inFlightRef.current = false;
      setSubmitting(false);
    }
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void attemptLogin();
  }

  const errorMessage = blockedByRateLimit ? waitMessage(cooldown) : formError;

  return (
    <main className="card">
      <h1>Exchange ETH/USDC</h1>
      <p className="muted">Ingresá con tu cuenta para operar el par ETH/USDC.</p>

      {session.notice !== null && (
        <p className="alert alert-warning" role="status" data-testid="session-notice">
          {session.notice}
        </p>
      )}

      {session.validationUnavailable && (
        <p className="alert alert-warning" role="status" data-testid="validation-unavailable">
          {CONNECTION_ERROR_MESSAGE}{' '}
          <button type="button" className="link" onClick={() => session.revalidate()}>
            Reintentar validación
          </button>
        </p>
      )}

      <form onSubmit={handleSubmit} noValidate>

