/** Completa el formulario con `userEvent` (eventos de teclado reales sobre los inputs). */
async function fillCredentials(
  user: ReturnType<typeof userEvent.setup>,
  credentials: { email: string; password: string } = CREDENTIALS,
) {
  await user.type(emailInput(), credentials.email);
  await user.type(passwordInput(), credentials.password);
}

/** Respuesta 200 de `POST /auth/login` (HU-09-01 / HU-01-02). */
function loginOk(token = TOKEN, expiresAt = isoIn(3600)) {
  return () => jsonResponse(200, { token, tokenType: 'Bearer', expiresAt });
}

describe('HU-10-01 — Pantalla de login', () => {
  // -----------------------------------------------------------------------------------
  // AT-10-01-01 — Login exitoso
  // -----------------------------------------------------------------------------------
  it('AT-10-01-01: login exitoso llama al endpoint, establece la sesión, navega a trading y no expone el token en el DOM ni en la URL', async () => {
    const expiresAt = isoIn(3600);
    const fetchMock = createFetchMock({
      login: loginOk(TOKEN, expiresAt),
      me: () => jsonResponse(200, PROFILE),
    });
    const user = userEvent.setup();
    renderApp({ fetchImpl: fetchMock });

    await fillCredentials(user);
    await user.click(submitButton());

    // Navegó a la vista de trading (HU-10-02) y ya no se piden credenciales.
