1	/**
2	 * Utilidades compartidas por la suite de aceptación de HU-10-01 (pantalla de login).
3	 *
4	 * Contiene: el montaje de la app con routing y sesión inyectables (`renderApp`), un mock de
5	 * `fetch` que discrimina por método + URL como lo haría la API real (`createFetchMock`),
6	 * constructores de respuestas con el envelope de `00-fundaciones/modelo-de-errores.md`
7	 * (`jsonResponse` / `errorResponse`) y acceso crudo al registro de sesión persistido.
8	 */
9	import { render } from '@testing-library/react';
10	import { MemoryRouter } from 'react-router-dom';
11	import { vi, type Mock } from 'vitest';
12	import { App } from '../src/App';
13	import { SessionProvider } from '../src/session/SessionProvider';
14	import { LOGIN_ROUTE } from '../src/routes/paths';
15	import type { FetchLike } from '../src/api/client';
16	import type { StoredSession } from '../src/session/storage';
17	
18	/**
19	 * Clave de `localStorage` del registro de sesión (contrato de `src/session/storage.ts`).
20	 * Se replica acá a propósito: los AT-10-01-07/09/10 y RN-3 afirman sobre el estado
21	 * persistido *desde afuera* del cliente, sin usar sus propios helpers de lectura.
22	 */
23	export const STORAGE_KEY = 'cex.web.session.v1';
24	
25	/** Prefijo de la API que se le pasa explícitamente al provider en los tests. */
26	export const BASE_URL = '/api/v1';
27	
28	/** Perfil que devuelve `GET /api/v1/me` (HU-09-01: `{accountId, email, status, createdAt}`). */
29	export const PROFILE = {
30	  accountId: 'acc_01HZY0000000000000000001',
31	  email: 'trader@example.com',
32	  status: 'ACTIVE',
33	  createdAt: '2026-01-05T10:00:00.000Z',
34	} as const;
35	
36	/** Credenciales que tipea el usuario en la mayoría de los escenarios. */
37	export const CREDENTIALS = {
38	  email: 'trader@example.com',
39	  password: 'Contrasena-Muy-Larga-1234',
40	} as const;
41	
42	/** Instante ISO 8601 UTC desplazado `seconds` respecto de ahora. */
43	export function isoIn(seconds: number): string {
44	  return new Date(Date.now() + seconds * 1000).toISOString();
45	}
46	
47	// --------------------------------------------------------------------------------------
48	// Mock de `fetch`
49	// --------------------------------------------------------------------------------------
50	
51	/** Una llamada al mock, ya normalizada para poder afirmar sobre ella. */
52	export interface FetchCall {
53	  url: string;
54	  method: string;
55	  headers: Record<string, string>;
56	  body: unknown;
57	}
58	
59	export type RouteHandler = (call: FetchCall) => Response | Promise<Response>;
60	
61	export interface RouteMap {
62	  /** `POST /auth/login` (HU-09-01). */
63	  login?: RouteHandler;
64	  /** `GET /me` (llamada liviana de validación de RN-11 y llamada protegida de trading). */
65	  me?: RouteHandler;
66	}
67	
68	export type FetchMock = Mock<(input: string, init?: RequestInit) => Promise<Response>>;
69	
70	function normalizeHeaders(headers: HeadersInit | undefined): Record<string, string> {
71	  const out: Record<string, string> = {};
72	  if (!headers) return out;
73	  if (headers instanceof Headers) {
74	    headers.forEach((value, key) => {
75	      out[key.toLowerCase()] = value;
76	    });
77	    return out;
78	  }
79	  if (Array.isArray(headers)) {
80	    for (const [key, value] of headers) out[String(key).toLowerCase()] = String(value);
81	    return out;
82	  }
83	  for (const [key, value] of Object.entries(headers)) out[key.toLowerCase()] = String(value);
84	  return out;
85	}
86	
87	function describeCall(input: string, init: RequestInit | undefined): FetchCall {
88	  let body: unknown = undefined;
89	  if (typeof init?.body === 'string' && init.body !== '') {
90	    try {
91	      body = JSON.parse(init.body);
92	    } catch {
93	      body = init.body;
94	    }
95	  }
96	  return {
97	    url: input,
98	    method: (init?.method ?? 'GET').toUpperCase(),
99	    headers: normalizeHeaders(init?.headers),
100	    body,
101	  };
102	}
103	
104	/**
105	 * `fetch` de mentira que enruta por método + URL. Una ruta sin handler declarado hace
106	 * fallar el test (el cliente la verá como fallo de red, pero la aserción del escenario no
107	 * se cumplirá y el mensaje queda en el listado de llamadas).
108	 */
109	export function createFetchMock(routes: RouteMap): FetchMock {
110	  return vi.fn(async (input: string, init?: RequestInit): Promise<Response> => {
111	    const call = describeCall(input, init);
112	    if (call.method === 'POST' && call.url.endsWith('/auth/login')) {
113	      if (!routes.login) throw new Error(`El test no esperaba una llamada a ${call.url}`);
114	      return routes.login(call);
115	    }
116	    if (call.method === 'GET' && call.url.endsWith('/me')) {
117	      if (!routes.me) throw new Error(`El test no esperaba una llamada a ${call.url}`);
118	      return routes.me(call);
119	    }
120	    throw new Error(`Ruta no mockeada: ${call.method} ${call.url}`);
121	  });
122	}
123	
124	/** Llamadas registradas por el mock, en orden. */
125	export function fetchCalls(mock: FetchMock): FetchCall[] {
126	  return mock.mock.calls.map(([input, init]) => describeCall(input, init));
127	}
128	
129	/** Llamadas cuyo path termina en `suffix`. */
130	export function callsTo(mock: FetchMock, suffix: string): FetchCall[] {
131	  return fetchCalls(mock).filter((call) => call.url.endsWith(suffix));
132	}
133	
134	/** Respuesta JSON realista (con `content-type`), como la de un servidor HTTP. */
135	export function jsonResponse(status: number, body: unknown): Response {
136	  return new Response(JSON.stringify(body), {
137	    status,
138	    headers: { 'content-type': 'application/json' },
139	  });
140	}
141	
142	/** Respuesta de error con el envelope uniforme `{ error: { code, message, details } }`. */
143	export function errorResponse(
144	  status: number,
145	  code: string,
146	  message: string,
147	  details?: Record<string, unknown>,
148	): Response {
149	  return jsonResponse(status, {
150	    error: { code, message, ...(details !== undefined ? { details } : {}) },
151	  });
152	}
153	
154	/** Promesa controlada por el test, para mantener una solicitud "en vuelo". */
155	export interface Deferred<T> {
156	  promise: Promise<T>;
157	  resolve: (value: T) => void;
158	  reject: (reason: unknown) => void;
159	}
160	
161	export function deferred<T>(): Deferred<T> {
162	  let resolve!: (value: T) => void;
163	  let reject!: (reason: unknown) => void;
164	  const promise = new Promise<T>((res, rej) => {
165	    resolve = res;
166	    reject = rej;
167	  });
168	  return { promise, resolve, reject };
169	}
170	
171	// --------------------------------------------------------------------------------------
172	// Sesión persistida
173	// --------------------------------------------------------------------------------------
174	
175	/** Deja un registro de sesión en `localStorage`, como una recarga de la SPA. */
176	export function seedStoredSession(session: StoredSession): void {
177	  globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
178	}
179	
180	/** Registro de sesión persistido crudo, o `null` si no hay ninguno. */
181	export function readPersistedSession(): { token?: unknown; expiresAt?: unknown } | null {
182	  const raw = globalThis.localStorage.getItem(STORAGE_KEY);
183	  if (raw === null) return null;
184	  return JSON.parse(raw) as { token?: unknown; expiresAt?: unknown };
185	}
186	
187	/** Contenido completo de `localStorage`, para afirmar que no quedó rastro del token. */
188	export function dumpLocalStorage(): string {
189	  const store = globalThis.localStorage;
190	  let out = '';
191	  for (let i = 0; i < store.length; i += 1) {
192	    const key = store.key(i);
193	    if (key === null) continue;
194	    out += `${key}=${store.getItem(key) ?? ''}\n`;
195	  }
196	  return out;
197	}
198	
199	// --------------------------------------------------------------------------------------
200	// Montaje de la app
201	// --------------------------------------------------------------------------------------
202	
203	export interface RenderAppOptions {
204	  fetchImpl: FetchLike;
205	  /** Ruta inicial del router en memoria. Por defecto, la pantalla de login. */
206	  initialEntries?: string[];
207	  baseUrl?: string;
208	}
209	
210	/**
211	 * Monta la app completa (rutas `/login` y `/trading`) con el mismo anidamiento que
212	 * `src/main.tsx` — `SessionProvider` por fuera del router —, cambiando `BrowserRouter` por
213	 * `MemoryRouter` e inyectando el `fetch` del test.
214	 */
215	export function renderApp(options: RenderAppOptions) {
216	  return render(
217	    <SessionProvider baseUrl={options.baseUrl ?? BASE_URL} fetchImpl={options.fetchImpl}>
218	      <MemoryRouter initialEntries={options.initialEntries ?? [LOGIN_ROUTE]}>
219	        <App />
220	      </MemoryRouter>
221	    </SessionProvider>,
222	  );
223	}
