271	  describe('AT-10-01-06 — rate limit', () => {
272	    afterEach(() => {
273	      vi.useRealTimers();
274	    });
275	
276	    /**
277	     * Avanza `seconds` segundos de temporizadores falsos, un tick por vez y cada uno dentro
278	     * de su propio `act`. Hace falta ir de a uno porque el componente **encadena** un
279	     * `setTimeout` de 1 s por tick: el temporizador del segundo siguiente sólo se programa
280	     * cuando React vuelve a renderizar y corre el efecto, y eso ocurre al salir de `act`.
281	     */
282	    async function tick(seconds: number) {
283	      for (let i = 0; i < seconds; i += 1) {
284	        await act(async () => {
285	          await vi.advanceTimersByTimeAsync(1000);
286	        });
287	      }
288	    }
289	
290	    it('AT-10-01-06: RATE_LIMITED (429) deshabilita el botón, informa los 30 segundos de espera y lo rehabilita al transcurrir', async () => {
291	      vi.useFakeTimers();
292	      // `retryAfterSeconds` viaja como **entero JSON** (no string), según el escenario 6.
293	      const fetchMock = createFetchMock({
294	        login: () =>
295	          errorResponse(429, 'RATE_LIMITED', 'Se superó el límite de solicitudes.', {
296	            retryAfterSeconds: 30,
297	          }),
298	      });
299	      renderApp({ fetchImpl: fetchMock });
300	
301	      // Con temporizadores falsos se usa `fireEvent` en lugar de `user-event`.
302	      fireEvent.change(emailInput(), { target: { value: CREDENTIALS.email } });
303	      fireEvent.change(passwordInput(), { target: { value: CREDENTIALS.password } });
304	      expect(submitButton().disabled).toBe(false);
305	
306	      await act(async () => {
307	        fireEvent.submit(loginForm());
308	      });
309	
310	      // Botón bloqueado y aviso con el lapso exacto informado por el servidor.
311	      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(1);
312	      expect(submitButton().disabled).toBe(true);
313	      expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');
314	
315	      // A mitad de la espera todavía está bloqueado (la cuenta regresiva avanza).
316	      await tick(15);
317	      expect(submitButton().disabled).toBe(true);
318	      expect(screen.getByTestId('login-error').textContent).toContain('15 segundos');
319	
320	      // Transcurrido el tiempo indicado, el botón se rehabilita (RN-6).
321	      await tick(15);
322	      expect(submitButton().disabled).toBe(false);
323	      expect(screen.queryByTestId('login-error')).toBeNull();
324	
325	      // Y un reenvío ya sí llega a la API.
326	      await act(async () => {
327	        fireEvent.submit(loginForm());
328	      });
329	      expect(callsTo(fetchMock, '/auth/login')).toHaveLength(2);
330	    });
331	  });
