  8	 *  RN-2  envío único: durante una solicitud en curso el segundo intento se ignora.
  9	 *  RN-3  ante 200, se establece la sesión (token en memoria + persistido con su
 10	 *        expiración) y se navega a la vista de trading. El token no se renderiza ni viaja
 11	 *        por la URL.
 12	 *  RN-4  `INVALID_CREDENTIALS` ⇒ mensaje genérico que no revela si el email existe; se
 13	 *        limpia `password` y se permanece en la pantalla.
 14	 *  RN-5  `VALIDATION_ERROR` ⇒ detalle por campo derivado de `details.issues`.
 15	 *  RN-6  `RATE_LIMITED` ⇒ botón deshabilitado durante `details.retryAfterSeconds`, con el
 16	 *        tiempo restante a la vista; al vencer, se rehabilita.
 17	 *  RN-7  el aviso de sesión expirada lo publica el `SessionProvider` al recibir
 18	 *        `UNAUTHENTICATED` en una llamada protegida; acá sólo se muestra.
 19	 *  RN-8  fallo de red o `INTERNAL_ERROR` ⇒ mensaje no técnico y opción de reintentar, sin
 20	 *        perder el email ingresado y sin filtrar detalle del error.
 21	 *  RN-9  con sesión válida ya presente, se redirige a trading sin pedir credenciales.
 22	 *  RN-10 todo error se discrimina por `code`, nunca por `message`.
 23	 *  RN-11 la validación de la sesión persistida ocurre en el `SessionProvider`.
 24	 */
 25	import { useEffect, useId, useRef, useState, type FormEvent } from 'react';
 26	import { Navigate, useNavigate } from 'react-router-dom';
 27	import { login } from '../api/auth';
 28	import {
 29	  ApiError,
 30	  CONNECTION_ERROR_MESSAGE,
 31	  INVALID_CREDENTIALS_MESSAGE,
 32	  messageForError,
 33	  NetworkError,
 34	} from '../api/errors';
 35	import { useSession } from '../session/SessionProvider';
 36	import { TRADING_ROUTE } from './paths';
 37	
 38	/** Mensaje por campo derivado de `details.issues` (RN-5). */
 39	interface FieldErrors {
 40	  email?: string;
 41	  password?: string;
 42	}
 43	
 44	/** Los campos del formulario a los que se puede anclar un issue. */
 45	const FORM_FIELDS = ['email', 'password'] as const;
 46	
 47	/** Límite defensivo: el detalle del servidor se muestra acotado y sin reformatear. */
 48	const MAX_ISSUE_LENGTH = 200;
 49	
 50	function truncate(text: string): string {
 51	  const clean = text.trim();
 52	  return clean.length > MAX_ISSUE_LENGTH ? `${clean.slice(0, MAX_ISSUE_LENGTH)}…` : clean;
 53	}
 54	
 55	function defaultIssueMessage(field: string): string {
 56	  if (field === 'email') return 'Revisá el email ingresado.';
 57	  if (field === 'password') return 'Revisá la contraseña ingresada.';
 58	  return 'Revisá los datos ingresados.';
 59	}
 60	
 61	/**
 62	 * Reparte los `issues` entre los campos del formulario y una lista general. Sólo se
 63	 * muestra el texto del issue (nunca el valor enviado), de modo que no se expone ningún
 64	 * dato sensible (RN-5).
 65	 */
 66	function splitIssues(error: ApiError): { fields: FieldErrors; general: string[] } {
 67	  const fields: FieldErrors = {};
 68	  const general: string[] = [];
 69	  for (const issue of error.issues) {
 70	    const field = issue.field.split('.').pop() ?? '';
 71	    const message = issue.message.trim() === '' ? defaultIssueMessage(field) : truncate(issue.message);
 72	    if ((FORM_FIELDS as readonly string[]).includes(field)) {
 73	      const key = field as (typeof FORM_FIELDS)[number];
 74	      if (fields[key] === undefined) fields[key] = message;
 75	    } else {
 76	      general.push(message);
 77	    }
 78	  }
 79	  if (Object.keys(fields).length === 0 && general.length === 0) {
 80	    general.push('Revisá los datos ingresados.');
 81	  }
 82	  return { fields, general };
 83	}
 84	
 85	function waitMessage(seconds: number): string {
 86	  const unit = seconds === 1 ? 'segundo' : 'segundos';
 87	  return `Demasiados intentos. Esperá ${seconds} ${unit} antes de reintentar.`;
 88	}
 89	
 90	export function LoginPage() {
 91	  const session = useSession();
 92	  const navigate = useNavigate();
 93	  const emailId = useId();
 94	  const passwordId = useId();
 95	
 96	  const [email, setEmail] = useState('');
 97	  const [password, setPassword] = useState('');
 98	  const [submitting, setSubmitting] = useState(false);
 99	  const [formError, setFormError] = useState<string | null>(null);
100	  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});
101	  const [generalIssues, setGeneralIssues] = useState<string[]>([]);
102	  const [retryable, setRetryable] = useState(false);
103	  const [cooldown, setCooldown] = useState(0);
104	
105	  // Guarda de envío único (RN-2): sobrevive a los re-renders y se evalúa antes de disparar
106	  // la llamada, así un segundo submit no puede colarse entre el `setState` y el `fetch`.
107	  const inFlightRef = useRef(false);
108	
109	  // Cuenta regresiva del rate limit (RN-6). Al llegar a cero el botón se rehabilita solo.
110	  useEffect(() => {
111	    if (cooldown <= 0) return;
112	    const timer = setTimeout(() => setCooldown((current) => (current <= 1 ? 0 : current - 1)), 1000);
113	    return () => clearTimeout(timer);
114	  }, [cooldown]);
115	
116	  // RN-9: con la sesión ya validada no se piden credenciales de nuevo.
117	  if (session.status === 'authenticated') {
118	    return <Navigate to={TRADING_ROUTE} replace />;
119	  }
120	
121	  // RN-11: mientras el `GET /me` de validación está en vuelo no se muestra el formulario
122	  // (evita pedir credenciales que quizá no hagan falta).
123	  if (session.status === 'validating') {
124	    return (
125	      <main className="card" aria-busy="true">
126	        <h1>Exchange ETH/USDC</h1>
127	        <p className="muted" data-testid="session-validating">
128	          Validando tu sesión…
129	        </p>
130	      </main>
131	    );
132	  }
133	
134	  const hasCredentials = email.trim() !== '' && password !== '';
135	  const blockedByRateLimit = cooldown > 0;
136	  const canSubmit = hasCredentials && !submitting && !blockedByRateLimit;
137	
138	  function resetFeedback() {
139	    setFormError(null);
140	    setFieldErrors({});
141	    setGeneralIssues([]);
142	    setRetryable(false);
143	  }
144	
145	  function handleFailure(error: unknown) {
146	    if (error instanceof ApiError) {
147	      switch (error.code) {
148	        case 'INVALID_CREDENTIALS':
149	        // RN-4: mismo mensaje genérico exista o no el email; la contraseña se limpia y el
150	        // usuario permanece en login para reintentar.
151	        //
152	        // `UNAUTHENTICATED` cae en la misma rama: contra un backend conforme el login
153	        // responde `INVALID_CREDENTIALS` (HU-01-02 RN-2), pero si igual devolviera el otro
154	        // código de la familia 401, sobre un endpoint **público** sólo puede significar que
155	        // la credencial no fue aceptada. Mostrar acá el aviso de "sesión expirada" sería
156	        // engañoso: el usuario nunca tuvo sesión. (El manejo global de RN-7 no se dispara en
157	        // el login: `api/auth.ts` pasa `handleUnauthenticated: false`.)
158	        case 'UNAUTHENTICATED':
159	          setPassword('');
160	          setFormError(INVALID_CREDENTIALS_MESSAGE);
161	          return;
162	        case 'VALIDATION_ERROR': {
163	          // RN-5: detalle por campo desde `details.issues`.
164	          const { fields, general } = splitIssues(error);
165	          setFieldErrors(fields);
166	          setGeneralIssues(general);
167	          return;
168	        }
169	        case 'RATE_LIMITED': {
170	          // RN-6: la espera sale de `details.retryAfterSeconds` (entero JSON). Si el error
171	          // no la trae, no hay lapso que contar: se informa el límite sin bloquear el botón.
172	          const seconds = error.retryAfterSeconds;
173	          if (seconds !== null && seconds > 0) {
174	            setCooldown(seconds);
175	            return;
176	          }
177	          setFormError(messageForError(error));
178	          return;
179	        }
180	        case 'INTERNAL_ERROR':
181	          // RN-8: mensaje no técnico, con reintento y sin filtrar detalle del error.
182	          setFormError(CONNECTION_ERROR_MESSAGE);
183	          setRetryable(true);
184	          return;
185	        default:
186	          // RN-10: cualquier otro `code` del catálogo se resuelve por su código, no por el
187	          // texto del servidor.
188	          setFormError(messageForError(error));
189	          return;
190	      }
191	    }
192	    // `NetworkError` o cualquier falla no clasificada: RN-8.
193	    setFormError(CONNECTION_ERROR_MESSAGE);
194	    setRetryable(true);
195	  }
196	
197	  async function attemptLogin() {
198	    // RN-2: durante una solicitud en curso el intento se ignora.
199	    if (inFlightRef.current) return;
200	    // RN-1: sin ambos campos no se llama a la API.
201	    if (!hasCredentials) return;
202	    // RN-6: durante la espera del rate limit tampoco se reintenta.
203	    if (blockedByRateLimit) return;
204	
205	    inFlightRef.current = true;
206	    setSubmitting(true);
207	    resetFeedback();
208	    session.dismissNotice();
209	
210	    try {
211	      // El email se envía tal como se tipeó: el login **no** valida su formato y la
212	      // normalización (trim + lowercase) es del servidor (HU-01-02 RN-1/RN-11).
213	      const response = await login(session.api, { email, password });
214	      // RNE-2: no se asume éxito sin una respuesta utilizable del servidor.
215	      if (
216	        typeof response?.token !== 'string' ||
217	        response.token === '' ||
218	        typeof response.expiresAt !== 'string'
219	      ) {
220	        throw new NetworkError();
221	      }
222	      // RN-3: sesión establecida y navegación a la vista de trading (HU-10-02).
223	      session.establish({ token: response.token, expiresAt: response.expiresAt });
224	      navigate(TRADING_ROUTE, { replace: true });
225	    } catch (error) {
226	      handleFailure(error);
227	    } finally {
228	      inFlightRef.current = false;
229	      setSubmitting(false);
230	    }
231	  }
232	
233	  function handleSubmit(event: FormEvent<HTMLFormElement>) {
234	    event.preventDefault();
235	    void attemptLogin();
236	  }
237	
238	  const errorMessage = blockedByRateLimit ? waitMessage(cooldown) : formError;
239	
240	  return (
241	    <main className="card">
242	      <h1>Exchange ETH/USDC</h1>
243	      <p className="muted">Ingresá con tu cuenta para operar el par ETH/USDC.</p>
244	
245	      {session.notice !== null && (
246	        <p className="alert alert-warning" role="status" data-testid="session-notice">
247	          {session.notice}
248	        </p>
249	      )}
250	
251	      {session.validationUnavailable && (
252	        <p className="alert alert-warning" role="status" data-testid="validation-unavailable">
253	          {CONNECTION_ERROR_MESSAGE}{' '}
254	          <button type="button" className="link" onClick={() => session.revalidate()}>
255	            Reintentar validación
256	          </button>
257	        </p>
258	      )}
259	
260	      <form onSubmit={handleSubmit} noValidate>
261	        <div className="field">
262	          <label htmlFor={emailId}>Email</label>
263	          <input
264	            id={emailId}
265	            name="email"
266	            type="email"
267	            autoComplete="username"
268	            value={email}
269	            onChange={(event) => setEmail(event.target.value)}
270	            aria-invalid={fieldErrors.email !== undefined}
271	            aria-describedby={fieldErrors.email !== undefined ? `${emailId}-error` : undefined}
272	            disabled={submitting}
273	          />
274	          {fieldErrors.email !== undefined && (
275	            <p className="field-error" id={`${emailId}-error`} data-testid="email-error">
276	              {fieldErrors.email}
277	            </p>
278	          )}
279	        </div>
280	
281	        <div className="field">
282	          <label htmlFor={passwordId}>Contraseña</label>
283	          <input
284	            id={passwordId}
285	            name="password"
286	            type="password"
287	            autoComplete="current-password"
288	            value={password}
289	            onChange={(event) => setPassword(event.target.value)}
290	            aria-invalid={fieldErrors.password !== undefined}
291	            aria-describedby={fieldErrors.password !== undefined ? `${passwordId}-error` : undefined}
292	            disabled={submitting}
293	          />
294	          {fieldErrors.password !== undefined && (
295	            <p className="field-error" id={`${passwordId}-error`} data-testid="password-error">
296	              {fieldErrors.password}
297	            </p>
298	          )}
299	        </div>
300	
301	        {generalIssues.length > 0 && (
302	          <ul className="alert alert-error" role="alert" data-testid="general-issues">
303	            {generalIssues.map((issue) => (
304	              <li key={issue}>{issue}</li>
305	            ))}
306	          </ul>
307	        )}
308	
309	        {errorMessage !== null && (
310	          <p className="alert alert-error" role="alert" data-testid="login-error">
311	            {errorMessage}
312	            {retryable && (
313	              <>
314	                {' '}
315	                <button
316	                  type="button"
317	                  className="link"
318	                  onClick={() => void attemptLogin()}
319	                  data-testid="retry-login"
320	                >
321	                  Reintentar
322	                </button>
323	              </>
324	            )}
325	          </p>
326	        )}
327	
328	        <button type="submit" disabled={!canSubmit} data-testid="submit-login">
329	          {submitting ? 'Ingresando…' : 'Ingresar'}
330	        </button>
331	      </form>
332	    </main>
333	  );
334	}

  1	/**
  2	 * Bordes de HU-10-01 que la spec no fija de forma explícita y que el cliente resuelve con
  3	 * una decisión propia. Se testean para que la decisión quede congelada y no se pierda en un
  4	 * refactor; cada test dice de dónde sale el criterio.
  5	 *
  6	 * Los criterios de aceptación de la HU (AT-10-01-*) están en `hu-10-01-login.test.tsx`.
  7	 */
  8	import { describe, expect, it } from 'vitest';
  9	import { act, screen, waitFor } from '@testing-library/react';
 10	import userEvent from '@testing-library/user-event';
 11	import {
 12	  CREDENTIALS,
 13	  PROFILE,
 14	  createFetchMock,
 15	  errorResponse,
 16	  isoIn,
 17	  jsonResponse,
 18	  readPersistedSession,
 19	  renderApp,
 20	  seedStoredSession,
 21	} from './support';
 22	
 23	const TOKEN = 'tok_borde_0123456789';
 24	
 25	function emailInput(): HTMLInputElement {
 26	  return screen.getByLabelText('Email') as HTMLInputElement;
 27	}
 28	function passwordInput(): HTMLInputElement {
 29	  return screen.getByLabelText('Contraseña') as HTMLInputElement;
 30	}
 31	function submitButton(): HTMLButtonElement {
 32	  return screen.getByTestId('submit-login') as HTMLButtonElement;
 33	}
 34	
 35	describe('HU-10-01 — bordes no fijados por la spec', () => {
 36	  /**
 37	   * RN-6 toma la espera de `details.retryAfterSeconds`, que el escenario 6 fija como entero
 38	   * JSON. Un servidor que lo serializara como string de dígitos no es conforme, pero el
 39	   * cliente lo tolera: perder la espera (y con ella el bloqueo del botón) sería peor que
 40	   * aceptar la forma laxa, y aceptarla no puede alterar el caso conforme.
 41	   */
 42	  it('RN-6 (tolerancia): un `retryAfterSeconds` como string de dígitos también bloquea el botón', async () => {
 43	    const fetchMock = createFetchMock({
 44	      login: () =>
 45	        errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.', { retryAfterSeconds: '30' }),
 46	    });
 47	    const user = userEvent.setup();
 48	    renderApp({ fetchImpl: fetchMock });
 49	
 50	    await user.type(emailInput(), CREDENTIALS.email);
 51	    await user.type(passwordInput(), CREDENTIALS.password);
 52	    await user.click(submitButton());
 53	
 54	    await waitFor(() => {
 55	      expect(screen.getByTestId('login-error').textContent).toContain('30 segundos');
 56	    });
 57	    expect(submitButton().disabled).toBe(true);
 58	  });
 59	
 60	  /**
 61	   * RN-6 sin espera utilizable: no hay lapso que contar, así que se informa el límite pero
 62	   * no se bloquea el botón por un tiempo inventado. Caso inalcanzable con un backend
 63	   * conforme (`{ retryAfterSeconds }` es el `details` esperado del catálogo).
 64	   */
 65	  it('RN-6 (degradación): sin `retryAfterSeconds` utilizable se informa el límite sin bloquear el botón', async () => {
 66	    const fetchMock = createFetchMock({
 67	      login: () => errorResponse(429, 'RATE_LIMITED', 'Demasiados intentos.'),
 68	    });
 69	    const user = userEvent.setup();
 70	    renderApp({ fetchImpl: fetchMock });
 71	
 72	    await user.type(emailInput(), CREDENTIALS.email);
 73	    await user.type(passwordInput(), CREDENTIALS.password);
 74	    await user.click(submitButton());
 75	
 76	    const error = await screen.findByTestId('login-error');
 77	    expect(error.textContent).toContain('Demasiados intentos');
 78	    expect(submitButton().disabled).toBe(false);
 79	  });
 80	
 81	  /**
 82	   * `UNAUTHENTICATED` sobre el endpoint **público** de login: contra un backend conforme no
 83	   * ocurre (HU-01-02 RN-2 fija `INVALID_CREDENTIALS`), pero si ocurriera sólo puede
 84	   * significar que la credencial no fue aceptada. Se muestra el mensaje genérico de RN-4 y
 85	   * **no** se dispara el manejo global de RN-7: el usuario nunca tuvo sesión, así que no hay
 86	   * nada que limpiar ni aviso de expiración que dar.
 87	   */
 88	  it('RN-4/RN-7: un UNAUTHENTICATED en el login no se confunde con una sesión expirada', async () => {
 89	    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
 90	    const fetchMock = createFetchMock({
 91	      me: () => jsonResponse(401, { error: { code: 'UNAUTHENTICATED', message: 'nope' } }),
 92	      login: () => errorResponse(401, 'UNAUTHENTICATED', 'Credencial ausente o inválida.'),
 93	    });
 94	    const user = userEvent.setup();
 95	    renderApp({ fetchImpl: fetchMock });
 96	
 97	    // Arranca sin sesión: el token persistido lo rechazó el servidor (RN-11).
 98	    await screen.findByLabelText('Email');
 99	    await user.type(emailInput(), CREDENTIALS.email);
100	    await user.type(passwordInput(), CREDENTIALS.password);
101	    await user.click(submitButton());
102	
103	    const error = await screen.findByTestId('login-error');
104	    expect(error.textContent).toContain('Email o contraseña incorrectos');
105	    expect(error.textContent).not.toContain('sesión expiró');
106	    expect(screen.queryByTestId('session-notice')).toBeNull();
107	    expect(passwordInput().value).toBe('');
108	  });
109	
110	  /**
111	   * RN-11 enumera exactamente tres causas para descartar el token persistido: ausente,
112	   * expirado según su expiración registrada, o `UNAUTHENTICATED` del servidor. Un `GET /me`
113	   * que no llega a destino no es ninguna de las tres y RNE-2 pone la decisión en el
114	   * servidor: el token se conserva, se muestra el aviso de conexión de RN-8 y se ofrece
115	   * reintentar la validación.
116	   */
117	  it('RN-11 (fallo de red en la validación): conserva el token, avisa de la conexión y permite reintentar', async () => {
118	    seedStoredSession({ token: TOKEN, expiresAt: isoIn(3600) });
119	    let attempts = 0;
120	    const fetchMock = createFetchMock({
121	      me: () => {
122	        attempts += 1;
123	        if (attempts === 1) return Promise.reject(new TypeError('Failed to fetch'));
124	        return jsonResponse(200, PROFILE);
125	      },
126	    });
127	    renderApp({ fetchImpl: fetchMock });
128	
129	    // Sin veredicto del servidor no se descarta la sesión…
130	    await screen.findByTestId('validation-unavailable');
131	    expect(readPersistedSession()?.token).toBe(TOKEN);
132	    // …y el formulario está disponible por si el usuario prefiere autenticarse de nuevo.
133	    expect(submitButton()).toBeTruthy();
134	    expect(screen.queryByTestId('trading-account')).toBeNull();
135	    // Tampoco se muestra el aviso de sesión expirada: no hubo 401 (RN-7 no aplica).
136	    expect(screen.queryByTestId('session-notice')).toBeNull();
137	
138	    // Al reintentar, el `GET /me` responde 200 y recién ahí se entra a trading.
139	    const user = userEvent.setup();
140	    await act(async () => {
141	      await user.click(screen.getByText('Reintentar validación'));
142	    });
143	    expect(await screen.findByTestId('trading-account')).toBeTruthy();
144	    expect(attempts).toBe(2);
145	  });
146	});

