     1	/**
     2	 * Rutas del cliente web. El alcance de esta etapa es la pantalla de login (HU-10-01);
     3	 * `/trading` existe sólo como destino de la navegación posterior al login (RN-3) y **no**
     4	 * implementa HU-10-02.
     5	 */
     6	import { Navigate, Route, Routes } from 'react-router-dom';
     7	import { LoginPage } from './routes/LoginPage';
     8	import { RequireSession } from './routes/RequireSession';
     9	import { TradingPage } from './routes/TradingPage';
    10	import { LOGIN_ROUTE, TRADING_ROUTE } from './routes/paths';
    11	
    12	export function App() {
    13	  return (
    14	    <Routes>
    15	      <Route path={LOGIN_ROUTE} element={<LoginPage />} />
    16	      <Route
    17	        path={TRADING_ROUTE}
    18	        element={
    19	          <RequireSession>
    20	            <TradingPage />
    21	          </RequireSession>
    22	        }
    23	      />
    24	      <Route path="*" element={<Navigate to={LOGIN_ROUTE} replace />} />
    25	    </Routes>
    26	  );
    27	}
    28	/** Rutas del cliente. El alcance de esta etapa es login + destino de la navegación. */
    29	export const LOGIN_ROUTE = '/login';
    30	export const TRADING_ROUTE = '/trading';
    31	/**
    32	 * Catálogo de errores de la API y derivación de los mensajes que ve el usuario.
