    38	
    39	export type SessionStatus = 'validating' | 'anonymous' | 'authenticated';
    40	
    41	export interface SessionContextValue {
    42	  status: SessionStatus;
    43	  /** Perfil de la cuenta autenticada, cuando la validación de RN-11 lo devolvió. */
    44	  profile: Profile | null;
    45	  /** Aviso a mostrar en la pantalla de login (p. ej. sesión expirada, RN-7). */
    46	  notice: string | null;
    47	  /** La validación de RN-11 no pudo completarse por falta de conexión (no hubo 401). */
    48	  validationUnavailable: boolean;
