import { loadEnv } from 'vite';
import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';

/**
 * `VITE_API_BASE_URL` (leída por el cliente) define contra qué prefijo se hacen las
 * llamadas HTTP. Su valor por defecto es `/api/v1`, o sea el **mismo origen** del cliente:
 * en desarrollo el proxy de abajo reenvía esas rutas al backend, de modo que el navegador
 * nunca hace una request cross-origin y no hace falta CORS.
 *
 * `BACKEND_URL` (destino del proxy) y `PORT` (puerto del servidor de desarrollo) son
 * variables del proceso de Vite, no del cliente: no se inyectan en el bundle. Vite sólo
 * vuelca en `import.meta.env` las variables con prefijo `VITE_`, y nunca las escribe en
 * `process.env`, así que para que `web/.env` sirva de archivo de configuración —como lo
 * documenta el README— hay que leerlo explícitamente con `loadEnv(mode, envDir, '')`
 * (prefijo vacío ⇒ todas las variables, no sólo las `VITE_*`).
 *
 * Precedencia: lo exportado en el entorno del proceso (`BACKEND_URL=… npm run dev`) gana
 * sobre lo escrito en `.env`, que es el orden que aplica `loadEnv`.
 */
export default defineConfig(({ mode }) => {
  // `import.meta.dirname` en vez de `process.cwd()`: el `.env` que configura al cliente es
  // el de `web/`, esté donde esté parado el shell que invoca a Vite.
  const env = loadEnv(mode, import.meta.dirname, '');
  const backendUrl = env.BACKEND_URL ?? 'http://localhost:3000';
  const proxy = {
    '/api': { target: backendUrl, changeOrigin: true },
    '/health': { target: backendUrl, changeOrigin: true },
  };

  return {
    plugins: [react()],
    server: {
      port: Number(env.PORT ?? 5173),
      proxy,
    },
    preview: {
      port: Number(env.PORT ?? 4173),
      proxy,
    },
    test: {
      environment: 'jsdom',
      globals: false,
      include: ['tests/**/*.test.{ts,tsx}'],
      setupFiles: ['tests/setup.ts'],
      restoreMocks: true,
    },
  };
});

