/**
 * `fetch` de mentira que enruta por método + URL. Una ruta sin handler declarado hace
 * fallar el test (el cliente la verá como fallo de red, pero la aserción del escenario no
 * se cumplirá y el mensaje queda en el listado de llamadas).
 */
export function createFetchMock(routes: RouteMap): FetchMock {
  return vi.fn(async (input: string, init?: RequestInit): Promise<Response> => {
    const call = describeCall(input, init);
    if (call.method === 'POST' && call.url.endsWith('/auth/login')) {
      if (!routes.login) throw new Error(`El test no esperaba una llamada a ${call.url}`);
      return routes.login(call);
    }
    if (call.method === 'GET' && call.url.endsWith('/me')) {
      if (!routes.me) throw new Error(`El test no esperaba una llamada a ${call.url}`);
      return routes.me(call);
    }
    throw new Error(`Ruta no mockeada: ${call.method} ${call.url}`);
  });
}

input.new_string:
/**
 * Llamadas que el mock recibió sin tener un handler declarado para ellas.
 *
 * Hace falta registrarlas afuera del mock porque lanzar dentro de la promesa no alcanza
 * para hacer fallar el test: el `ApiClient` trata cualquier excepción del `fetch` como un
 * `NetworkError` (RN-8), así que la llamada espuria quedaría silenciada. El `afterEach`
 * global de `tests/setup.ts` vacía esta lista y falla si quedó algo.
 */
const unexpectedFetchCalls: string[] = [];

/** Registra la llamada inesperada y devuelve el error con el que se rechaza el `fetch`. */
function unexpected(reason: string, call: FetchCall): Error {
  const description = `${reason}: ${call.method} ${call.url}`;
  unexpectedFetchCalls.push(description);
  return new Error(description);
}

/** Vacía el registro de llamadas inesperadas y devuelve lo que había. */
export function takeUnexpectedFetchCalls(): string[] {
  return unexpectedFetchCalls.splice(0, unexpectedFetchCalls.length);
}

/**
 * `fetch` de mentira que enruta por método + URL. Una ruta sin handler declarado queda
 * anotada en `unexpectedFetchCalls` (además de rechazar la promesa), y el `afterEach`
 * global hace fallar al test que la haya provocado.
 */
export function createFetchMock(routes: RouteMap): FetchMock {
  return vi.fn(async (input: string, init?: RequestInit): Promise<Response> => {
    const call = describeCall(input, init);
    if (call.method === 'POST' && call.url.endsWith('/auth/login')) {
      if (!routes.login) throw unexpected('El test no esperaba una llamada a esta ruta', call);
      return routes.login(call);
    }
    if (call.method === 'GET' && call.url.endsWith('/me')) {
      if (!routes.me) throw unexpected('El test no esperaba una llamada a esta ruta', call);
      return routes.me(call);
    }
    throw unexpected('Ruta no mockeada', call);
  });
}

