export interface RenderAppOptions {
  fetchImpl: FetchLike;
  /** Ruta inicial del router en memoria. Por defecto, la pantalla de login. */
  initialEntries?: string[];
  baseUrl?: string;
}

/** Ubicación del router en memoria: lo que el navegador mostraría en la barra de direcciones. */
export interface RouterLocation {
  pathname: string;
  search: string;
  hash: string;
  /** `pathname + search + hash`, o sea la URL completa relativa al origen. */
  href: string;
}

export interface RenderedApp extends RenderResult {
  /**
   * Ubicación actual del router. Es la única forma de afirmar sobre "la URL" en esta suite:
   * `MemoryRouter` no escribe en `window.location` (en jsdom `search`/`hash` son siempre
   * `''`, con lo que afirmar sobre ellos no verificaría nada).
   */
  location(): RouterLocation;
}

/**
 * Sonda de ubicación: no renderiza nada, sólo publica el `useLocation()` del router para
 * que el test pueda leerlo sin alterar el DOM de la app.
 */
function LocationProbe({ sink }: { sink: { current: RouterLocation } }) {
  const location = useLocation();
  sink.current = {
    pathname: location.pathname,
    search: location.search,
    hash: location.hash,
    href: `${location.pathname}${location.search}${location.hash}`,
  };
  return null;
}

const NO_LOCATION: RouterLocation = { pathname: '', search: '', hash: '', href: '' };

/**
 * Monta la app completa (rutas `/login` y `/trading`) con el mismo anidamiento que
 * `src/main.tsx` — `SessionProvider` por fuera del router —, cambiando `BrowserRouter` por
 * `MemoryRouter` e inyectando el `fetch` del test. Junto a `<App />` va una sonda que
 * expone la ubicación del router (`location()` del resultado).
 */
export function renderApp(options: RenderAppOptions): RenderedApp {
  const sink = { current: NO_LOCATION };
  const result = render(
    <SessionProvider baseUrl={options.baseUrl ?? BASE_URL} fetchImpl={options.fetchImpl}>
      <MemoryRouter initialEntries={options.initialEntries ?? [LOGIN_ROUTE]}>
        <App />
        <LocationProbe sink={sink} />
      </MemoryRouter>
    </SessionProvider>,
  );
  return Object.assign(result, { location: () => sink.current });
}

