/** Limpieza del DOM y del almacenamiento entre tests, más las guardas globales de la suite. */
import { afterEach } from 'vitest';
import { cleanup } from '@testing-library/react';
import { takeUnexpectedFetchCalls } from './support';

declare global {
  /**
   * Bandera que React 19 consulta para habilitar `act(...)`. Sin ella, cada actualización
   * de estado envuelta en `act` emite la advertencia "The current testing environment is
   * not configured to support act(...)".
   */
  // eslint-disable-next-line no-var
  var IS_REACT_ACT_ENVIRONMENT: boolean;
}

globalThis.IS_REACT_ACT_ENVIRONMENT = true;

afterEach(() => {
  cleanup();
  try {
    globalThis.localStorage?.clear();
  } catch {
    /* sin almacenamiento disponible */
  }
  // Una llamada a una ruta sin handler declarado no puede pasar inadvertida: el
  // `ApiClient` la convertiría en un `NetworkError` (RN-8) y el test seguiría en verde.
  const unexpected = takeUnexpectedFetchCalls();
  if (unexpected.length > 0) {
    throw new Error(
      `El test hizo ${unexpected.length} llamada(s) a rutas que no mockeó:\n  - ` +
        unexpected.join('\n  - '),
    );
  }
});

