it('AT-10-01-02b: email existente con contraseña incorrecta ⇒ salida indistinguible del caso 02a (mismo code)', async () => {
  // Las dos situaciones difieren de verdad: un email que **no** corresponde a ninguna
  // cuenta contra el email que el resto de la suite trata como existente (`CREDENTIALS`),
  // y con el `message` que un servidor podría mandar en cada caso. El `code` es el mismo,
  // que es lo único que el cliente puede (y debe) mirar.
  const inexistente = await attemptRejectedLogin(
    'no-existe@example.com',
    'Credenciales inválidas.',
  );
  cleanup();
  globalThis.localStorage.clear();
  const passwordIncorrecta = await attemptRejectedLogin(
    CREDENTIALS.email,
    'Password incorrecta para la cuenta acc_0001.',
  );

  expect(passwordIncorrecta.errorText).toBe('Email o contraseña incorrectos');
  expect(passwordIncorrecta.passwordValue).toBe('');
  expect(passwordIncorrecta.emailValue).toBe(CREDENTIALS.email);
  expect(passwordIncorrecta.onLogin).toBe(true);
  expect(passwordIncorrecta.onTrading).toBe(false);

  // La evidencia de que no se revela si el email existe: todo lo observable coincide con
  // el caso 02a salvo el email tipeado, que legítimamente es otro (RN-4 + RN-10).
  const { emailValue: _tipeadoA, ...salidaInexistente } = inexistente;
  const { emailValue: _tipeadoB, ...salidaPasswordIncorrecta } = passwordIncorrecta;
  expect(salidaPasswordIncorrecta).toEqual(salidaInexistente);
});

