it('RN-7: el aviso de sesión expirada se descarta al reenviar credenciales (aunque el nuevo intento falle)', async () => {
  const gate = deferred<Response>();
  let loginAttempts = 0;
  const fetchMock = createFetchMock({
    login: () => {
      loginAttempts += 1;
      // Primer intento: sesión establecida. Segundo: rechazado, para que el aviso no
      // desaparezca "de rebote" por navegar a trading.
      if (loginAttempts === 1) return loginOk()();
      return errorResponse(401, 'INVALID_CREDENTIALS', 'Credenciales inválidas.');
    },
    me: () => gate.promise,
