/** Forma mínima de una ubicación, tal como la reportan `useLocation()` y el `history`. */
interface LocationLike {
  pathname: string;
  search: string;
  hash: string;
}

/** El `history` del router expone `listen`, aunque el tipo público del navigator no lo declare. */
interface Listenable {
  listen(listener: (update: { location: LocationLike }) => void): () => void;
}

function toRouterLocation(location: LocationLike): RouterLocation {
  return {
    pathname: location.pathname,
    search: location.search,
    hash: location.hash,
    href: `${location.pathname}${location.search}${location.hash}`,
  };
}

/**
 * Sonda de ubicación: no renderiza nada, sólo publica la ubicación del router para que el
 * test pueda leerla sin alterar el DOM de la app.
 *
 * Además de la ubicación renderizada (`useLocation()`), se escucha el `history` del router:
 * una navegación que React descarta enseguida (porque otra actualización la superpone) no
 * llega a renderizarse, pero igual ocurrió y el navegador la habría mostrado en la barra de
 * direcciones. Para RN-3/RNE-4 —"el token no aparece en la URL"— cuenta.
 */
function LocationProbe({ sink }: { sink: LocationSink }) {
  const location = useLocation();
  const navigation = useContext(UNSAFE_NavigationContext);

  const record = (visited: RouterLocation) => {
    if (sink.history[sink.history.length - 1]?.href !== visited.href) sink.history.push(visited);
  };

  sink.current = toRouterLocation(location);
  record(sink.current);

  useEffect(() => {
    const history = navigation.navigator as unknown as Listenable;
    return history.listen((update) => record(toRouterLocation(update.location)));
  });

  return null;
}

