export interface RenderAppOptions {
  fetchImpl: FetchLike;
  /** Ruta inicial del router en memoria. Por defecto, la pantalla de login. */
  initialEntries?: string[];
  baseUrl?: string;
}

/** Ubicación del router en memoria: lo que el navegador mostraría en la barra de direcciones. */
export interface RouterLocation {
  pathname: string;
  search: string;
  hash: string;
  /** `pathname + search + hash`, o sea la URL completa relativa al origen. */
  href: string;
}

export interface RenderedApp extends RenderResult {
  /**
   * Ubicación actual del router. Es la única forma de afirmar sobre "la URL" en esta suite:
   * `MemoryRouter` no escribe en `window.location` (en jsdom `search`/`hash` son siempre
   * `''`, con lo que afirmar sobre ellos no verificaría nada).
   */
  location(): RouterLocation;
  /** Todas las ubicaciones por las que pasó el router, en orden y sin repetir consecutivas. */
  locations(): RouterLocation[];
}

interface LocationSink {
  current: RouterLocation;
  history: RouterLocation[];
}

/** Forma mínima de una ubicación, tal como la reportan `useLocation()` y el `history`. */
interface LocationLike {
  pathname: string;
  search: string;
  hash: string;
}

/** El `navigator` del router (su `history`): lo que ejecuta cada navegación pedida. */
interface NavigatorLike {
  push(to: string | Partial<LocationLike>, state?: unknown): void;
  replace(to: string | Partial<LocationLike>, state?: unknown): void;
}

function toRouterLocation(location: Partial<LocationLike>): RouterLocation {
  const pathname = location.pathname ?? '';
  const search = location.search ?? '';
  const hash = location.hash ?? '';
  return { pathname, search, hash, href: `${pathname}${search}${hash}` };
}

function destination(to: string | Partial<LocationLike>): RouterLocation {
  return toRouterLocation(typeof to === 'string' ? parsePath(to) : to);
}

/**
 * Sonda de ubicación: no renderiza nada, sólo publica la ubicación del router para que el
 * test pueda leerla sin alterar el DOM de la app.
 *
 * Además de la ubicación renderizada (`useLocation()`), se anotan los destinos que la app
 * le **pide** al router: una navegación que React descarta enseguida (porque otra
 * actualización la superpone) no llega a renderizarse, pero con `BrowserRouter` el
 * navegador ya la habría escrito en la barra de direcciones. Para RN-3/RNE-4 —"el token no
 * aparece en la URL"— cuenta igual.
 */
function LocationProbe({ sink }: { sink: LocationSink }) {
  const location = useLocation();
  const navigation = useContext(UNSAFE_NavigationContext);

  const record = (visited: RouterLocation) => {
    if (sink.history[sink.history.length - 1]?.href !== visited.href) sink.history.push(visited);
  };

  sink.current = toRouterLocation(location);
  record(sink.current);

  useEffect(() => {
    // Se envuelven `push`/`replace` en lugar de usar `listen`: el `history` del router
    // admite un único listener y es suyo, así que escucharlo lo dejaría sin navegación.
    const navigator = navigation.navigator as unknown as NavigatorLike;
    const original = { push: navigator.push, replace: navigator.replace };
    navigator.push = (to, state) => {
      record(destination(to));
      original.push.call(navigator, to, state);
    };
    navigator.replace = (to, state) => {
      record(destination(to));
      original.replace.call(navigator, to, state);
    };
    return () => {
      navigator.push = original.push;
      navigator.replace = original.replace;
    };
  }, [navigation]);

